/** Module CRUD chuẩn — map 1:1 thư mục `src/modules/{id}` trong package. */
export type AdminModuleId = string

export type AdminAppMenuConfig = {
  /** Href gốc main backend (vd. `/staff`) — luôn include khi module bật. */
