  excludeHrefs?: string[]
  hrefOverrides?: Record<string, string>
  nativeGroups?: Array<
    AdminMenuTreeItemData & {
      insertAfter?: string
      replaceLabel?: string
    }
  >
  appendToGroup?: Record<string, AdminMenuTreeItemData[]>
}

export type AdminNativeRoutePreserve = {
  /** Đường dẫn tương đối dưới `basePath` — không generate từ package (vd. `dormitory-checkin`). */
  paths: string[]
}

export type AdminAppConfig = {
  /** Định danh deploy (vd. `hub-main`, `hub-checkin`). */
  id: string
  /** Prefix route Next (main: `""`, deploy line: `/admin`, `/manage`, …). */
  basePath: "" | `/${string}`
  title: string
  /** Module CRUD bật — render + menu tự lọc. */
