import type { AdminAppConfig } from "../config/types"
import { resolveAdminDashboardDir } from "../config/admin-access-paths"
import type {
  AdminMenuLeafData,
  AdminMenuTreeItemData,
} from "./admin-menu-tree.items"
import { BACKEND_ADMIN_MENU_ITEMS } from "./admin-menu-tree.items"

function normalizeMenuLabel(label: string): string {
  return String(label)
    .normalize("NFC")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase()
}

function stripNativeMeta(
  native: AdminMenuTreeItemData & { insertAfter?: string; replaceLabel?: string },
): AdminMenuTreeItemData {
  const { insertAfter: _a, replaceLabel: _b, ...group } = native
  return group
}

function findNativeReplacement(
  label: string,
  nativeGroups: NonNullable<AdminAppConfig["menu"]>["nativeGroups"],
) {
  const norm = normalizeMenuLabel(label)
  for (const raw of nativeGroups ?? []) {
    if (raw.replaceLabel && normalizeMenuLabel(raw.replaceLabel) === norm) {
      return stripNativeMeta(raw)
    }
  }
  return null
}

function moduleToHref(mod: string): string {
  if (mod === "file-storage") return "/file-storage"
  return `/${mod}`
}

function buildIncludeHrefs(config: AdminAppConfig): Set<string> {
  const hrefs = new Set(config.menu?.alwaysIncludeHrefs ?? ["/", "/events"])
  for (const mod of config.modules ?? []) {
    hrefs.add(moduleToHref(mod))
  }
  for (const ex of config.menu?.excludeHrefs ?? []) {
    hrefs.delete(ex)
  }
  return hrefs
}

function resolveHrefOverride(override: string, config: AdminAppConfig): string {
  const base = (config.basePath ?? "").replace(/\/$/, "")
  if (override === "@root" || override === ".") {
    return base ? `/${base}` : "/"
  }
  if (override.startsWith("/")) {
    return override
  }
  const segment = override.replace(/^\/+/, "")
  return base ? `/${base}/${segment}` : `/${segment}`
}

function remapHrefForConfig(
  href: string,
  config: AdminAppConfig,
  overrides: Record<string, string>,
) {
  if (Object.prototype.hasOwnProperty.call(overrides, href)) {
    return resolveHrefOverride(overrides[href]!, config)
  }
  const basePath = config.basePath ?? ""
  if (href === "/") {
    const rel = resolveAdminDashboardDir(config.dashboard?.relativePath)
    const prefix = basePath.replace(/\/$/, "")
    return prefix ? `${prefix}/${rel}` : `/${rel}`
  }
  const prefix = basePath.replace(/\/$/, "")
  return prefix ? `${prefix}${href}` : href
}

function remapNativeMenuHref(
  href: string,
  config: AdminAppConfig,
  overrides: Record<string, string>,
): string {
  if (!href.startsWith("/")) {
    const base = (config.basePath ?? "").replace(/\/$/, "")
    const segment = href.replace(/^\/+/, "")
    return base ? `/${base}/${segment}` : `/${segment}`
  }
  const base = (config.basePath ?? "").replace(/\/$/, "")
  if (base && (href === `/${base}` || href.startsWith(`/${base}/`))) {
    return href
  }
  return remapHrefForConfig(href, config, overrides)
}

function remapNativeGroup(
  group: AdminMenuTreeItemData,
  config: AdminAppConfig,
  overrides: Record<string, string>,
): AdminMenuTreeItemData {
  if (group.type !== "group") return group
  return {
    ...group,
    children: group.children.map((c) => ({
      ...c,
      href: remapNativeMenuHref(c.href, config, overrides),
    })),
  }
}

function flattenMenuLeaves(items: AdminMenuTreeItemData[]): AdminMenuLeafData[] {
  const out: AdminMenuLeafData[] = []
  for (const entry of items) {
    if (entry.type === "leaf") {
      const { type: _type, ...leaf } = entry
      out.push(leaf)
      continue
    }
    out.push(...entry.children)
  }
  return out
}

function applyAppendToGroup(
  menu: AdminMenuTreeItemData[],
  config: AdminAppConfig,
): AdminMenuTreeItemData[] {
  const appendToGroup = config.menu?.appendToGroup ?? {}
  return menu.map((item) => {
    if (item.type !== "group") return item
    const extra = appendToGroup[item.label]
    if (!extra?.length) return item
    return {
      ...item,
      children: [...item.children, ...flattenMenuLeaves(extra)],
    }
  })
}

/** Lọc menu gốc main theo module bật + remap href theo `basePath`. */
export function buildAdminMenuFromConfig(
  config: AdminAppConfig,
  source: AdminMenuTreeItemData[] = BACKEND_ADMIN_MENU_ITEMS,
): AdminMenuTreeItemData[] {
  const includeHrefs = buildIncludeHrefs(config)
  const overrides = config.menu?.hrefOverrides ?? {}
  const nativeGroups = config.menu?.nativeGroups ?? []
  const out: AdminMenuTreeItemData[] = []

  for (const item of source) {
    if (item.type === "leaf") {
      if (!includeHrefs.has(item.href)) continue
      out.push({
        ...item,
        href: remapHrefForConfig(item.href, config, overrides),
      })
      continue
    }

    const replacement = findNativeReplacement(item.label, nativeGroups)
    if (replacement) {
      out.push(remapNativeGroup(replacement, config, overrides))
      continue
    }

    const children = item.children
      .filter((c: AdminMenuLeafData) => includeHrefs.has(c.href))
      .map((c) => ({
        ...c,
        href: remapHrefForConfig(c.href, config, overrides),
      }))
    if (children.length === 0) continue
    out.push({ ...item, children })
  }

  return applyAppendToGroup(out, config)
}

src/modules/academic-years/new/page.tsx.content:
"use client"
import { api } from "@workspace/admin-app/lib/api"
import { useAdminModuleNavigation } from "@workspace/admin-app/runtime"
import { useCallback } from "react"
import { useQueryClient } from "@tanstack/react-query"
import { AdminPageGuard, AdminPageSection } from "@ui/components/admin"
import {
  AcademicYearFormShell,
  useAcademicYearForm,
  buildAcademicYearPayload,
} from "../_component"
import type { AcademicYearFormValues } from "../_component"

import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
function NewAcademicYearPageInner() {
  const crudNav = useAdminModuleNavigation("academic-years")
  const queryClient = useQueryClient()
  const { form } = useAcademicYearForm()

  const invalidateAll = async () => {
    await queryClient.invalidateQueries({ queryKey: ["academic-years"] })
  }

  const createMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: (_data, variables) =>
        `Đã tạo niên khóa "${(variables.name as string)?.trim()}"`,
      error: (err) =>
        err instanceof Error ? err.message : "Không thể tạo niên khóa",
    },
    mutationFn: async (input: Record<string, unknown>) =>
      api.academicYears.create(input),
    onSuccess: async () => {
      await invalidateAll()
      crudNav.list()
    },
  })

  const handleSubmit = useCallback(
    async (values: AcademicYearFormValues) => {
      await createMutation.mutateAsync(buildAcademicYearPayload(values))
    },
    [createMutation]
  )

  return (
    <AdminPageSection>
      <AcademicYearFormShell
        form={form}
        onSubmit={handleSubmit}
        submitting={createMutation.isPending}
        editingId={null}
        onBack={() => crudNav.list()}
        onReset={() => {
          form.reset()
        }}
      />
    </AdminPageSection>
  )
}

export default function NewAcademicYearPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <NewAcademicYearPageInner />
    </AdminPageGuard>
  )
}

