  const queryClient = useQueryClient()
  return useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: "Đã tạo yêu cầu liên hệ mới",
      error: (error) => error.message || "Không thể tạo yêu cầu liên hệ",
