"use client"

import {
  defineAdminCrudActionsColumn,
  defineAdminTrashActionsColumn,
} from "@ui/components/admin"

import type { ColumnDef } from "@tanstack/react-table"

import { UsageStatusFromValue } from "@ui/components/usage-status-badge"

import type { AdminCrudRowHandlers } from "@workspace/admin-app/lib/admin-row-action-handlers"

import {
  type AdminTableView,
  buildAdminTableColumns,
  dedupeAdminTableColumns,
  defineAdminCreatedAtColumn,
  defineAdminUpdatedAtColumn,
} from "@workspace/admin-app/lib/admin-table-columns"

import type { CourseRow } from "./types"

export function getCourseColumns({
  view = "list",

  openDetail = () => {},

  openEdit = () => {},

  rowActions,

  canWrite,

  canDelete,

  canRestore,

  canHardDelete,
}: {
  view?: AdminTableView

  openDetail?: (row: CourseRow) => void

  openEdit?: (row: CourseRow) => void

  rowActions: AdminCrudRowHandlers<CourseRow>

  canWrite: boolean

  canDelete?: boolean

  canRestore?: boolean

  canHardDelete?: boolean
}): ColumnDef<CourseRow>[] {
  const dataColumns: ColumnDef<CourseRow>[] = [
    {
      accessorKey: "name",

      header: "Tên khóa học",

      enableColumnFilter: true,
      filterFn: () => true,

      cell: ({ row, getValue }) => (
        <button
          type="button"
          className="text-left font-medium text-foreground transition-colors hover:text-primary"
          onClick={() => openDetail(row.original)}
        >
          {String(getValue())}
        </button>
      ),
    },

    {
      accessorKey: "startYear",

      header: "Năm bắt đầu",

      cell: ({ getValue }) => {
        const val = getValue() as number | null

        return <span className="text-sm">{val ?? "—"}</span>
      },
    },

    {
      accessorKey: "endYear",

      header: "Năm kết thúc",

      cell: ({ getValue }) => {
        const val = getValue() as number | null

        return <span className="text-sm">{val ?? "—"}</span>
      },
    },

    {
      accessorKey: "departmentId",

      header: "Phòng/Khoa (ID)",

      meta: { defaultHidden: true },

      cell: ({ getValue }) => {
        const val = getValue() as number | null

        return (
          <span className="font-mono text-xs text-muted-foreground">
            {val ?? "—"}
          </span>
        )
      },
    },

    defineAdminCreatedAtColumn<CourseRow>({ defaultHidden: true }),

    {
      accessorKey: "status",

      header: "Trạng thái",

      enableColumnFilter: true,

      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true

        return String(row.getValue(columnId)) === String(filterValue)
      },

      meta: {
        filterVariant: "select",

        selectOptions: [
          { value: "1", label: "Hoạt động" },

          { value: "0", label: "Tắt" },
        ],
      },

      cell: ({ getValue }) => (
        <UsageStatusFromValue
          value={getValue() as number}
          labels={{ active: "Hoạt động", locked: "Tắt" }}
          className="text-[10px]"
        />
      ),
    },

    defineAdminUpdatedAtColumn<CourseRow>({ header: "Cập nhật" }),
  ]

  return dedupeAdminTableColumns(
    buildAdminTableColumns({
      view,

      dataColumns,

      listActionsColumn: defineAdminCrudActionsColumn<CourseRow>({
        canWrite,

        canDelete,

        canHardDelete,

        onView: openDetail,

        onEdit: openEdit,

        onSoftDelete: rowActions.onSoftDelete,

        onPurge: rowActions.onPurge,

        getRecordLabel: rowActions.getRecordLabel,
      }),

      trashActionsColumn: defineAdminTrashActionsColumn<CourseRow>({
        canWrite,

        canRestore,

        canHardDelete,

        onRestore: rowActions.onRestore,

        onPurge: rowActions.onPurge,

        getRecordLabel: rowActions.getRecordLabel,
      }),
    })
  )
}

