  submitting,
  editingId,
  onBack,
  onReset,
}: CourseFormShellProps) {
  const { control } = form

  return (
    <>
      <AdminFormPageHeader
        title={editingId ? "Chỉnh sửa khóa học" : "Tạo khóa học mới"}
