                  <FormFieldCol label="Mã khoa">
                    <Input
                      placeholder="VD: P.CNTT"
                      {...field}
                      value={field.value ?? ""}
                      className={cn(
                        "font-mono text-sm",
                        fieldState.error && "border-destructive"
                      )}
                    />
                    {fieldState.error && (
                      <FieldError>{fieldState.error.message}</FieldError>
                    )}
                  </FormFieldCol>
                )}
