/** Thời gian từng bảng / lô HTTP — phục vụ báo cáo và tối ưu import. */

export type ImportModelTimingStats = {
  /** Thời gian wall-clock từ lô đầu → lô cuối của bảng. */
  wallMs: number
  /** Tổng thời gian chờ HTTP (cộng dồn các lô). */
  httpMs: number
  /** Tổng thời gian xử lý server (từ API `timing.models`, nếu có). */
  serverInsertMs: number
  serverClearMs: number
  httpJobCount: number
  records: number
  startedAtMs?: number
  completedAtMs?: number
}

export type ImportJobTimingEntry = {
  label: string
  primaryModel: string
  bundledModels: string[]
  recordCount: number
  httpMs: number
  serverRequestMs?: number
}

export function createEmptyModelTiming(
  records: number
): ImportModelTimingStats {
  return {
    wallMs: 0,
    httpMs: 0,
    serverInsertMs: 0,
    serverClearMs: 0,
    httpJobCount: 0,
    records,
  }
}

export function formatImportDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return "—"
  if (ms < 1000) return `${Math.round(ms)}ms`
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`
  const minutes = Math.floor(ms / 60_000)
  const seconds = Math.round((ms % 60_000) / 1000)
  return seconds > 0 ? `${minutes}m ${seconds}s` : `${minutes}m`
}

export function formatImportThroughput(
  records: number,
  durationMs: number
): string {
  if (!Number.isFinite(durationMs) || durationMs <= 0 || records <= 0) {
    return "—"
  }
  const perSec = records / (durationMs / 1000)
  if (perSec >= 100)
    return `${Math.round(perSec).toLocaleString("vi-VN")} bản ghi/s`
  if (perSec >= 10) return `${perSec.toFixed(1)} bản ghi/s`
  return `${perSec.toFixed(2)} bản ghi/s`
}

export function formatModelTimingSummary(
  stats: ImportModelTimingStats
): string {
  const serverWorkMs = stats.serverInsertMs + stats.serverClearMs
  const bundleWaitMs =
    stats.wallMs > serverWorkMs + 100 ? stats.wallMs - serverWorkMs : 0
  /** Bảng pivot trong bundle: throughput theo insert thực, không theo wall chờ bảng cha. */
  const throughputMs =
    bundleWaitMs >= 500 && stats.serverInsertMs > 0
      ? Math.max(stats.serverInsertMs, 1)
      : stats.wallMs

  const parts: string[] = [formatImportDuration(stats.wallMs)]
  const throughput = formatImportThroughput(stats.records, throughputMs)
  if (throughput !== "—") parts.push(throughput)
  if (stats.httpJobCount > 1) {
    parts.push(`${stats.httpJobCount} lô HTTP`)
  }
  if (stats.serverInsertMs > 0) {
    parts.push(`insert server ${formatImportDuration(stats.serverInsertMs)}`)
  }
  if (stats.serverClearMs > 0) {
    parts.push(`clear ${formatImportDuration(stats.serverClearMs)}`)
  }
  if (bundleWaitMs >= 500) {
    parts.push(`chờ bundle ${formatImportDuration(bundleWaitMs)}`)
  }
  if (stats.httpMs > 0 && stats.httpJobCount > 1) {
    const parallelOverlap =
      stats.httpMs > stats.wallMs + 100 && stats.httpJobCount > 1
    if (parallelOverlap) {
      parts.push(
        `HTTP cộng dồn ${formatImportDuration(stats.httpMs)} (song song)`
      )
    } else if (Math.abs(stats.httpMs - stats.wallMs) > 50) {
      parts.push(`HTTP thuần ${formatImportDuration(stats.httpMs)}`)
    }
  }
  return parts.join(" · ")
}

src/modules/data/_component/system-opera.content:
import { toast } from "@ui/components/sonner"
import type {
  DatabaseSchemaResponse,
  SystemBootstrapResult,
} from "@workspace/api-client"
import { formatEntityRowCount } from "./utils"

export async function copyTextToClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    try {
      const textarea = document.createElement("textarea")
      textarea.value = text
      textarea.setAttribute("readonly", "")
      textarea.style.position = "fixed"
      textarea.style.left = "-9999px"
      document.body.appendChild(textarea)
      textarea.select()
      const ok = document.execCommand("copy")
      document.body.removeChild(textarea)
      return ok
    } catch {
      return false
    }
  }
}

export function toastSystemOperationResult(options: {
  success: boolean
  title: string
  description?: string
}) {
  if (options.success) {
    toast.success(options.title, {
      description: options.description,
    })
    return
  }
  toast.error(options.title, {
    description: options.description,
  })
}

export function buildSeedBootstrapReport(
  result: SystemBootstrapResult
): string {
  const lines = [
    "=== Kết quả seed hệ thống ===",
    `Roles: +${result.rolesInserted}, cập nhật ${result.rolesUpdated}, bỏ qua ${result.rolesSkipped}`,
    `Users: +${result.usersInserted}, cập nhật ${result.usersUpdated}, bỏ qua ${result.usersSkipped}`,
    `User roles: +${result.userRolesInserted}, đã có ${result.userRolesSkipped}`,
    `Page contents: +${result.pageContentsInserted}, đã có ${result.pageContentsSkipped}`,
  ]
  return lines.join("\n")
}

export function buildDatabaseVerificationReport(
  schema: DatabaseSchemaResponse
): string {
  const lines = [
    "=== Kiểm tra cơ sở dữ liệu sau thao tác ===",
    `Tổng bảng: ${schema.tables.length}`,
    `Tổng quan hệ FK: ${schema.relations.length}`,
    `Tổng bản ghi active: ${formatEntityRowCount(schema.totalActiveRows)}`,
    `Tổng bản ghi database: ${formatEntityRowCount(schema.totalRows)}`,
  ]

  if (schema.verification) {
    lines.push(
      "",
      "=== Đối chiếu manifest import ===",
      `Nguồn: ${schema.verification.referenceSource}`,
      `Exported at: ${schema.verification.referenceExportedAt}`,
      `Trạng thái: ${schema.verification.isComplete ? "Khớp" : "Chưa khớp"}`,
      `Bảng khớp: ${schema.verification.matchedModels}`,
      `Bảng lệch: ${schema.verification.mismatchedModels}`,
      `Bản ghi nghiệp vụ: ${formatEntityRowCount(
        schema.verification.actualBusinessTotalRows
      )} / ${formatEntityRowCount(
        schema.verification.expectedBusinessTotalRows
      )}`
    )

    const mismatches = schema.verification.models.filter(
      (model) => model.status !== "ok"
    )
    if (mismatches.length > 0) {
      lines.push("", "=== Bảng lệch ===")
      for (const model of mismatches) {
        lines.push(
          `- ${model.exportModelName}: actual ${formatEntityRowCount(
            model.actual
          )} / expected ${formatEntityRowCount(model.expected)} (${model.status})${model.note ? ` — ${model.note}` : ""}`
        )
      }
    }
  } else {
    lines.push("", "Không có manifest import để đối chiếu.")
  }

  return lines.join("\n")
}

"use client"

import { useMemo, useState } from "react"
import { toast } from "@ui/components/sonner"
import { Button } from "@ui/components/button"
import { Badge } from "@ui/components/badge"
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert"
import {
  FieldDescription,
  FieldSectionLegend,
  FieldSectionValue,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import { api } from "@workspace/admin-app/lib/api"
import type {
  DatabaseSchemaResponse,
  SystemBootstrapResult,
} from "@workspace/api-client"
import {
  Check,
  ClipboardCheck,
  Copy,
  DatabaseZap,
  Loader2,
  RefreshCcw,
  ShieldCheck,
} from "lucide-react"
import {
  buildDatabaseVerificationReport,
  buildSeedBootstrapReport,
  copyTextToClipboard,
  toastSystemOperationResult,
} from "./system-operation-result"
import { formatEntityRowCount } from "./utils"

type OperationStatus = "idle" | "running" | "done" | "error"

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "Thao tác hệ thống thất bại."
}

function buildFullOperationReport(options: {
  seedResult?: SystemBootstrapResult
  schema?: DatabaseSchemaResponse
  error?: string
}): string {
  const parts: string[] = []
  if (options.seedResult) {
    parts.push(buildSeedBootstrapReport(options.seedResult))
  }
  if (options.schema) {
    if (parts.length) parts.push("")
    parts.push(buildDatabaseVerificationReport(options.schema))
  }
  if (options.error) {
    if (parts.length) parts.push("")
    parts.push("=== Lỗi thao tác ===", options.error)
  }
  return parts.join("\n")
}

export function SystemOperationsPanel() {
  const [status, setStatus] = useState<OperationStatus>("idle")
  const [seedResult, setSeedResult] = useState<SystemBootstrapResult | null>(
    null
  )
  const [verifiedSchema, setVerifiedSchema] =
    useState<DatabaseSchemaResponse | null>(null)
  const [message, setMessage] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)

  const reportText = useMemo(
    () =>
      buildFullOperationReport({
        seedResult: seedResult ?? undefined,
        schema: verifiedSchema ?? undefined,
        error: status === "error" ? (message ?? undefined) : undefined,
      }),
    [message, seedResult, status, verifiedSchema]
  )

  const runSeedAndVerify = async () => {
    setStatus("running")
    setMessage("Đang chạy seed hệ thống…")
    setSeedResult(null)
    setVerifiedSchema(null)
    try {
      const result = await api.system.runSeedBootstrap()
      setSeedResult(result)
      toastSystemOperationResult({
        success: true,
        title: "Seed hệ thống hoàn tất",
        description: "Đang kiểm tra lại cơ sở dữ liệu sau seed.",
      })

      setMessage("Đang kiểm tra cơ sở dữ liệu sau seed…")
      const schema = await api.system.getDatabaseSchema()
      setVerifiedSchema(schema)
      setStatus("done")
      const isComplete = schema.verification?.isComplete
      const summary =
        schema.verification == null
          ? `${schema.tables.length} bảng, ${formatEntityRowCount(schema.totalActiveRows)} bản ghi active.`
          : isComplete
            ? `Khớp manifest: ${schema.verification.matchedModels} bảng.`
            : `Chưa khớp manifest: ${schema.verification.mismatchedModels} bảng lệch.`
      setMessage(summary)
      toastSystemOperationResult({
        success: schema.verification?.isComplete !== false,
        title:
          schema.verification?.isComplete === false
            ? "Seed xong nhưng dữ liệu chưa khớp"
            : "Seed xong và DB đã được kiểm tra",
        description: summary,
      })
    } catch (error) {
      const errorMessage = getErrorMessage(error)
      setStatus("error")
      setMessage(errorMessage)
      toastSystemOperationResult({
        success: false,
        title: "Thao tác hệ thống thất bại",
        description: errorMessage,
      })
    }
  }

  const copyReport = async () => {
    if (!reportText.trim()) {
      toast.error("Chưa có kết quả thao tác để copy.")
      return
    }
    const ok = await copyTextToClipboard(reportText)
    if (!ok) {
      toast.error("Không copy được — thử chọn và copy thủ công.")
      return
    }
    setCopied(true)
    toast.success("Đã copy kết quả chi tiết.")
    window.setTimeout(() => setCopied(false), 2000)
  }

  const busy = status === "running"
  const hasResult = Boolean(reportText.trim())
  const verification = verifiedSchema?.verification

  return (
    <FieldSet variant="section">
      <FieldSectionLegend
        icon={DatabaseZap}
        title="Thao tác hệ thống"
        description="Chạy seed bootstrap, kiểm tra DB sau thao tác và copy báo cáo chi tiết."
        badge={
          status === "done" ? (
            <Badge variant="outline" className="text-xs font-normal">
              Đã kiểm tra DB
            </Badge>
          ) : status === "error" ? (
            <Badge variant="destructive" className="text-xs font-normal">
              Có lỗi
            </Badge>
          ) : undefined
        }
      />
      <FieldSetContent
        variant="section"
        className="space-y-3 px-4 pt-0 pb-4 sm:px-5"
      >
        <FieldDescription className="text-xs">
          Dùng sau deploy hoặc sau `db:fresh`: chạy lại superadmin/role/page
          contents seed, sau đó đọc `/database-schema` để xác nhận dữ liệu thật
          trong database.
        </FieldDescription>

        <FieldSectionValue className="flex flex-wrap items-center gap-2 px-4 py-3">
          <Button
            type="button"
            size="sm"
            className="h-8 gap-1.5"
            disabled={busy}
            onClick={() => void runSeedAndVerify()}
          >
            {busy ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <ShieldCheck className="size-3.5" />
            )}
            Chạy seed + kiểm tra DB
          </Button>
          <Button
            type="button"
            size="sm"
            variant="outline"
            className="h-8 gap-1.5"
            disabled={busy || !hasResult}
            onClick={() => void copyReport()}
          >
            {copied ? (
              <Check className="size-3.5" />
            ) : (
              <Copy className="size-3.5" />
            )}
            {copied ? "Đã copy" : "Copy kết quả chi tiết"}
          </Button>
          {verifiedSchema ? (
            <Badge variant="secondary" className="text-xs font-normal">
              {verifiedSchema.tables.length} bảng ·{" "}
              {formatEntityRowCount(verifiedSchema.totalActiveRows)} bản ghi
            </Badge>
          ) : null}
        </FieldSectionValue>

        {message ? (
          <Alert
            variant={status === "error" ? "destructive" : "default"}
            className="py-3"
          >
            <AlertTitle className="flex items-center gap-2 text-sm">
              {status === "running" ? (
                <RefreshCcw className="size-4 animate-spin" />
              ) : status === "done" ? (
                <ClipboardCheck className="size-4" />
              ) : null}
              {status === "running"
                ? "Đang xử lý"
                : status === "error"
                  ? "Thao tác lỗi"
                  : "Kết quả thao tác"}
            </AlertTitle>
            <AlertDescription className="text-xs">{message}</AlertDescription>
          </Alert>
        ) : null}

        {seedResult ? (
          <div className="grid gap-2 text-xs sm:grid-cols-2 lg:grid-cols-4">
            {[
              ["Roles", seedResult.rolesInserted, seedResult.rolesUpdated],
              ["Users", seedResult.usersInserted, seedResult.usersUpdated],
              [
                "User roles",
                seedResult.userRolesInserted,
                seedResult.userRolesSkipped,
              ],
              [
                "Page contents",
                seedResult.pageContentsInserted,
                seedResult.pageContentsSkipped,
              ],
            ].map(([label, primary, secondary]) => (
              <div
                key={label}
                className="rounded-md border bg-background/60 px-3 py-2"
              >
                <p className="font-medium">{label}</p>
                <p className="text-muted-foreground">
                  +{primary} · {secondary}{" "}
                  {label === "User roles" || label === "Page contents"
                    ? "đã có"
                    : "cập nhật"}
                </p>
              </div>
            ))}
          </div>
        ) : null}

        {verification ? (
          <div
            className={cn(
              "rounded-md border px-3 py-2 text-xs",
              verification.isComplete
                ? "border-emerald-200 bg-emerald-50 text-emerald-800 dark:border-emerald-900 dark:bg-emerald-950/20 dark:text-emerald-300"
                : "border-amber-200 bg-amber-50 text-amber-800 dark:border-amber-900 dark:bg-amber-950/20 dark:text-amber-300"
            )}
          >
            <p className="font-medium">
              {verification.isComplete
                ? "DB khớp manifest import"
                : "DB chưa khớp manifest import"}
            </p>
            <p>
              {verification.matchedModels}/
              {verification.matchedModels + verification.mismatchedModels} bảng
              khớp ·{" "}
              {formatEntityRowCount(verification.actualBusinessTotalRows)} /{" "}
              {formatEntityRowCount(verification.expectedBusinessTotalRows)} bản
              ghi nghiệp vụ.
            </p>
          </div>
        ) : null}
      </FieldSetContent>
    </FieldSet>
  )
}

