"use client"
import { api } from "@workspace/admin-app/lib/api"
import { useAdminModuleNavigation } from "@workspace/admin-app/runtime"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@workspace/admin-app/lib/fetch-all-admin-list"

import { useCallback, useEffect, useRef, useState } from "react"
import {
  buildEntityDraftKey,
  loadEntityDraft,
} from "@workspace/query-client"
import { useParams } from "next/navigation"
import { useQueryClient } from "@tanstack/react-query"
import { toast } from "@ui/components/sonner"
import {
  AdminPageGuard,
  AdminPageSection,
  AdminPageLoading,
} from "@ui/components/admin"
import {
  EventFormShell,
  useEventForm,
  useEventDetailQuery,
} from "../../_component"
import { buildEventSubmitPayload } from "@workspace/admin-app/lib/build-event-submit-payload"
import { getPosterUrlFromValue } from "../../_component/utils"
import type {
  EventDetail,
  EventFormValues,
  EventFormSpeaker,
} from "../../_component"

import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { useAdminFormDraftPersistence } from "@workspace/admin-app/hooks/use-admin-edit-form-hydration"
function toDatetimeLocal(value: string | null | undefined): string {
  if (!value) return ""
  const d = new Date(value)
  if (Number.isNaN(d.getTime())) return ""
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
}

function normalizeContent(value: unknown): EventFormValues["content"] {
  if (value && typeof value === "object" && "root" in value) return value
  if (typeof value === "string") {
    let parsed: unknown = null
    try {
      parsed = JSON.parse(value)
    } catch {
      parsed = null
    }
    if (parsed && typeof parsed === "object" && "root" in parsed) return parsed
  }
  return {
    root: {
      children: [
        {
          children: [],
          direction: null,
          format: "",
          indent: 0,
          type: "paragraph",
          version: 1,
        },
      ],
      direction: null,
      format: "",
      indent: 0,
      type: "root",
      version: 1,
    },
  }
}

function buildFormValues(
  entity: EventDetail,
  speakers: EventFormSpeaker[]
): EventFormValues {
  return {
    title: entity.title ?? "",
    slug: entity.slug ?? "",
    posterUrl: getPosterUrlFromValue(entity.poster),
    description: entity.description ?? "",
    startDate: toDatetimeLocal(entity.startDate),
    endDate: toDatetimeLocal(entity.endDate),
    checkinStart: toDatetimeLocal(entity.checkinStart),
    checkinEnd: toDatetimeLocal(entity.checkinEnd),
    checkoutStart: toDatetimeLocal(entity.checkoutStart),
    checkoutEnd: toDatetimeLocal(entity.checkoutEnd),
    registrationStart: toDatetimeLocal(entity.registrationStart),
    registrationEnd: toDatetimeLocal(entity.registrationEnd),
    organizer: entity.organizer ?? "",
    location: entity.location ?? "",
    address: entity.address ?? "",
    status: entity.status ?? 1,
    isFeatured: entity.isFeatured === true,
    featuredOrder: Number(entity.featuredOrder) || 0,
    allowCheckin: entity.allowCheckin ?? true,
    allowCheckout: entity.allowCheckout ?? true,
    requireFaceId: entity.requireFaceId ?? false,
    checkinCameraId: entity.checkinCameraId ?? "",
    checkoutCameraId: entity.checkoutCameraId ?? "",
    checkinHanetDeviceId: entity.checkinCameraCode ?? "",
    checkoutHanetDeviceId: entity.checkoutCameraCode ?? "",
    maxParticipants: entity.maxParticipants ?? 0,
    format: entity.format ?? 0,
    onlineLink: entity.onlineLink ?? "",
    content: normalizeContent(entity.content),
    speakers,
  }
}

function EditEventPageInner() {
  const crudNav = useAdminModuleNavigation("events")
  const params = useParams()
  const id = params.id as string
  const queryClient = useQueryClient()
  const { form } = useEventForm()
  const {
    data: entity,
    isLoading,
    isError,
    refetch,
  } = useEventDetailQuery(api, id)
  const [existingSpeakers, setExistingSpeakers] = useState<
    { id: string; speakerId: number }[]
  >([])
  const hydratedRef = useRef<string | null>(null)
  const { clearDraft } = useAdminFormDraftPersistence("events", id, form)

  useEffect(() => {
    hydratedRef.current = null
  }, [id])

  useEffect(() => {
    if (isError) {
      toast.error("Không tải được sự kiện")
      crudNav.list()
    }
  }, [isError, crudNav])

  useEffect(() => {
    if (!entity || hydratedRef.current === id) return

    const draft = loadEntityDraft<EventFormValues>(
      buildEntityDraftKey("events", id),
    )
    if (draft) {
      form.reset(draft)
      hydratedRef.current = id
      return
    }

    api.eventSpeakers
      .list<EventFormSpeaker & { id: string }>({
        eventId: id,
        limit: ADMIN_LIST_EXPORT_FETCH_LIMIT,
      })
      .then((res) => {
        const assignments = res.items.map((a) => ({
          id: a.id,
          speakerId: a.speakerId as number,
        }))
        setExistingSpeakers(assignments)
        const speakers = res.items.map((a) => ({
          speakerId: a.speakerId as number,
          role: (a.role as string) ?? undefined,
          presentationTitle: (a.presentationTitle as string) ?? undefined,
          duration: a.duration != null ? (a.duration as number) : undefined,
        }))
        form.reset(buildFormValues(entity, speakers))
      })
      .catch(() => form.reset(buildFormValues(entity, [])))
      .finally(() => {
        hydratedRef.current = id
      })
  }, [entity, form, id])

  const invalidateAll = async () => {
    await queryClient.invalidateQueries({ queryKey: ["events"] })
  }

  const updateMutation = useAdminMutation({
    toast: {
      loading: "Đang thực hiện…",
      success: (_data, variables) =>
        `Đã cập nhật sự kiện "${(variables.title as string)?.trim()}"`,
      error: (err) =>
        err instanceof Error ? err.message : "Không thể cập nhật sự kiện",
    },
    mutationFn: async (input: Record<string, unknown>) =>
      api.events.update(id, input),
    onSuccess: async () => {
      clearDraft()
      await invalidateAll()
      crudNav.view(String(id))
    },
  })

  const handleSubmit = useCallback(
    async (values: EventFormValues) => {
      await updateMutation.mutateAsync(await buildEventSubmitPayload(values))
      const newSpeakers = values.speakers ?? []
      const existingMap = new Map(existingSpeakers.map((a) => [a.speakerId, a]))
      const newIds = newSpeakers.map((s) => s.speakerId)
      const existingIds = existingSpeakers.map((a) => a.speakerId)
      const toCreate = newSpeakers.filter(
        (s) => !existingIds.includes(s.speakerId)
      )
      const toUpdate = newSpeakers.filter((s) =>
        existingIds.includes(s.speakerId)
      )
      const toRemove = existingSpeakers.filter(
        (a) => !newIds.includes(a.speakerId)
      )
      await Promise.all([
        ...toCreate.map((s) =>
          api.eventSpeakers
            .create({
              eventId: id,
              speakerId: s.speakerId,
              role: s.role?.trim() || null,
              presentationTitle: s.presentationTitle?.trim() || null,
              duration: s.duration ?? null,
            })
            .catch(() => {})
        ),
        ...toUpdate.map((s) => {
          const existing = existingMap.get(s.speakerId)
          if (!existing) return Promise.resolve()
          return api.eventSpeakers
            .update(existing.id, {
              role: s.role?.trim() || null,
              presentationTitle: s.presentationTitle?.trim() || null,
              duration: s.duration ?? null,
            })
            .catch(() => {})
        }),
        ...toRemove.map((a) => api.eventSpeakers.remove(a.id).catch(() => {})),
      ])
    },
    [updateMutation, existingSpeakers, id]
  )

  if (isLoading) return <AdminPageLoading variant="form" />
  if (!entity) return null

  return (
    <AdminPageSection>
      <EventFormShell
        form={form}
        onSubmit={handleSubmit}
        submitting={updateMutation.isPending}
        editingId={id}
        onBack={() => crudNav.view(String(id))}
        onReset={async () => {
          await refetch()
        }}
      />
    </AdminPageSection>
  )
}

export default function EditEventPage() {
  return (
    <AdminPageGuard roles={["super_admin", "admin", "manager"]}>
      <EditEventPageInner />
    </AdminPageGuard>
  )
}

src/modules/events/_component/attendance.content:
import {
  UsageStatusBadge,
  type UsageStatusTone,
} from "@ui/components/usage-status-badge"
import { LogIn, LogOut, UserRound } from "lucide-react"
import { cn } from "@ui/lib/utils"

export type AttendanceRow = {
  hasCheckin?: boolean
  hasCheckout?: boolean
}

/** Trạng thái check-in/out trên danh sách đăng ký. */
export function getAttendanceStatusLabel(row: AttendanceRow): string {
  if (row.hasCheckin && row.hasCheckout) return "Đã check-in / check-out"
  if (row.hasCheckin) return "Đã check-in"
  return "Chưa check-in"
}

function resolveAttendanceTone(row: AttendanceRow): UsageStatusTone {
  if (row.hasCheckin && row.hasCheckout) return "success"
  if (row.hasCheckin) return "warning"
  return "danger"
}

function StatusIcon({ row }: { row: AttendanceRow }) {
  if (row.hasCheckin && row.hasCheckout) {
    return (
      <span className="inline-flex items-center gap-0.5" aria-hidden>
        <LogIn className="size-3" />
        <LogOut className="size-3" />
      </span>
    )
  }
  if (row.hasCheckin) {
    return <LogIn className="size-3" aria-hidden />
  }
  return <UserRound className="size-3" aria-hidden />
}

export function AttendanceStatusBadge({ row }: { row: AttendanceRow }) {
  const tone = resolveAttendanceTone(row)
  return (
    <UsageStatusBadge tone={tone} className={cn("gap-1 text-[10px]")}>
      <StatusIcon row={row} />
      {getAttendanceStatusLabel(row)}
    </UsageStatusBadge>
  )
}

src/modules/events/_component/columns.ts.content:
"use client"

import {
  defineAdminCrudActionsColumn,
  defineAdminTrashActionsColumn,
} from "@ui/components/admin"

import type { ColumnDef } from "@tanstack/react-table"
import { Badge } from "@ui/components/badge"
import { UsageStatusFromValue } from "@ui/components/usage-status-badge"
import { Button } from "@ui/components/button"
import { Calendar, MapPin, Star } from "lucide-react"
import type { AdminCrudRowHandlers } from "@workspace/admin-app/lib/admin-row-action-handlers"
import {
  type AdminTableView,
  buildAdminTableColumns,
  defineAdminCreatedAtColumn,
  defineAdminUpdatedAtColumn,
} from "@workspace/admin-app/lib/admin-table-columns"
import type { EventRow } from "./types"
import { defineRelationExportColumns } from "@ui/components/data-table"

function formatDate(value: string | null | undefined): string {
  if (!value) return "—"
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleDateString("vi-VN")
}

export function getEventColumns({
  view = "list",
  openDetail = () => {},
  openEdit = () => {},
  rowActions,
  canWrite,
  canDelete,
  canRestore,
  canHardDelete,
  onToggleFeatured,
  isTogglingFeaturedId,
}: {
  view?: AdminTableView
  openDetail?: (row: EventRow) => void
  openEdit?: (row: EventRow) => void
  rowActions: AdminCrudRowHandlers<EventRow>
  canWrite: boolean
  canDelete?: boolean
  canRestore?: boolean
  canHardDelete?: boolean
  onToggleFeatured?: (row: EventRow) => void
  isTogglingFeaturedId?: string | null
}): ColumnDef<EventRow>[] {
  const dataColumns: ColumnDef<EventRow>[] = [
    {
      accessorKey: "title",
      header: "Sự kiện",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ row, getValue }) => (
        <button
          type="button"
          className="text-left font-medium text-foreground transition-colors hover:text-primary"
          onClick={() => openDetail(row.original)}
        >
          {String(getValue())}
        </button>
      ),
    },
    {
      accessorKey: "organizer",
      header: "Đơn vị tổ chức",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => (
        <span className="text-sm">{String(getValue() ?? "—")}</span>
      ),
    },
    {
      accessorKey: "startDate",
      header: "Bắt đầu",
      enableColumnFilter: true,
      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        const rowVal = row.getValue(columnId) as string
        if (!rowVal) return false
        const [fromStr, toStr] = String(filterValue).split(",")
        const rowDate = rowVal.split("T")[0] ?? ""
        if (fromStr && rowDate < fromStr) return false
        if (toStr && rowDate > toStr) return false
        return true
      },
      meta: { filterVariant: "date-range" },
      cell: ({ getValue }) => (
        <span className="flex items-center gap-1 text-xs text-muted-foreground">
          <Calendar className="size-3" />
          {formatDate(getValue() as string)}
        </span>
      ),
    },
    {
      accessorKey: "location",
      header: "Địa điểm",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => (
        <span className="flex items-center gap-1 text-xs text-muted-foreground">
          <MapPin className="size-3" />
          {String(getValue() ?? "—")}
        </span>
      ),
    },
    {
      accessorKey: "format",
      header: "Hình thức",
      enableColumnFilter: true,
      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        return String(row.getValue(columnId)) === String(filterValue)
      },
      meta: {
        filterVariant: "select",
        selectOptions: [
          { value: "0", label: "Offline" },
          { value: "1", label: "Online" },
          { value: "2", label: "Hybrid" },
        ],
      },
      cell: ({ getValue }) => {
        const fmt = getValue() as number
        return (
          <Badge
            variant={
              fmt === 1 ? "secondary" : fmt === 2 ? "outline" : "default"
            }
            className="text-[10px]"
          >
            {fmt === 1 ? "Online" : fmt === 2 ? "Hybrid" : "Offline"}
          </Badge>
        )
      },
    },
    {
      accessorKey: "isFeatured",
      header: "Nổi bật",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ row }) => {
        const featured = row.original.isFeatured
        const busy = isTogglingFeaturedId === row.original.id
        if (!canWrite || !onToggleFeatured) {
          return featured ? (
            <Badge className="bg-amber-500/15 text-[10px] text-amber-800 dark:text-amber-300">
              Nổi bật
            </Badge>
          ) : (
            <span className="text-xs text-muted-foreground">—</span>
          )
        }
        return (
          <Button
            type="button"
            variant={featured ? "default" : "outline"}
            size="sm"
            className="h-8 gap-1 rounded-md px-2"
            disabled={busy}
            onClick={() => onToggleFeatured(row.original)}
            title={featured ? "Bỏ đánh dấu nổi bật" : "Đánh dấu nổi bật"}
          >
            <Star className={featured ? "size-3.5 fill-current" : "size-3.5"} />
            {featured ? "Đang bật" : "Đánh dấu"}
          </Button>
        )
      },
    },
    {
      accessorKey: "status",
      header: "Trạng thái",
      enableColumnFilter: true,
      filterFn: (row, columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        return String(row.getValue(columnId)) === String(filterValue)
      },
      meta: {
        filterVariant: "select",
        selectOptions: [
          { value: "1", label: "Hoạt động" },
          { value: "0", label: "Khóa" },
        ],
      },
      cell: ({ getValue }) => (
        <UsageStatusFromValue
          value={getValue() as number}
          labels={{ active: "Hoạt động", locked: "Khóa" }}
          className="text-[10px]"
        />
      ),
    },
    ...defineRelationExportColumns<EventRow>([
      { id: "slug", header: "Slug", getValue: (r) => r.slug ?? "" },
      { id: "address", header: "Địa chỉ", getValue: (r) => r.address ?? "" },
      {
        id: "onlineLink",
        header: "Link online",
        getValue: (r) => r.onlineLink ?? "",
      },
      { id: "endDate", header: "Kết thúc", getValue: (r) => r.endDate ?? "" },
      {
        id: "createdBy",
        header: "Người tạo (ID)",
        getValue: (r) => r.createdBy ?? "",
      },
      {
        id: "checkinCamera",
        header: "Camera check-in",
        getValue: (r) =>
          r.checkinCameraName
            ? `${r.checkinCameraName}${r.checkinCameraCode ? ` (${r.checkinCameraCode})` : ""}`
            : (r.checkinCameraId ?? ""),
      },
      {
        id: "checkoutCamera",
        header: "Camera check-out",
        getValue: (r) =>
          r.checkoutCameraName
            ? `${r.checkoutCameraName}${r.checkoutCameraCode ? ` (${r.checkoutCameraCode})` : ""}`
            : (r.checkoutCameraId ?? ""),
      },
      {
        id: "totalRegistrations",
        header: "Đăng ký",
        getValue: (r) => r.totalRegistrations,
      },
      {
        id: "totalCheckins",
        header: "Check-in",
        getValue: (r) => r.totalCheckins,
      },
      {
        id: "totalCheckouts",
        header: "Check-out",
        getValue: (r) => r.totalCheckouts,
      },
      {
        id: "maxParticipants",
        header: "Sức chứa",
        getValue: (r) => r.maxParticipants,
      },
    ]),
    defineAdminCreatedAtColumn<EventRow>({ defaultHidden: true }),
    defineAdminUpdatedAtColumn<EventRow>({ defaultHidden: true }),
  ]

  return buildAdminTableColumns({
    view,
    dataColumns,
    listActionsColumn: defineAdminCrudActionsColumn<EventRow>({
      canWrite,
      canDelete,
      canHardDelete,
      onView: openDetail,
      onEdit: openEdit,
      onSoftDelete: rowActions.onSoftDelete,
      onPurge: rowActions.onPurge,
      getRecordLabel: rowActions.getRecordLabel,
    }),
    trashActionsColumn: defineAdminTrashActionsColumn<EventRow>({
      canWrite,
      canRestore,
      canHardDelete,
      onRestore: rowActions.onRestore,
      onPurge: rowActions.onPurge,
      getRecordLabel: rowActions.getRecordLabel,
    }),
  })
}

