}

src/modules/events/_component/event-regi.content:
"use client"
import { api } from "@workspace/admin-app/lib/api"
import { useEffect, useMemo, useState } from "react"
import { AlertTriangle, Radio, RefreshCw } from "lucide-react"
import { AdminDataTable } from "@ui/components/data-table"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { cn } from "@ui/lib/utils"
import { buildEventDetailXlsxExport } from "@ui/components/admin"
import { useEventRegistrationsQuery } from "./_query"
import { mergeRegistrationRowsForDisplay } from "./_live/event-attendance-sync"
import { useEventAttendanceContext } from "./_live/event-attendance-provider"
import {
  getEventRegistrationColumns,
  getEventRegistrationGlobalFilterText,
  type EventRegistrationRow,
} from "./registration-columns"

const HIGHLIGHT_MS = 4000

export function EventRegistrationsLiveTable({
  eventId,
  eventTitle,
}: {
  eventId: string
  eventTitle: string
}) {
  const { connected, socketError, lastPayload, liveRevision } =
    useEventAttendanceContext()

  const {
    data: registrations,
    isLoading,
    refetch,
    isFetching,
  } = useEventRegistrationsQuery(api, eventId, {
    enabled: true,
  })

  const displayRows = useMemo(
    () => mergeRegistrationRowsForDisplay(registrations, lastPayload),
    [registrations, lastPayload]
  )

  const [flashRegistrationId, setFlashRegistrationId] = useState<string | null>(
    null
  )

  useEffect(() => {
    if (!lastPayload?.registrationId) return
    setFlashRegistrationId(String(lastPayload.registrationId))
    const timer = window.setTimeout(
      () => setFlashRegistrationId(null),
      HIGHLIGHT_MS
    )
    return () => window.clearTimeout(timer)
  }, [lastPayload, liveRevision])

  const columns = useMemo(
    () =>
      getEventRegistrationColumns({
        eventId,
        showSocketFallback: !connected,
      }),
    [eventId, connected]
  )

  const showSocketFallback = !connected

  return (
    <AdminDataTable<EventRegistrationRow>
      data={displayRows}
      columns={columns}
      rowContextMenu
      getRowId={(row) => String(row.id ?? "")}
      isLoading={isLoading}
      emptyLabel="Chưa có đăng ký nào."
      globalFilterPlaceholder="Tìm theo email, tên, trạng thái…"
      filterColumnVisibilityKey="admin-table-filter-visibility:event-registrations"
      getGlobalFilterText={getEventRegistrationGlobalFilterText}
      getRowClassName={(row) =>
        flashRegistrationId &&
        String(row.original.id ?? "") === flashRegistrationId
          ? "ring-2 ring-inset ring-primary bg-primary/5"
          : undefined
      }
      filterToolbarExtra={
        <div className="flex flex-wrap items-center gap-2">
          {showSocketFallback ? (
            <Badge variant="destructive" className="gap-1">
              <AlertTriangle className="size-3" aria-hidden />
              {socketError ? "Socket lỗi" : "Mất realtime"}
            </Badge>
          ) : null}
          <Badge
            variant={connected ? "default" : "secondary"}
            className="gap-1"
          >
            <Radio
              className={cn("size-3", connected && "animate-pulse")}
              aria-hidden
            />
            {connected ? "Realtime" : "Đang kết nối…"}
          </Badge>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-8 gap-1"
            disabled={isFetching}
            onClick={() => void refetch()}
          >
            <RefreshCw
              className={cn("size-3.5", isFetching && "animate-spin")}
              aria-hidden
            />
            Làm mới
          </Button>
        </div>
      }
      xlsxExport={buildEventDetailXlsxExport("registrations", {
        eventId,
        eventTitle,
        pageCount: displayRows.length,
        total: displayRows.length,
      })}
      clientPagination={{
        initialPageSize: 15,
        itemLabel: "đăng ký",
        emptySummary: "Chưa có đăng ký nào",
        isLoading,
      }}
      footer={
        <span>Cập nhật khi check-in/check-out (socket hoặc thủ công).</span>
      }
    />
  )
}

src/modules/events/_component/live-activ.content:
"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { LogIn, LogOut } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { cn } from "@ui/lib/utils"
import { asAttendanceBool } from "./_live/event-attendance-sync"
import {
  RegistrationAvatarCell,
  resolveRegistrationAvatarUrl,
} from "./registration-avatar-cell"

export type EventLiveActivityKind = "checkin" | "checkout"

export type EventLiveActivityRow = {
  id: string
  kind: EventLiveActivityKind
  at: string
  email: string
  fullName: string
  avatar?: string | null
  detail?: string
}

type RegistrationDict = Record<string, unknown>

function formatDateTime(value: string | null | undefined): string {
  if (!value) return "—"
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString("vi-VN")
}

export function checkinTypeLabel(value: unknown): string {
  const v = Number(value)
  if (v === 2) return "Face ID"
  if (v === 1) return "QR Code"
  if (v === 3) return "Thủ công"
  return "—"
}

/** Luồng check-in/out từ danh sách đăng ký (cùng nguồn realtime). */
export function buildLiveActivitiesFromRegistrations(
  registrations: RegistrationDict[]
): EventLiveActivityRow[] {
  const items: EventLiveActivityRow[] = []

  for (const row of registrations) {
    const regId = String(row.id ?? "")
    const email = String(row.email ?? "")
    const fullName = String(row.fullName ?? "")

    if (asAttendanceBool(row.hasCheckin)) {
      const at = String(row.updatedAt ?? row.registeredAt ?? "")
      if (at) {
        items.push({
          id: `checkin:${regId}`,
          kind: "checkin",
          at,
          email,
          fullName,
          avatar: row.avatar as string | null | undefined,
          detail: checkinTypeLabel(row.checkinMethod),
        })
      }
    }

    if (asAttendanceBool(row.hasCheckout)) {
      const at = String(row.updatedAt ?? row.registeredAt ?? "")
      if (at) {
        items.push({
          id: `checkout:${regId}`,
          kind: "checkout",
          at,
          email,
          fullName,
          avatar: row.avatar as string | null | undefined,
          detail: "Check-out",
        })
      }
    }
  }

  return items.sort(
    (a, b) => new Date(b.at).getTime() - new Date(a.at).getTime()
  )
}

export function getEventLiveActivityGlobalFilterText(
  row: EventLiveActivityRow
): string {
  const kindLabel = row.kind === "checkin" ? "Check-in" : "Check-out"
  return [
    row.fullName,
    row.email,
    kindLabel,
    row.detail,
    formatDateTime(row.at),
  ]
    .filter(Boolean)
    .join(" ")
}

export function getEventLiveActivityColumns(): ColumnDef<EventLiveActivityRow>[] {
  return [
    {
      id: "avatar",
      header: "Avatar",
      enableColumnFilter: true,
      filterFn: () => true,
      size: 56,
      meta: {
        exportHeader: "Avatar",
        exportValue: (row) =>
          resolveRegistrationAvatarUrl({
            fullName: row.fullName,
            email: row.email,
            avatar: row.avatar,
          }) || "",
        exportWidth: 36,
      },
      cell: ({ row }) => (
        <RegistrationAvatarCell
          row={{
            fullName: row.original.fullName,
            email: row.original.email,
            avatar: row.original.avatar,
          }}
        />
      ),
    },
    {
      id: "kind",
      header: "Loại",
      enableColumnFilter: true,
      filterFn: () => true,
      size: 120,
      meta: {
        exportValue: (row) =>
          row.kind === "checkin" ? "Check-in" : "Check-out",
        exportWidth: 14,
      },
      cell: ({ row }) => {
        const isCheckin = row.original.kind === "checkin"
        return (
          <div className="flex items-center gap-2">
            <div
              className={cn(
                "flex size-7 shrink-0 items-center justify-center rounded-full",
                isCheckin
                  ? "bg-emerald-500/15 text-emerald-700"
                  : "bg-amber-500/15 text-amber-700"
              )}
            >
              {isCheckin ? (
                <LogIn className="size-3.5" aria-hidden />
              ) : (
                <LogOut className="size-3.5" aria-hidden />
              )}
            </div>
            <Badge
              variant={isCheckin ? "default" : "secondary"}
              className="text-[10px]"
            >
              {isCheckin ? "Check-in" : "Check-out"}
            </Badge>
          </div>
        )
      },
    },
    {
      accessorKey: "fullName",
      header: "Họ tên",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => (getValue() as string) || "—",
    },
    {
      accessorKey: "email",
      header: "Email",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => (getValue() as string) || "—",
    },
    {
      accessorKey: "detail",
      header: "Ghi chú",
      enableColumnFilter: true,
      filterFn: () => true,
      cell: ({ getValue }) => (getValue() as string) || "—",
    },
    {
      id: "at",
      header: "Thời gian",
      enableColumnFilter: true,
      filterFn: () => true,
      accessorFn: (row) => row.at,
      meta: {
        exportValue: (row) => formatDateTime(row.at),
        exportWidth: 20,
      },
      cell: ({ row }) => (
        <span className="text-sm tabular-nums">
          {formatDateTime(row.original.at)}
        </span>
      ),
    },
  ]
}

src/modules/events/_component/registrati.content:
"use client"
import { api } from "@workspace/admin-app/lib/api"
import { useQueryClient } from "@tanstack/react-query"
import {
  ClipboardList,
  LogIn,
  LogOut,
  RotateCcw,
  Trash2,
  Undo2,
} from "lucide-react"
import {
  DataTableRowActionsMenu,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import {
  asAttendanceBool,
  buildManualAttendancePayload,
  buildPayloadFromRegistrationRow,
} from "./_live/event-attendance-sync"
import { useEventAttendanceContext } from "./_live/event-attendance-provider"
import { AttendanceStatusBadge } from "./attendance-status"

import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
type RegistrationRow = Record<string, unknown>

type AttendanceAction =
  | "checkin"
  | "checkout"
  | "reset-checkin"
  | "reset-checkout"
  | "reset-all"

export function RegistrationAttendanceActions({
  eventId,
  row,
  compact,
}: {
  eventId: string
  row: RegistrationRow
  compact?: boolean
}) {
  const queryClient = useQueryClient()
  const { applyAttendance } = useEventAttendanceContext()
  const registrationId = String(row.id ?? "")
  const hasCheckin = asAttendanceBool(row.hasCheckin)
  const hasCheckout = asAttendanceBool(row.hasCheckout)

  const mutation = useAdminMutation({
    toast: {
      loading: "Đang cập nhật điểm danh…",
      success: "Đã cập nhật điểm danh",
      error: (err) =>
        err instanceof Error ? err.message : "Không cập nhật được điểm danh",
    },
    mutationFn: async (action: AttendanceAction) => {
      return api.eventRegistrations.setAttendance<RegistrationRow>(
        registrationId,
        { action }
      )
    },
    onMutate: async (action) => {
      const payload = buildManualAttendancePayload(
        eventId,
        registrationId,
        row,
        action
      )
      applyAttendance(payload)
      await queryClient.cancelQueries({
        queryKey: ["events", eventId, "registrations"],
      })
      const previous = queryClient.getQueryData<RegistrationRow[]>([
        "events",
        eventId,
        "registrations",
      ])
      return { previous, payload }
    },
    onError: (_err, _action, ...rest) => {
      const context = rest[0] as { previous?: RegistrationRow[] } | undefined
      if (context?.previous) {
        queryClient.setQueryData(
          ["events", eventId, "registrations"],
          context.previous
        )
      }
    },
    onSuccess: (updated) => {
      applyAttendance(buildPayloadFromRegistrationRow(eventId, updated))
    },
  })

  const busy = mutation.isPending

  const actions: DataTableRowActionItem[] = []

  if (!hasCheckin && !busy && registrationId) {
    actions.push({
      key: "checkin",
      label: "Ghi nhận check-in",
      hint: "Đánh dấu người tham dự đã vào sự kiện",
      onClick: () => mutation.mutate("checkin"),
      icon: <LogIn />,
      group: "primary",
    })
  }

  if (!hasCheckout && hasCheckin && !busy && registrationId) {
    actions.push({
      key: "checkout",
      label: "Ghi nhận check-out",
      hint: "Đánh dấu người tham dự đã rời sự kiện",
      onClick: () => mutation.mutate("checkout"),
      icon: <LogOut />,
      group: "primary",
    })
  }

  if (hasCheckout && !busy && registrationId) {
    actions.push({
      key: "reset-checkout",
      label: "Hoàn tác check-out",
      hint: "Bỏ trạng thái check-out, giữ check-in",
      onClick: () => mutation.mutate("reset-checkout"),
      icon: <Undo2 />,
      group: "status",
    })
  }

  if (hasCheckin && !busy && registrationId) {
    actions.push({
      key: "reset-checkin",
      label: "Hoàn tác check-in",
      hint: "Bỏ check-in (và check-out nếu có)",
      onClick: () => mutation.mutate("reset-checkin"),
      icon: <RotateCcw />,
      group: "status",
    })
  }

  if ((hasCheckin || hasCheckout) && !busy && registrationId) {
    actions.push({
      key: "reset-all",
      label: "Xóa toàn bộ trạng thái",
      hint: "Xóa cả check-in và check-out",
      onClick: () => mutation.mutate("reset-all"),
      icon: <Trash2 />,
      group: "danger",
      menuVariant: "destructive",
    })
  }

  if (compact) {
    return (
      <DataTableRowActionsMenu
        actions={actions}
        busy={busy}
        triggerLabel="Thao tác trạng thái check-in"
        groups={{
          primary: { label: "Trạng thái check-in", icon: ClipboardList },
          status: {
            label: "Hoàn tác",
            sublabel: true,
            header: (
              <div className="mb-1.5 px-1">
                <AttendanceStatusBadge row={{ hasCheckin, hasCheckout }} />
              </div>
            ),
          },
          danger: { label: "Xóa trạng thái", sublabel: true },
        }}
      />
    )
  }

  return (
    <div className="flex w-full justify-center">
      <DataTableRowActionsMenu
        actions={actions}
        busy={busy}
        triggerLabel="Thao tác trạng thái check-in"
        className="w-full"
        groups={{
          primary: { label: "Trạng thái check-in", icon: ClipboardList },
          status: {
            label: "Hoàn tác",
            sublabel: true,
            header: (
              <div className="mb-1.5 px-1">
                <AttendanceStatusBadge row={{ hasCheckin, hasCheckout }} />
              </div>
            ),
          },
          danger: { label: "Xóa trạng thái", sublabel: true },
        }}
      />
    </div>
  )
}

"use client"

import { Avatar, AvatarFallback, AvatarImage } from "@ui/components/avatar"
import { getPosterUrlFromValue } from "./utils"

function initialsFromName(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "?"
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase()
  return `${parts[0]![0] ?? ""}${parts[parts.length - 1]![0] ?? ""}`.toUpperCase()
}

/** URL ảnh đại diện từ nhiều shape row (đăng ký, diễn giả sự kiện, …). */
export function resolveRegistrationAvatarUrl(
  row: Record<string, unknown>
): string {
  const raw = row.avatar ?? row.speakerAvatar ?? null
  return getPosterUrlFromValue(raw)
}

export function resolveRowDisplayName(row: Record<string, unknown>): string {
  return String(row.fullName ?? row.speakerName ?? row.email ?? "")
}

export function RegistrationAvatarCell({
  row,
  size = "sm",
}: {
