"use client"
import { api } from "@workspace/admin-app/lib/api"
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react"
import { useQueryClient } from "@tanstack/react-query"
import { useEventRegistrationsQuery } from "../_query"
import { syncEventAttendanceUi } from "./event-attendance-sync"
import {
  eventRegistrationsPollInterval,
  useEventAttendanceSocket,
} from "./use-event-attendance-socket"
import type {
  EventAttendanceSocketPayload,
  EventHanetSyncSocketPayload,
} from "./use-event-attendance-socket"

const MAX_HANET_SYNC_LOG = 50

type EventAttendanceContextValue = {
  connected: boolean
  socketError: boolean
  lastPayload: EventAttendanceSocketPayload | null
  hanetSyncLog: EventHanetSyncSocketPayload[]
  /** Tăng mỗi lần check-in/out — ép bảng re-render tức thì. */
  liveRevision: number
  applyAttendance: (payload: EventAttendanceSocketPayload) => void
}

const EventAttendanceContext =
  createContext<EventAttendanceContextValue | null>(null)

/** Socket + cache đăng ký luôn sống trên trang chi tiết sự kiện. */
export function EventAttendanceProvider({
  eventId,
  enabled = true,
  children,
}: {
  eventId: string
  enabled?: boolean
  children: ReactNode
}) {
  const queryClient = useQueryClient()
  const [liveRevision, setLiveRevision] = useState(0)
  const [lastPayload, setLastPayload] =
    useState<EventAttendanceSocketPayload | null>(null)
  const [hanetSyncLog, setHanetSyncLog] = useState<
    EventHanetSyncSocketPayload[]
  >([])

  const applyAttendance = useCallback(
    (payload: EventAttendanceSocketPayload) => {
      setLastPayload(payload)
      setLiveRevision((r) => r + 1)
      syncEventAttendanceUi(queryClient, eventId, payload)
    },
    [queryClient, eventId]
  )

  const appendHanetSync = useCallback((payload: EventHanetSyncSocketPayload) => {
    setHanetSyncLog((prev) => [payload, ...prev].slice(0, MAX_HANET_SYNC_LOG))
  }, [])

  const { connected, socketError } = useEventAttendanceSocket(
    eventId,
    enabled,
    applyAttendance,
    appendHanetSync
  )

  const pollMs = eventRegistrationsPollInterval(connected)

  useEventRegistrationsQuery(api, eventId, {
    enabled: enabled && !!eventId,
    refetchInterval: pollMs,
  })

  const value = useMemo<EventAttendanceContextValue>(
    () => ({
      connected,
      socketError,
      lastPayload,
      hanetSyncLog,
      liveRevision,
      applyAttendance,
    }),
    [
      applyAttendance,
      connected,
      hanetSyncLog,
      lastPayload,
      liveRevision,
      socketError,
    ]
  )

  return (
    <EventAttendanceContext.Provider value={value}>
      {children}
    </EventAttendanceContext.Provider>
  )
}

export function useEventAttendanceContext(): EventAttendanceContextValue {
  const ctx = useContext(EventAttendanceContext)
  if (!ctx) {
    return {
      connected: false,
      socketError: false,
      lastPayload: null,
      hanetSyncLog: [],
      liveRevision: 0,
      applyAttendance: () => {},
    }
  }
  return ctx
}

import type { QueryClient } from "@tanstack/react-query"
import type { EventDetail } from "../types"
import { patchRegistrationAttendanceCache } from "./patch-registration-attendance-cache"
import type { EventAttendanceSocketPayload } from "./use-event-attendance-socket"

type RegistrationRow = Record<string, unknown>

/** API / DB có thể trả 0/1 thay vì boolean. */
export function asAttendanceBool(value: unknown): boolean {
  return value === true || value === 1 || value === "1"
}

function recountFromRegistrations(regs: RegistrationRow[]) {
  let totalCheckins = 0
  let totalCheckouts = 0
  for (const row of regs) {
    if (asAttendanceBool(row.hasCheckin)) totalCheckins += 1
    if (asAttendanceBool(row.hasCheckout)) totalCheckouts += 1
  }
  return { totalCheckins, totalCheckouts }
}

function patchEventDetailCounts(
  queryClient: QueryClient,
  eventId: string,
  regs: RegistrationRow[]
): void {
  const { totalCheckins, totalCheckouts } = recountFromRegistrations(regs)
  queryClient.setQueryData<EventDetail>(
    ["events", "detail", eventId],
    (detail) => {
      if (!detail) return detail
      return {
        ...detail,
        totalCheckins,
        totalCheckouts,
      }
    }
  )
}

function cloneRegistrations(regs: RegistrationRow[]): RegistrationRow[] {
  return regs.map((row) => ({ ...row }))
}

/**
 * Gộp cache React Query + payload realtime mới nhất — bảng re-render ngay
 * kể cả khi query observer chưa kịp notify.
 */
export function mergeRegistrationRowsForDisplay(
  rows: RegistrationRow[] | undefined,
  lastPayload: EventAttendanceSocketPayload | null
): RegistrationRow[] {
  const base = cloneRegistrations(rows ?? [])
  if (!lastPayload?.registrationId) return base

  const targetId = String(lastPayload.registrationId)
  return base.map((row) => {
    if (String(row.id ?? "") !== targetId) {
      return {
        ...row,
        hasCheckin: asAttendanceBool(row.hasCheckin),
        hasCheckout: asAttendanceBool(row.hasCheckout),
        avatar: row.avatar ?? null,
      }
    }

    const hasCheckin =
      lastPayload.hasCheckin !== undefined
        ? asAttendanceBool(lastPayload.hasCheckin)
        : lastPayload.kind === "checkout"
          ? true
          : true
    const hasCheckout =
      lastPayload.hasCheckout !== undefined
        ? asAttendanceBool(lastPayload.hasCheckout)
        : lastPayload.kind === "checkout"

    return {
      ...row,
      hasCheckin,
      hasCheckout,
      avatar: row.avatar ?? null,
      updatedAt: lastPayload.at,
    }
  })
}

export function buildManualAttendancePayload(
  eventId: string,
  registrationId: string,
  row: RegistrationRow,
  action:
    | "checkin"
    | "checkout"
    | "reset-checkin"
    | "reset-checkout"
    | "reset-all"
): EventAttendanceSocketPayload {
  const at = new Date().toISOString()
  let hasCheckin = asAttendanceBool(row.hasCheckin)
  let hasCheckout = asAttendanceBool(row.hasCheckout)

  switch (action) {
    case "checkin":
      hasCheckin = true
      break
    case "checkout":
      hasCheckin = true
      hasCheckout = true
      break
    case "reset-checkout":
      hasCheckout = false
      break
    case "reset-checkin":
      hasCheckin = false
      hasCheckout = false
      break
    case "reset-all":
      hasCheckin = false
      hasCheckout = false
      break
  }

  return {
    kind: action === "checkout" ? "checkout" : "checkin",
    eventId,
    at,
    email: String(row.email ?? ""),
    fullName: String(row.fullName ?? ""),
    source: "manual",
    registrationId,
    hasCheckin,
    hasCheckout,
  }
}

export function buildPayloadFromRegistrationRow(
  eventId: string,
  row: RegistrationRow
): EventAttendanceSocketPayload {
  return {
    kind: asAttendanceBool(row.hasCheckout) ? "checkout" : "checkin",
    eventId,
    at: String(row.updatedAt ?? new Date().toISOString()),
    email: String(row.email ?? ""),
    fullName: String(row.fullName ?? ""),
    source: "manual",
    registrationId: String(row.id ?? ""),
    hasCheckin: asAttendanceBool(row.hasCheckin),
    hasCheckout: asAttendanceBool(row.hasCheckout),
  }
}

/**
 * Đồng bộ cache + đánh dấu stale (không refetch đồng loạt — tránh ghi đè optimistic).
 */
export function syncEventAttendanceUi(
  queryClient: QueryClient,
  eventId: string,
  payload: EventAttendanceSocketPayload
): void {
  patchRegistrationAttendanceCache(queryClient, eventId, payload)

  const regs = queryClient.getQueryData<RegistrationRow[]>([
    "events",
    eventId,
    "registrations",
  ])
  if (regs?.length) {
    patchEventDetailCounts(queryClient, eventId, regs)
  }

  void queryClient.invalidateQueries({
    queryKey: ["events", eventId],
    refetchType: "active",
  })
}

export function applyOptimisticRegistrationAttendance(
  rows: RegistrationRow[] | undefined,
  registrationId: string,
  action:
    | "checkin"
    | "checkout"
    | "reset-checkin"
    | "reset-checkout"
    | "reset-all"
): RegistrationRow[] | undefined {
  if (!rows?.length) return rows
  const at = new Date().toISOString()
  const CHECKIN_METHOD_MANUAL = 3

  return rows.map((row) => {
    if (String(row.id) !== registrationId) return row
    switch (action) {
      case "checkin":
        return {
          ...row,
          hasCheckin: true,
          checkinMethod: CHECKIN_METHOD_MANUAL,
          updatedAt: at,
        }
      case "checkout":
        return {
          ...row,
          hasCheckin: true,
          hasCheckout: true,
          updatedAt: at,
        }
      case "reset-checkout":
        return {
          ...row,
          hasCheckout: false,
          updatedAt: at,
        }
      case "reset-checkin":
        return {
          ...row,
          hasCheckin: false,
          hasCheckout: false,
          checkinMethod: 0,
          updatedAt: at,
        }
      case "reset-all":
        return {
          ...row,
          hasCheckin: false,
          hasCheckout: false,
          checkinMethod: 0,
          updatedAt: at,
        }
      default:
        return row
    }
  })
}

"use client"

import Link from "next/link"
import { ExternalLink, Loader2, RefreshCw, Users } from "lucide-react"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { useQueryClient } from "@tanstack/react-query"
import { api } from "@workspace/admin-app/lib/api"
import { useAdminModulePath } from "@workspace/admin-app/runtime"
import type { HanetSyncAvatarsResult } from "@workspace/api-client"
import {
  HanetAvatarCard,
  useHanetAvatarsQuery,
} from "@workspace/admin-app/modules/hanet/_component"
import { HanetPlaceSelect } from "@workspace/admin-app/modules/hanet/_component/hanet-place-select"
import { readHanetAdminPlaceId } from "@workspace/admin-app/lib/hanet-place-storage"
import { useHanetStatusQuery } from "@workspace/admin-app/modules/events/_component/_query"
import { useCallback, useState } from "react"

export function EventHanetAvatarPanel({
  defaultPlaceId,
}: {
  defaultPlaceId?: string | null
}) {
  const queryClient = useQueryClient()
  const hanetPath = useAdminModulePath("hanet")
  const { data: hanetStatus } = useHanetStatusQuery()
  const [search, setSearch] = useState("")
  const [selectedPlaceId, setSelectedPlaceId] = useState(readHanetAdminPlaceId)

  const avatarsQuery = useHanetAvatarsQuery({
    page: 1,
    limit: 12,
    search,
  })

  const effectivePlaceId =
    selectedPlaceId || defaultPlaceId || hanetStatus?.defaultPlaceId || ""

  const syncMutation = useAdminMutation({
    mutationKey: ["hanet", "avatars", "sync"],
    mutationFn: () =>
      api.hanet.syncPersonAvatars(effectivePlaceId || undefined),
    toast: {
      loading: "Đang đồng bộ avatar từ HANET…",
      success: (res: HanetSyncAvatarsResult) =>
        `Đã đồng bộ ${res.fetched} người (${res.created} mới, ${res.updated} cập nhật)`,
      error: (err) =>
        err instanceof Error ? err.message : "Không đồng bộ được avatar HANET",
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["hanet", "avatars"] })
    },
  })

  const onSearch = useCallback((value: string) => {
    setSearch(value)
  }, [])

  const items = avatarsQuery.data?.items ?? []
  const total = avatarsQuery.data?.total ?? 0

  return (
    <div className="space-y-3 rounded-md border border-border/70 bg-background px-3 py-2.5 text-xs">
      <div className="flex flex-wrap items-center gap-2">
        <Users className="size-4 shrink-0 text-primary" aria-hidden />
        <p className="font-medium text-foreground">Avatar HANET đã lưu</p>
        <span className="text-muted-foreground">{total} bản ghi</span>
        <Link
          href={`${hanetPath()}/avatar`}
          className="inline-flex items-center gap-1 text-primary hover:underline"
        >
          Xem trang đầy đủ
          <ExternalLink className="size-3" aria-hidden />
        </Link>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="ml-auto h-7 gap-1.5 text-xs"
          disabled={syncMutation.isPending || !effectivePlaceId}
          onClick={() => syncMutation.mutate()}
        >
          {syncMutation.isPending ? (
            <Loader2 className="size-3.5 animate-spin" />
          ) : (
            <RefreshCw className="size-3.5" />
          )}
          Đồng bộ
        </Button>
      </div>

      {hanetStatus?.configured ? (
        <HanetPlaceSelect
          value={selectedPlaceId}
          onChange={setSelectedPlaceId}
          defaultPlaceId={defaultPlaceId ?? hanetStatus.defaultPlaceId}
          disabled={syncMutation.isPending}
        />
      ) : null}

      <Input
        value={search}
        onChange={(e) => onSearch(e.target.value)}
        placeholder="Tìm tên, email, personID…"
        className="h-8 text-xs"
      />

      {avatarsQuery.isLoading ? (
        <div className="flex items-center gap-2 py-4 text-muted-foreground">
          <Loader2 className="size-4 animate-spin" />
          Đang tải…
        </div>
      ) : items.length ? (
        <div className="flex flex-col gap-2">
          {items.map((row) => (
            <HanetAvatarCard key={row.id} row={row} compact />
          ))}
        </div>
      ) : (
        <p className="py-3 text-center text-muted-foreground">
          Chưa có avatar —{" "}
          <Link href={`${hanetPath()}?tab=avatars`} className="text-primary hover:underline">
            mở trang HANET → Avatar
          </Link>
        </p>
      )}
    </div>
  )
}

"use client"

import { useCallback, useState } from "react"
import Link from "next/link"
import {
  ChevronRight,
  Copy,
  Check,
  Link2,
  ExternalLink,
  Loader2,
} from "lucide-react"
import { Card, CardContent, CardHeader, CardTitle } from "@ui/components/card"
import { Button } from "@ui/components/button"
import { Badge } from "@ui/components/badge"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@ui/components/collapsible"
import {
  buildHanetWebhookAutoUrl,
  buildHanetWebhookUrl,
} from "@workspace/admin-app/lib/hanet-webhook-url"
import { useAdminModulePath } from "@workspace/admin-app/runtime"
import { useHanetStatusQuery } from "../_query/use-hanet-status"

export type EventHanetCameraInfo = {
  checkinCameraName: string | null
  checkinCameraCode: string | null
  checkoutCameraName: string | null
  checkoutCameraCode: string | null
}

function CopyUrlButton({ url, label }: { url: string; label: string }) {
  const [copied, setCopied] = useState(false)

  const copyUrl = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(url)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 2000)
    } catch {
      setCopied(false)
    }
  }, [url])

  return (
    <div className="space-y-1.5">
      <p className="text-xs font-medium text-muted-foreground">{label}</p>
      <div className="flex flex-wrap items-center gap-2">
        <code className="min-w-0 flex-1 rounded-md border border-border/70 bg-background px-3 py-2 text-xs break-all">
          {url}
        </code>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="shrink-0 gap-1.5"
          onClick={() => void copyUrl()}
        >
          {copied ? (
            <>
              <Check className="size-3.5" /> Đã copy
            </>
          ) : (
            <>
              <Copy className="size-3.5" /> Copy
            </>
          )}
        </Button>
      </div>
    </div>
  )
}

export function EventHanetConfigCard({
  eventId,
  cameras,
}: {
  eventId: string
  cameras?: EventHanetCameraInfo
}) {
  const eventEditPath = useAdminModulePath("events")
  const hanetPath = useAdminModulePath("hanet")
  const { data: hanetStatus, isLoading: loadingStatus } =
    useHanetStatusQuery(eventId)

  const webhookPerEvent =
    hanetStatus?.urls.forEvent ?? buildHanetWebhookUrl(eventId)
  const webhookAuto = hanetStatus?.urls.auto ?? buildHanetWebhookAutoUrl()

  const hasCameras = Boolean(
    cameras?.checkinCameraName || cameras?.checkoutCameraName
  )

  return (
    <Collapsible defaultOpen={false} className="w-full">
      <Card className="justify-start gap-0 border border-dashed border-primary/30 bg-primary/5 py-0 shadow-sm">
        <CollapsibleTrigger className="group w-full cursor-pointer py-2 text-left transition-colors hover:bg-primary/10">
          <CardHeader>
            <CardTitle className="flex flex-wrap items-center gap-2 text-base">
              <ChevronRight
                className="size-4 shrink-0 text-muted-foreground transition-transform group-data-[panel-open]:rotate-90"
                aria-hidden
              />
              <Link2 className="size-5 text-primary" />
              Webhook HANET
              {loadingStatus ? (
                <Loader2 className="size-4 animate-spin text-muted-foreground" />
              ) : hanetStatus?.configured ? (
                <Badge variant="default" className="text-[10px] font-normal">
                  OAuth đã cấu hình
                </Badge>
              ) : (
                <Badge variant="outline" className="text-[10px] font-normal">
                  Chưa cấu hình .env API
                </Badge>
              )}
              <a
                href="https://developers.hanet.ai/document"
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1 text-xs font-normal text-primary underline-offset-2 hover:underline"
                onClick={(e) => e.stopPropagation()}
              >
                Tài liệu
                <ExternalLink className="size-3" aria-hidden />
              </a>
              <span className="w-full text-xs font-normal text-muted-foreground sm:ml-auto sm:w-auto">
                {hasCameras
                  ? "Đã gắn camera HANET"
                  : "Chưa gắn camera · chọn trên form sự kiện"}
              </span>
            </CardTitle>
          </CardHeader>
        </CollapsibleTrigger>
        <CollapsibleContent className="pb-4">
          <CardContent className="space-y-4 border-t border-primary/15 pt-4 text-sm">
            <p className="text-xs text-muted-foreground">
              Kết nối OAuth, địa điểm, thiết bị và avatar — quản lý tập trung trên{" "}
              <Link href={`${hanetPath()}/ket-noi`} className="font-medium text-primary hover:underline">
                trang HANET
              </Link>
              .
            </p>

            <div className="space-y-1">
              <p className="font-medium text-sm">Gắn camera cho sự kiện</p>
              <ol className="list-inside list-decimal space-y-1 text-xs text-muted-foreground">
                <li>
                  <Link
                    href={eventEditPath(eventId, "edit")}
                    className="text-primary hover:underline"
                  >
                    Chỉnh sửa sự kiện
                  </Link>{" "}
                  → mục <strong>Camera HANET</strong>: chọn thiết bị check-in /
                  check-out từ danh sách HANET.
                </li>
                <li>
                  Copy URL webhook bên dưới → dán vào App trên cổng HANET.
                </li>
              </ol>
            </div>

            {hasCameras ? (
              <ul className="space-y-1 rounded-md border border-border/70 bg-background px-3 py-2 text-xs">
                <li>
                  <span className="text-muted-foreground">Check-in: </span>
                  {cameras?.checkinCameraName ?? "—"}
                  {cameras?.checkinCameraCode ? (
                    <span className="font-mono text-muted-foreground">
                      {" "}
                      (deviceID: {cameras.checkinCameraCode})
                    </span>
                  ) : null}
                </li>
                <li>
                  <span className="text-muted-foreground">Check-out: </span>
                  {cameras?.checkoutCameraName ?? "—"}
                  {cameras?.checkoutCameraCode ? (
                    <span className="font-mono text-muted-foreground">
                      {" "}
                      (deviceID: {cameras.checkoutCameraCode})
                    </span>
                  ) : null}
                </li>
              </ul>
            ) : (
              <p className="text-xs text-amber-700 dark:text-amber-400">
                Chưa chọn camera —{" "}
                <Link
                  href={eventEditPath(eventId, "edit")}
                  className="font-medium underline underline-offset-2"
                >
                  mở Chỉnh sửa sự kiện → Camera HANET
                </Link>
                .
              </p>
            )}

            <CopyUrlButton
              label="Webhook theo sự kiện (khuyến nghị)"
              url={webhookPerEvent}
            />
            <CopyUrlButton
              label="Webhook chung (tự nhận diện theo deviceID + camera đã gắn)"
              url={webhookAuto}
            />
          </CardContent>
        </CollapsibleContent>
      </Card>
    </Collapsible>
  )
}

"use client"
import { Badge } from "@ui/components/badge"
import { cn } from "@ui/lib/utils"
import { Radio } from "lucide-react"
import type { EventHanetSyncSocketPayload } from "./use-event-attendance-socket"

const KIND_LABELS: Record<EventHanetSyncSocketPayload["kind"], string> = {
  device: "Thiết bị",
  place: "Địa điểm",
  person: "Người",
  checkin: "Check-in",
  checkout: "Check-out",
  unknown: "Khác",
}

function formatAt(value: string): string {
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString("vi-VN")
}

function kindVariant(
  kind: EventHanetSyncSocketPayload["kind"],
  acknowledged: boolean
): "default" | "secondary" | "destructive" | "outline" {
  if (!acknowledged) return "destructive"
  if (kind === "checkin") return "default"
  if (kind === "checkout") return "secondary"
  return "outline"
}

export function EventHanetSyncLog({
  entries,
  connected,
}: {
  entries: EventHanetSyncSocketPayload[]
  connected: boolean
}) {
  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-2">
        <p className="flex items-center gap-2 text-base font-semibold">
          <Radio className="size-5 text-primary" />
          Webhook HANET gần đây
        </p>
        {connected ? (
          <Badge variant="secondary" className="text-[10px]">
            Live
          </Badge>
        ) : null}
      </div>
      <div className="overflow-hidden rounded-lg border border-border/70 bg-card">
        {entries.length === 0 ? (
          <p className="px-4 py-6 text-sm text-muted-foreground">
            Chưa có webhook HANET trong phiên này. Đồng bộ person/device/place
            hoặc check-in từ camera sẽ hiện tại đây.
          </p>
        ) : (
          <ul className="divide-y divide-border/60">
            {entries.map((entry, index) => (
              <li
                key={`${entry.at}-${entry.kind}-${index}`}
                className={cn(
                  "flex flex-wrap items-start justify-between gap-2 px-4 py-3 text-sm",
                  index === 0 && "bg-primary/5"
                )}
              >
                <div className="min-w-0 flex-1 space-y-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <Badge
                      variant={kindVariant(entry.kind, entry.acknowledged)}
                      className="text-[10px]"
                    >
                      {KIND_LABELS[entry.kind] ?? entry.kind}
                      {entry.action ? ` · ${entry.action}` : ""}
                    </Badge>
                    {!entry.acknowledged ? (
                      <Badge variant="destructive" className="text-[10px]">
                        Lỗi
                      </Badge>
                    ) : null}
                  </div>
                  <p className="font-medium leading-snug">{entry.summary}</p>
                  {entry.error ? (
                    <p className="text-xs text-destructive">{entry.error}</p>
                  ) : null}
                </div>
                <time
                  className="shrink-0 text-xs tabular-nums text-muted-foreground"
                  dateTime={entry.at}
                >
                  {formatAt(entry.at)}
                </time>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

"use client"
import { api } from "@workspace/admin-app/lib/api"
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react"
import {
  Activity,
  LogOut,
  Pause,
  Play,
  Radio,
  RefreshCw,
  UserCheck,
  Users,
} from "lucide-react"
import { AdminDataTable } from "@ui/components/data-table"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { cn } from "@ui/lib/utils"
import { buildEventDetailXlsxExport } from "@ui/components/admin"
import type { EventDetail } from "../types"
import {
  useEventDetailQuery,
  useEventRegistrationsQuery,
  type EventLiveQueryOptions,
} from "../_query"
import {
  asAttendanceBool,
  mergeRegistrationRowsForDisplay,
} from "./event-attendance-sync"
import { useEventAttendanceContext } from "./event-attendance-provider"
import { EventHanetConfigCard } from "./event-hanet-config-card"
import { EventHanetSyncLog } from "./event-hanet-sync-log"
import {
  buildLiveActivitiesFromRegistrations,
  getEventLiveActivityColumns,
  getEventLiveActivityGlobalFilterText,
  type EventLiveActivityRow,
} from "../live-activity-columns"

const LIVE_POLL_MS = 15_000
const LIVE_POLL_SOCKET_MS = 60_000
const NEW_HIGHLIGHT_MS = 12_000

function formatDateTime(value: string | null | undefined): string {
  if (!value) return "—"
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString("vi-VN")
}

export function EventLiveMonitorTab({
  eventId,
  eventTitle,
  initialStats,
}: {
  eventId: string
  eventTitle?: string
  initialStats: Pick<
    EventDetail,
    "totalRegistrations" | "totalCheckins" | "totalCheckouts"
  >
}) {
  const [liveEnabled, setLiveEnabled] = useState(true)
  const {
    connected: socketConnected,
    socketError,
    lastPayload,
    liveRevision,
    hanetSyncLog,
  } = useEventAttendanceContext()

  const pollOptions = useMemo<EventLiveQueryOptions>(
    () => ({
      enabled: liveEnabled,
      refetchInterval: liveEnabled
        ? socketConnected
          ? LIVE_POLL_SOCKET_MS
          : LIVE_POLL_MS
        : false,
    }),
    [liveEnabled, socketConnected]
  )

  const detailQuery = useEventDetailQuery(api, eventId, pollOptions)
  const registrationsQuery = useEventRegistrationsQuery(
    api,
    eventId,
    pollOptions
  )

  const registrations = useMemo(
    () => mergeRegistrationRowsForDisplay(registrationsQuery.data, lastPayload),
    [registrationsQuery.data, lastPayload]
  )

  const stats = detailQuery.data ?? initialStats

  const hanetCameras = useMemo(() => {
    const d = detailQuery.data
    if (!d) return undefined
    return {
      checkinCameraName: d.checkinCameraName ?? null,
      checkinCameraCode: d.checkinCameraCode ?? null,
      checkoutCameraName: d.checkoutCameraName ?? null,
      checkoutCameraCode: d.checkoutCameraCode ?? null,
    }
  }, [detailQuery.data])

  const activities = useMemo(
    () => buildLiveActivitiesFromRegistrations(registrations),
    [registrations]
  )

  const activityColumns = useMemo(() => getEventLiveActivityColumns(), [])

  const pendingCheckin = useMemo(
    () =>
      registrations.filter(
        (r) => !asAttendanceBool(r.hasCheckin) && r.status !== 2
      ).length,
    [registrations]
  )

  const seenIdsRef = useRef<Set<string>>(new Set())
  const [newActivityIds, setNewActivityIds] = useState<Set<string>>(new Set())
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null)

  const newActivityCount = useMemo(
    () => activities.filter((a) => newActivityIds.has(a.id)).length,
    [activities, newActivityIds]
  )

  const isFetching = detailQuery.isFetching || registrationsQuery.isFetching

  const isLoading = registrationsQuery.isLoading

  useEffect(() => {
    if (!liveEnabled || isFetching) return

    const currentIds = new Set(activities.map((a) => a.id))
    const fresh = new Set<string>()

    if (seenIdsRef.current.size > 0) {
      for (const id of currentIds) {
        if (!seenIdsRef.current.has(id)) fresh.add(id)
      }
    }

    seenIdsRef.current = currentIds
    setLastSyncedAt(new Date())

    if (fresh.size === 0) return

    setNewActivityIds((prev) => new Set([...prev, ...fresh]))
    const timer = window.setTimeout(() => {
      setNewActivityIds((prev) => {
        const next = new Set(prev)
        for (const id of fresh) next.delete(id)
        return next
      })
    }, NEW_HIGHLIGHT_MS)

    return () => window.clearTimeout(timer)
  }, [activities, isFetching, liveEnabled])

  useEffect(() => {
    if (!liveEnabled || !lastPayload) return
    const id =
      lastPayload.kind === "checkin"
        ? `checkin:${lastPayload.registrationId ?? lastPayload.checkinId ?? lastPayload.email}`
        : lastPayload.kind === "checkout"
          ? `checkout:${lastPayload.registrationId ?? lastPayload.email}`
          : null
    if (!id) return
    setNewActivityIds((prev) => new Set([...prev, id]))
    const timer = window.setTimeout(() => {
      setNewActivityIds((prev) => {
        const next = new Set(prev)
        next.delete(id)
        return next
      })
    }, NEW_HIGHLIGHT_MS)
    return () => window.clearTimeout(timer)
  }, [lastPayload, liveRevision, liveEnabled])

  const handleRefresh = () => {
    void detailQuery.refetch()
    void registrationsQuery.refetch()
  }

  return (
    <div className="space-y-4">
      <EventHanetConfigCard eventId={eventId} cameras={hanetCameras} />

      <EventHanetSyncLog entries={hanetSyncLog} connected={socketConnected} />

      <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-border/70 bg-card px-4 py-3">
        <div className="flex items-center gap-2">
          <span
            className={cn(
              "relative flex size-2.5 rounded-full",
              liveEnabled ? "bg-emerald-500" : "bg-muted-foreground/40"
            )}
          >
            {liveEnabled ? (
              <span className="absolute inline-flex size-full animate-ping rounded-full bg-emerald-400 opacity-60" />
            ) : null}
          </span>
          <Radio className="size-4 text-primary" />
          {liveEnabled && socketConnected ? (
            <Badge variant="secondary" className="text-[10px]">
              HANET live
            </Badge>
          ) : null}
          {socketError && liveEnabled ? (
            <Badge variant="destructive" className="text-[10px]">
              Socket lỗi
            </Badge>
          ) : null}
          <div>
            <p className="text-sm font-medium">Theo dõi realtime</p>
            <p className="text-xs text-muted-foreground">
              {liveEnabled
                ? socketConnected
                  ? "HANET → Socket đã kết nối · polling dự phòng 60s"
                  : `Polling mỗi ${LIVE_POLL_MS / 1000}s (chờ Socket)`
                : "Đã tạm dừng"}
              {lastSyncedAt
                ? ` · Cập nhật ${formatDateTime(lastSyncedAt.toISOString())}`
                : ""}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {isFetching && liveEnabled ? (
            <RefreshCw className="size-4 animate-spin text-muted-foreground" />
          ) : null}
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="gap-1.5"
            onClick={() => setLiveEnabled((v) => !v)}
          >
            {liveEnabled ? (
              <>
                <Pause className="size-3.5" /> Tạm dừng
              </>
            ) : (
              <>
                <Play className="size-3.5" /> Tiếp tục
              </>
            )}
          </Button>
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard
          label="Đăng ký"
          value={stats.totalRegistrations}
          icon={<Users className="size-4 text-primary" />}
        />
        <StatCard
          label="Check-in"
          value={stats.totalCheckins}
          icon={<UserCheck className="size-4 text-emerald-600" />}
          tone="emerald"
        />
        <StatCard
          label="Check-out"
          value={stats.totalCheckouts}
          icon={<LogOut className="size-4 text-amber-600" />}
          tone="amber"
        />
        <StatCard
          label="Chưa check-in"
          value={pendingCheckin}
          icon={<Activity className="size-4 text-muted-foreground" />}
        />
      </div>

      <div className="space-y-2">
        <p className="flex items-center gap-2 text-base font-semibold">
          <Activity className="size-5 text-primary" />
          Luồng hoạt động gần đây
        </p>
        <AdminDataTable<EventLiveActivityRow>
          data={activities}
          columns={activityColumns}
          getRowId={(row) => row.id}
          isLoading={isLoading}
          emptyLabel="Chưa có check-in hoặc check-out nào."
          globalFilterPlaceholder="Tìm theo tên, email, loại, thời gian…"
          filterColumnVisibilityKey="admin-table-filter-visibility:event-live-activities"
          getGlobalFilterText={getEventLiveActivityGlobalFilterText}
          getRowClassName={(row) =>
            newActivityIds.has(row.original.id)
