"use client"

import {
  Download,
  ExternalLink,
  Eye,
  Film,
  Settings2,
  Trash2,
} from "lucide-react"

import {
  DataTableRowActionsMenu,
  type DataTableRowActionItem,
} from "@ui/components/data-table"

import type { FileStorageRow } from "./types"

import { resolveStorageAssetUrl } from "./utils"

export type FileStorageRowActionsProps = {
  row: FileStorageRow

  canDelete: boolean

  deleting?: boolean

  downloading?: boolean

  onPreviewImage?: () => void

  onPreviewVideo?: () => void

  onDownload: () => void | Promise<void>

  onDelete: () => void | Promise<void>
}

function deleteConfirm(row: FileStorageRow) {
  return {
    title: "Xóa file?",

    description: (
      <>
        File <strong>{row.originalName}</strong> sẽ bị xóa vĩnh viễn khỏi kho
        lưu trữ. Hành động này không thể hoàn tác.
      </>
    ),

    confirmLabel: "Xóa",

    destructive: true,
  }
}

export function FileStorageRowActions({
  row,

  canDelete,

  deleting,

  downloading,

  onPreviewImage,

  onPreviewVideo,

  onDownload,

  onDelete,
}: FileStorageRowActionsProps) {
  const actions: DataTableRowActionItem[] = [
    {
      key: "download",

      label: "Tải về",

      hint: "Lưu file xuống máy",

      onClick: onDownload,

      icon: <Download />,

      group: "primary",

      confirm: false,
    },

    {
      key: "open",

      label: "Mở tab mới",

      hint: "Xem file trong tab trình duyệt",

      onClick: () => {
        window.open(
          resolveStorageAssetUrl(row),
          "_blank",
          "noopener,noreferrer"
        )
      },

      icon: <ExternalLink />,

      group: "primary",

      confirm: false,
    },
  ]

  if (onPreviewImage) {
    actions.unshift({
      key: "preview-image",

      label: "Xem ảnh",

      hint: "Mở lightbox xem ảnh",

      onClick: onPreviewImage,

      icon: <Eye />,

      group: "primary",

      confirm: false,
    })
  }

  if (onPreviewVideo) {
    actions.unshift({
      key: "preview-video",

      label: "Phát video",

      hint: "Xem trước video trong hộp thoại",

      onClick: onPreviewVideo,

      icon: <Film />,

      group: "primary",

      confirm: false,
    })
  }

  if (canDelete && !deleting) {
    actions.push({
      key: "delete",

      label: "Xóa",

      hint: "Xóa vĩnh viễn khỏi kho lưu trữ",

      onClick: onDelete,

      icon: <Trash2 />,

      group: "danger",

      menuVariant: "destructive",

      confirm: deleteConfirm(row),
    })
  }

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={deleting || downloading}
      autoConfirmDangerousActions
      groups={{
        primary: { label: "Thao tác", icon: Settings2 },

        danger: { label: "Xóa", sublabel: true },
      }}
    />
  )
}

"use client"

import { Checkbox } from "@ui/components/checkbox"
import { Label } from "@ui/components/label"
import type { StorageRealm } from "./types"
import {
  extensionsFromGroupIds,
  formatExtensionsSummary,
  getRealmDefaultGroupIds,
  getRealmExtensionGroups,
  type StorageExtensionGroupId,
} from "./storage-upload-policy"

type FileStorageAllowedExtensionsPickerProps = {
  realm: StorageRealm
  value: StorageExtensionGroupId[]
  onChange: (groupIds: StorageExtensionGroupId[]) => void
  disabled?: boolean
}

export function FileStorageAllowedExtensionsPicker({
  realm,
  value,
  onChange,
  disabled = false,
}: FileStorageAllowedExtensionsPickerProps) {
  const groups = getRealmExtensionGroups(realm)
  const selectedExtensions = extensionsFromGroupIds(realm, value)

  const toggleGroup = (groupId: StorageExtensionGroupId, checked: boolean) => {
    const next = checked
      ? [...new Set([...value, groupId])]
      : value.filter((id) => id !== groupId)
    onChange(next.length > 0 ? next : getRealmDefaultGroupIds(realm))
  }

  return (
    <div className="space-y-2 rounded-lg border bg-muted/30 p-3">
      <div className="space-y-0.5">
        <p className="text-sm font-medium">Loại file được phép import</p>
        <p className="text-xs text-muted-foreground">
          Chỉ áp dụng cho folder cấp 1 mới. Folder con kế thừa cấu hình folder
          cha.
        </p>
      </div>
      <div className="space-y-2">
        {groups.map((group) => {
          const checked = value.includes(group.id)
          return (
            <div key={group.id} className="flex items-start gap-2">
              <Checkbox
                id={`ext-group-${group.id}`}
                checked={checked}
                disabled={disabled}
                onCheckedChange={(state) =>
                  toggleGroup(group.id, state === true)
                }
              />
              <div className="grid gap-0.5 leading-none">
                <Label
                  htmlFor={`ext-group-${group.id}`}
                  className="cursor-pointer text-sm font-normal"
                >
                  {group.label}
                </Label>
                <p className="text-xs text-muted-foreground">
                  {group.extensions.join(", ")}
                </p>
              </div>
            </div>
          )
        })}
      </div>
      <p className="text-xs text-muted-foreground">
        Đã chọn: {formatExtensionsSummary(selectedExtensions)}
      </p>
    </div>
  )
}

"use client"

import { useCallback, useMemo, useState } from "react"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import { Popover, PopoverContent, PopoverTrigger } from "@ui/components/popover"
import { toast } from "@ui/components/sonner"
import { resolveStorageFolderSlugPath } from "@workspace/api-client"
import { createStorageFolder } from "@workspace/admin-app/lib/admin-uploads"
import { FolderPlus, Loader2 } from "lucide-react"
import { FileStorageAllowedExtensionsPicker } from "./file-storage-allowed-extensions-picker"
import {
  extensionsFromGroupIds,
  getRealmDefaultGroupIds,
  type StorageExtensionGroupId,
} from "./storage-upload-policy"
import type { StorageRealm } from "./types"
import { resolveCreateFolderParent } from "./utils"

type FileStorageCreateFolderButtonProps = {
  realm: StorageRealm
  parentFolderPath?: string
  parentLabel: string
  onCreated: (folderPath: string) => Promise<void>
  disabled?: boolean
  size?: "default" | "sm"
}

export function FileStorageCreateFolderButton({
  realm,
  parentFolderPath = "",
  parentLabel,
  onCreated,
  disabled = false,
  size = "sm",
}: FileStorageCreateFolderButtonProps) {
  const [open, setOpen] = useState(false)
  const [name, setName] = useState("")
  const [creating, setCreating] = useState(false)
  const [extensionGroups, setExtensionGroups] = useState<
    StorageExtensionGroupId[]
  >(() => getRealmDefaultGroupIds(realm))
  const isLevel1Create = !parentFolderPath.trim()
  const slugPreview = useMemo(() => resolveStorageFolderSlugPath(name), [name])

  const handleCreate = useCallback(async () => {
    const folderName = name.trim()
    if (!folderName) {
      toast.error("Vui lòng nhập tên thư mục")
      return
    }

    const { parentPath, resourceType } = resolveCreateFolderParent(
      realm,
      parentFolderPath
    )

    setCreating(true)
    try {
      const result = await createStorageFolder({
        folderName,
        parentPath,
        resourceType,
        allowedExtensions: isLevel1Create
          ? extensionsFromGroupIds(resourceType, extensionGroups)
          : undefined,
      })
      toast.success(
        `Đã tạo thư mục «${result.folderLabel ?? result.folderName}»`
      )
      setName("")
      setOpen(false)
      await onCreated(result.folderPath)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Không tạo được thư mục")
    } finally {
      setCreating(false)
    }
  }, [
    extensionGroups,
    isLevel1Create,
    name,
    onCreated,
    parentFolderPath,
    realm,
  ])

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger className="w-auto">
        <Button
          type="button"
          variant="outline"
          size={size}
          disabled={disabled || creating}
          className="shrink-0 gap-1.5"
        >
          {creating ? (
            <Loader2 className="size-4 animate-spin" />
          ) : (
            <FolderPlus className="size-4" />
          )}
          Tạo folder
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="w-[min(100vw-2rem,22rem)] space-y-3"
        align="start"
      >
        <div className="space-y-1">
          <p className="text-sm font-medium">Tạo thư mục mới</p>
          <p className="text-xs text-muted-foreground">
            Trong «{parentLabel}». Nhập tên tiếng Việt — hệ thống tự tạo slug
            cho đường dẫn (vd. Sự kiện 1 → su-kien-1).
          </p>
        </div>
        <div className="space-y-2">
          <Label htmlFor="create-folder-name">Tên hiển thị</Label>
          <Input
            id="create-folder-name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="vd. Sự kiện 1, Avatars, 2026/06/Hội thảo"
            disabled={creating}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                void handleCreate()
              }
            }}
          />
          {slugPreview ? (
            <div className="rounded-md border border-border/70 bg-muted/20 px-2.5 py-2 text-xs">
              <p>
                <span className="text-muted-foreground">Nhãn: </span>
                <span className="font-medium text-foreground">
                  {slugPreview.leafLabel}
                </span>
              </p>
              <p className="mt-1 font-mono text-[11px] text-muted-foreground">
                slug: {slugPreview.slugPath}
              </p>
            </div>
          ) : null}
        </div>
        {isLevel1Create ? (
          <FileStorageAllowedExtensionsPicker
            realm={realm}
            value={extensionGroups}
            onChange={setExtensionGroups}
            disabled={creating}
          />
        ) : null}
        <div className="flex justify-end gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setOpen(false)}
            disabled={creating}
          >
            Hủy
          </Button>
          <Button
            type="button"
            size="sm"
            onClick={() => void handleCreate()}
            disabled={creating || !name.trim()}
          >
            {creating ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <FolderPlus className="size-4" />
            )}
            Tạo
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

"use client"

import { useCallback, useState } from "react"
import { Button } from "@ui/components/button"
import { ConfirmActionDialog } from "@ui/components/dialogs"
import { toast } from "@ui/components/sonner"
import { deleteStorageFolder } from "@workspace/admin-app/lib/admin-uploads"
import { FolderX, Loader2 } from "lucide-react"
import type { StorageRealm } from "./types"
import { resolveStorageFolderDiskPath } from "./utils"

type FileStorageDeleteFolderButtonProps = {
  realm: StorageRealm
  folderPath: string
  folderLabel: string
  onDeleted: () => Promise<void>
  disabled?: boolean
}

export function FileStorageDeleteFolderButton({
  realm,
  folderPath,
  folderLabel,
  onDeleted,
  disabled = false,
}: FileStorageDeleteFolderButtonProps) {
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const diskPath = resolveStorageFolderDiskPath(realm, folderPath)

  const runDelete = useCallback(async () => {
    if (!diskPath) return

    setDeleting(true)
    const pending = toast.loading("Đang xóa thư mục…")
    try {
      await deleteStorageFolder(diskPath)
      toast.success(`Đã xóa thư mục «${folderLabel}»`, { id: pending })
      setConfirmOpen(false)
      await onDeleted()
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Không xóa được thư mục",
        {
          id: pending,
        }
      )
    } finally {
      setDeleting(false)
    }
  }, [diskPath, folderLabel, onDeleted])

  if (!diskPath) return null

  return (
    <>
      <Button
        type="button"
        variant="outline"
        size="sm"
        className="gap-1.5 text-destructive hover:text-destructive"
        onClick={() => setConfirmOpen(true)}
        disabled={disabled || deleting}
      >
        {deleting ? (
          <Loader2 className="size-4 animate-spin" />
        ) : (
          <FolderX className="size-4" />
        )}
        Xóa folder
      </Button>

      <ConfirmActionDialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title={`Xóa thư mục «${folderLabel}»?`}
        icon={<FolderX className="size-5 text-destructive" />}
        description={
          <>
            Toàn bộ file bên trong sẽ bị xóa vĩnh viễn.
            <br />
            <br />
            Đường dẫn:{" "}
            <span className="font-mono text-foreground">{diskPath}</span>
            <br />
            <br />
            Thao tác không thể hoàn tác.
          </>
        }
        confirmLabel="Xóa thư mục"
        cancelLabel="Huỷ"
        confirmDestructive
        confirmLoading={deleting}
        onConfirm={runDelete}
      />
    </>
  )
}

"use client"

import { Button } from "@ui/components/button"
import { AdminEmptyState } from "@ui/components/admin"
import {
  ArchiveRestore,
  CloudUpload,
  FileImage,
  FolderOpen,
  Loader2,
  Upload,
} from "lucide-react"

type FileStorageGlobalEmptyProps = {
  canUpload: boolean
  uploading: boolean
  importing: boolean
  onUpload: () => void
  onImport: () => void
}

export function FileStorageGlobalEmpty({
  canUpload,
  uploading,
  importing,
  onUpload,
  onImport,
}: FileStorageGlobalEmptyProps) {
  return (
    <AdminEmptyState
      icon={<FolderOpen className="text-primary" />}
      title="Kho lưu trữ đang trống"
      description="Chưa có ảnh, video hay tài liệu nào. Tải lên từng file hoặc khôi phục toàn bộ kho từ file ZIP backup."
      hints={[
        "Tải lên: chọn ảnh, video, PDF hoặc tài liệu — hệ thống tự phân loại theo folder.",
        "Khôi phục kho: chọn file ZIP đã xuất trước đó, chọn Ghi đè để import đầy đủ.",
        "Sau khi có file, chọn dạng lưu trữ (Hình ảnh / Tệp tin / Video) rồi duyệt theo folder hệ thống.",
      ]}
      actions={
        canUpload ? (
          <>
            <Button
              type="button"
              onClick={onUpload}
              disabled={uploading || importing}
            >
              {uploading ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <Upload className="size-4" />
              )}
              {uploading ? "Đang tải lên…" : "Tải lên file"}
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={onImport}
              disabled={uploading || importing}
            >
              {importing ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <ArchiveRestore className="size-4" />
              )}
              {importing ? "Đang khôi phục…" : "Khôi phục từ ZIP"}
            </Button>
          </>
        ) : undefined
      }
    />
  )
}

type FileStorageTabEmptyProps = {
  tabLabel: string
  canUpload: boolean
  uploading: boolean
  onUpload?: () => void
}

export function FileStorageTabEmpty({
  tabLabel,
  canUpload,
  uploading,
  onUpload,
}: FileStorageTabEmptyProps) {
  return (
    <AdminEmptyState
      size="compact"
      icon={<FileImage className="text-primary" />}
      title={`Chưa có file trong «${tabLabel}»`}
      description="Tab này tương ứng với một folder hệ thống. Tải file lên hoặc khôi phục kho từ ZIP để thấy nội dung tại đây."
      hints={[
        `File thuộc folder «${tabLabel}» sẽ xuất hiện trong tab này.`,
        "Ảnh và video có thể xem trực tiếp; tài liệu tải về hoặc mở link.",
      ]}
      actions={
        canUpload && onUpload ? (
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={onUpload}
            disabled={uploading}
          >
            {uploading ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <CloudUpload className="size-4" />
            )}
            {uploading ? "Đang tải…" : "Tải lên vào kho"}
          </Button>
        ) : undefined
      }
    />
  )
}

"use client"

import type { ReactNode } from "react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { Input } from "@ui/components/input"
import { Tooltip, TooltipContent, TooltipTrigger } from "@ui/components/tooltip"
import { cn } from "@ui/lib/utils"
import {
  ChevronRight,
  FolderOpen,
  Home,
  Layers,
  Loader2,
  Search,
  X,
} from "lucide-react"
import { useFolderNavSearch } from "./_hooks"
import {
  diskPathToNavPath,
  formatStorageFolderLabel,
  formatStorageFolderPathHint,
  normalizeHomeFolderPath,
} from "./folder-domain"
import type { StorageRealm, StorageTab } from "./types"

type FileStorageFolderNavProps = {
  realm: StorageRealm
  realmLabel: string
  breadcrumb: Array<{ id: string; label: string }>
  childFolders: StorageTab[]
  activeFolderPath: string
  includeDescendants: boolean
  onIncludeDescendantsChange: (value: boolean) => void
  onNavigate: (folderPath: string) => void
  foldersRefreshKey?: number
  /** Khi set — nút Home quay về folder này thay vì root realm. */
  homeFolderPath?: string
  actions?: ReactNode
  className?: string
}

export function FileStorageFolderNav({
  realm,
  realmLabel,
  breadcrumb,
  childFolders,
  activeFolderPath,
  includeDescendants,
  onIncludeDescendantsChange,
  onNavigate,
  foldersRefreshKey = 0,
  homeFolderPath,
  actions,
  className,
}: FileStorageFolderNavProps) {
  const homePath = normalizeHomeFolderPath(homeFolderPath)
  const {
    searchInputId,
    listId,
    searchRootRef,
    folderQuery,
    onQueryChange,
    openSearch,
    clearSearch,
    loadingFolders,
    searchResults,
    searchState,
    pickSearchResult,
    navigateAndClear,
  } = useFolderNavSearch(realm, foldersRefreshKey)

  const currentLabel = breadcrumb[breadcrumb.length - 1]?.label ?? realmLabel

  return (
    <section
      className={cn(
        "overflow-hidden rounded-xl border border-border/70 bg-card shadow-sm",
        className
      )}
    >
      <div className="flex flex-col gap-2 px-3 py-2.5 sm:flex-row sm:items-center sm:justify-between sm:gap-3">
        <div className="min-w-0 flex-1 space-y-1">
          <nav
            aria-label="Đường dẫn thư mục"
            className="flex min-w-0 items-center gap-0.5 overflow-x-auto text-sm [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          >
            <Button
              type="button"
              variant={
                activeFolderPath === homePath || (!activeFolderPath && !homePath)
                  ? "secondary"
                  : "ghost"
              }
              size="sm"
              className="h-7 shrink-0 gap-1 px-2 text-xs"
              onClick={() => navigateAndClear(homePath, onNavigate)}
            >
              <Home className="size-3.5" />
              <span className="max-w-[8rem] truncate">{realmLabel}</span>
            </Button>
            {breadcrumb.map((crumb) => (
              <div
                key={crumb.id}
                className="flex shrink-0 items-center gap-0.5"
              >
                <ChevronRight
                  className="size-3.5 shrink-0 text-muted-foreground/70"
                  aria-hidden
                />
                <Button
                  type="button"
                  variant={
                    activeFolderPath === crumb.id ? "secondary" : "ghost"
                  }
                  size="sm"
                  className="h-7 max-w-[10rem] truncate px-2 text-xs"
                  onClick={() => navigateAndClear(crumb.id, onNavigate)}
                  title={crumb.label}
                >
                  {crumb.label}
                </Button>
              </div>
            ))}
          </nav>
          <p className="truncate text-[11px] text-muted-foreground">
            {includeDescendants
              ? `Đang xem «${currentLabel}» và mọi thư mục con`
              : `Đang xem file trong «${currentLabel}»`}
          </p>
        </div>

        <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5">
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  type="button"
                  variant={includeDescendants ? "secondary" : "outline"}
                  size="sm"
                  className="size-8 p-0"
                  onClick={() =>
                    onIncludeDescendantsChange(!includeDescendants)
                  }
                  aria-pressed={includeDescendants}
                  aria-label={
                    includeDescendants
                      ? "Đang gồm cả subfolder — bấm để chỉ folder này"
                      : "Chỉ folder này — bấm để gồm subfolder"
                  }
                />
              }
            >
              <Layers className="size-4" />
            </TooltipTrigger>
            <TooltipContent side="bottom">
              {includeDescendants ? "Gồm cả subfolder" : "Chỉ folder này"}
            </TooltipContent>
          </Tooltip>

          <div
            ref={searchRootRef}
            className="relative w-full min-w-[11rem] sm:w-52"
          >
            <Search
              className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground"
              aria-hidden
            />
            <Input
              id={searchInputId}
              value={folderQuery}
              onChange={(e) => onQueryChange(e.target.value)}
              onFocus={openSearch}
              placeholder="Tìm folder…"
              className="h-8 border-border/80 bg-background pr-7 pl-8 text-xs shadow-none"
              role="combobox"
              aria-expanded={searchState.showSearchPanel}
              aria-controls={searchState.showSearchPanel ? listId : undefined}
              aria-autocomplete="list"
              autoComplete="off"
            />
            {folderQuery ? (
              <button
                type="button"
                className="absolute top-1/2 right-1.5 -translate-y-1/2 rounded p-0.5 text-muted-foreground hover:bg-muted hover:text-foreground"
                onClick={clearSearch}
                aria-label="Xóa tìm kiếm"
              >
                <X className="size-3.5" />
              </button>
            ) : null}

            {searchState.showSearchPanel ? (
              <div
                id={listId}
                role="listbox"
                className="absolute top-[calc(100%+4px)] z-50 max-h-56 w-full overflow-y-auto rounded-lg border border-border bg-popover p-1 shadow-md"
              >
                {loadingFolders || searchState.isDebouncing ? (
                  <p className="flex items-center gap-2 px-2.5 py-2 text-xs text-muted-foreground">
                    <Loader2 className="size-3.5 animate-spin" />
                    Đang tìm…
                  </p>
                ) : searchResults.length > 0 ? (
                  searchResults.map((folder) => {
                    const navPath = diskPathToNavPath(realm, folder.path)
                    const label = formatStorageFolderLabel(folder)
                    const hint = formatStorageFolderPathHint(folder.path, realm)
                    return (
                      <button
                        key={folder.path}
                        type="button"
                        role="option"
                        aria-selected={activeFolderPath === navPath}
                        className={cn(
                          "flex w-full flex-col items-start rounded-md px-2.5 py-1.5 text-left transition-colors hover:bg-accent",
                          activeFolderPath === navPath && "bg-accent/70"
                        )}
                        onMouseDown={(e) => e.preventDefault()}
                        onClick={() => pickSearchResult(folder.path, onNavigate)}
                      >
                        <span className="text-xs font-medium text-foreground">
                          {label}
                        </span>
                        <span className="truncate font-mono text-[10px] text-muted-foreground">
                          {hint}
                        </span>
                      </button>
                    )
                  })
                ) : (
                  <p className="px-2.5 py-2 text-xs text-muted-foreground">
                    Không tìm thấy folder.
                  </p>
                )}
              </div>
            ) : null}
          </div>

          {actions ? (
            <div className="flex items-center gap-1.5">{actions}</div>
          ) : null}
        </div>
      </div>

      {!searchState.isSearching && childFolders.length > 0 ? (
        <div className="flex gap-1.5 overflow-x-auto border-t border-border/50 bg-muted/15 px-3 py-2 [scrollbar-width:thin]">
          {childFolders.map((folder) => (
            <button
              key={folder.id}
              type="button"
              className="inline-flex shrink-0 items-center gap-1 rounded-md border border-border/60 bg-background px-2 py-1 text-xs transition-colors hover:border-primary/30 hover:bg-primary/5"
              onClick={() => navigateAndClear(folder.id, onNavigate)}
            >
              <FolderOpen className="size-3.5 text-amber-600/90 dark:text-amber-500" />
              <span className="font-medium">{folder.label}</span>
              <Badge
                variant="secondary"
                className="h-4 px-1.5 text-[10px] tabular-nums"
              >
                {folder.count}
              </Badge>
            </button>
          ))}
        </div>
      ) : null}
    </section>
  )
}

"use client"

import { useEffect, useMemo, useState } from "react"
import { cn } from "@ui/lib/utils"
import {
  ChevronDown,
  ChevronRight,
  Folder,
  FolderOpen,
  HardDrive,
} from "lucide-react"
import type { StorageFolderTreeNode } from "./utils"
import {
  buildRealmFolderTree,
  buildStorageFolderTree,
  collectStorageFolderExpandablePaths,
  expandStorageFolderAncestors,
  filterStorageFolderTree,
} from "./utils"
import type { FolderItem } from "@workspace/admin-app/lib/admin-uploads"
import type { StorageRealm } from "./types"

export const STORAGE_ROOT_IMAGES = "__root_images__"
export const STORAGE_ROOT_FILES = "__root_files__"
export const STORAGE_ROOT_VIDEOS = "__root_videos__"
export const STORAGE_ROOT_AUDIO = "__root_audio__"

export type FileStorageVirtualRoot = {
  value: string
  label: string
}

type FileStorageFolderTreeProps = {
  folders: FolderItem[]
  filter: string
  selectedPath: string
  onSelect: (path: string) => void
  disabled?: boolean
  /** Hiện 2 nút gốc ảnh/files — dùng khi chọn thư mục cha (tab Tạo mới). */
  showVirtualRoots?: boolean
  /** Gốc ảnh tùy chỉnh (vd. chỉ «images» khi di chuyển). */
  virtualRoots?: FileStorageVirtualRoot[]
  /** Bỏ nút images/files/videos — cây bắt đầu từ admincp, docs, … */
  realm?: StorageRealm
  /** Tự mở các nhánh cấp 1 khi render cây. */
  autoExpandRoots?: boolean
  className?: string
}

type TreeRowProps = {
  node: StorageFolderTreeNode
  depth: number
  selectedPath: string
  expandedPaths: Set<string>
  onToggleExpand: (path: string) => void
  onSelect: (path: string) => void
  disabled?: boolean
}

function TreeRow({
  node,
  depth,
  selectedPath,
  expandedPaths,
  onToggleExpand,
  onSelect,
  disabled,
}: TreeRowProps) {
  const hasChildren = node.children.length > 0
  const isExpanded = expandedPaths.has(node.path)
  const isSelected = selectedPath === node.path

  return (
    <div role="none">
      <div
        className={cn(
          "flex w-full items-center gap-0.5 rounded-md pr-1 text-sm transition-colors",
          isSelected
            ? "bg-primary/10 text-foreground ring-1 ring-primary/20"
            : "text-muted-foreground hover:bg-muted/70 hover:text-foreground"
        )}
        style={{ paddingLeft: `${8 + depth * 16}px` }}
      >
        {hasChildren ? (
          <button
            type="button"
            aria-label={isExpanded ? "Thu gọn" : "Mở rộng"}
            disabled={disabled}
            onClick={() => onToggleExpand(node.path)}
            className="flex size-7 shrink-0 items-center justify-center rounded-md hover:bg-muted"
          >
            {isExpanded ? (
              <ChevronDown className="size-4" />
            ) : (
              <ChevronRight className="size-4" />
            )}
          </button>
        ) : (
          <span className="size-7 shrink-0" aria-hidden />
        )}
        <button
          type="button"
          disabled={disabled}
          onClick={() => onSelect(node.path)}
          className="flex min-w-0 flex-1 items-center gap-2 py-1.5 text-left"
        >
          {isSelected ? (
            <FolderOpen className="size-4 shrink-0 text-primary" />
          ) : (
            <Folder className="size-4 shrink-0 text-amber-600/90 dark:text-amber-500" />
          )}
          <span className="truncate font-medium">{node.name}</span>
          <span className="truncate font-mono text-[10px] opacity-60">
            {node.path}
          </span>
        </button>
      </div>
      {hasChildren && isExpanded
        ? node.children.map((child) => (
            <TreeRow
              key={child.path}
              node={child}
              depth={depth + 1}
              selectedPath={selectedPath}
              expandedPaths={expandedPaths}
              onToggleExpand={onToggleExpand}
              onSelect={onSelect}
              disabled={disabled}
            />
          ))
        : null}
    </div>
  )
}

export function FileStorageFolderTree({
  folders,
  filter,
  selectedPath,
  onSelect,
  disabled = false,
  showVirtualRoots = false,
  virtualRoots,
  realm,
  autoExpandRoots = false,
  className,
}: FileStorageFolderTreeProps) {
  const [expandedPaths, setExpandedPaths] = useState<Set<string>>(new Set())

  const tree = useMemo(
    () =>
      realm
        ? buildRealmFolderTree(folders, realm)
        : buildStorageFolderTree(folders),
    [folders, realm]
  )
  const filteredTree = useMemo(
    () => filterStorageFolderTree(tree, filter),
    [filter, tree]
  )

  useEffect(() => {
    setExpandedPaths((prev) => {
      const next = new Set(prev)
      if (autoExpandRoots) {
        for (const node of filteredTree) {
          if (node.children.length > 0) next.add(node.path)
        }
      }
      if (
        selectedPath &&
        selectedPath !== STORAGE_ROOT_IMAGES &&
        selectedPath !== STORAGE_ROOT_FILES &&
        selectedPath !== STORAGE_ROOT_VIDEOS &&
        selectedPath !== STORAGE_ROOT_AUDIO
      ) {
        expandStorageFolderAncestors(selectedPath, next)
      }
      if (filter.trim()) {
        collectStorageFolderExpandablePaths(filteredTree, next)
      }
      return next
    })
  }, [autoExpandRoots, filter, filteredTree, selectedPath])

  const toggleExpand = (path: string) => {
    setExpandedPaths((prev) => {
      const next = new Set(prev)
      if (next.has(path)) next.delete(path)
      else next.add(path)
      return next
    })
  }

  const virtualRootRow = (value: string, label: string) => {
    const isSelected = selectedPath === value
    return (
      <button
        key={value}
        type="button"
        disabled={disabled}
        onClick={() => onSelect(value)}
        className={cn(
          "flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-sm transition-colors",
          isSelected
            ? "bg-primary/10 text-foreground ring-1 ring-primary/20"
            : "text-muted-foreground hover:bg-muted/70 hover:text-foreground"
        )}
      >
        <HardDrive className="size-4 shrink-0 text-primary" />
        <span className="font-medium">{label}</span>
      </button>
    )
  }

  const rootOptions = virtualRoots?.length
    ? virtualRoots
    : showVirtualRoots
      ? [
          {
            value: STORAGE_ROOT_IMAGES,
            label: "Gốc — thư mục ảnh / media",
          },
          {
            value: STORAGE_ROOT_FILES,
            label: "Gốc — thư mục tệp tin (files/)",
          },
          {
            value: STORAGE_ROOT_VIDEOS,
            label: "Gốc — thư mục video (videos/)",
          },
          {
            value: STORAGE_ROOT_AUDIO,
            label: "Gốc — thư mục âm thanh (audio/)",
          },
        ]
      : []

  const isEmpty = filteredTree.length === 0 && rootOptions.length === 0

  return (
    <div className={cn("space-y-1 p-1", className)}>
      {rootOptions.length > 0 ? (
        <div className="mb-2 space-y-1 border-b border-border/60 pb-2">
          {rootOptions.map((root) => virtualRootRow(root.value, root.label))}
        </div>
      ) : null}

      {isEmpty ? (
        <p className="px-2 py-4 text-center text-sm text-muted-foreground">
          Không có thư mục khớp tìm kiếm.
        </p>
      ) : (
        filteredTree.map((node) => (
          <TreeRow
            key={node.path}
            node={node}
            depth={0}
            selectedPath={selectedPath}
            expandedPaths={expandedPaths}
            onToggleExpand={toggleExpand}
            onSelect={onSelect}
            disabled={disabled}
          />
        ))
      )}
    </div>
  )
}

"use client"

import { ConfirmActionDialog } from "@ui/components/dialogs"
import { ArchiveRestore } from "lucide-react"

export type FileStorageImportConfirmState = {
  file: File
  sizeMb: string
  step: "restore" | "overwrite"
}

type FileStorageImportConfirmDialogsProps = {
  state: FileStorageImportConfirmState | null
  importing: boolean
  onClose: () => void
  onConfirmRestore: () => void
  onConfirmOverwrite: () => void
  onSkipOverwrite: () => void
}

export function FileStorageImportConfirmDialogs({
  state,
  importing,
  onClose,
  onConfirmRestore,
  onConfirmOverwrite,
  onSkipOverwrite,
}: FileStorageImportConfirmDialogsProps) {
  const fileName = state?.file.name ?? ""

  return (
    <>
      <ConfirmActionDialog
        open={state?.step === "restore"}
        onOpenChange={(open) => {
          if (!open) onClose()
        }}
        title="Khôi phục kho lưu trữ?"
        icon={<ArchiveRestore className="size-5 text-primary" />}
        description={
          <>
            Khôi phục từ file <strong>{fileName}</strong>
            {state?.sizeMb ? ` (${state.sizeMb} MB)` : ""}.
            <br />
