            <strong>{fileName}</strong>?
            <br />
            <br />
            <strong>Ghi đè tất cả</strong> — thay file trùng bằng bản trong ZIP
            (khuyến nghị khi khôi phục đầy đủ).
            <br />
            <strong>Chỉ thêm file mới</strong> — bỏ qua file đã tồn tại.
          </>
        }
        confirmLabel="Ghi đè tất cả"
        cancelLabel="Chỉ thêm file mới"
        confirmDestructive
        confirmLoading={importing}
        onConfirm={onConfirmOverwrite}
      />
    </>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useState } from "react"

import { Button } from "@ui/components/button"

import {
  PanelDialog,
  PanelDialogDestination,
  PanelDialogEmpty,
  PanelDialogHint,
  PanelDialogLoading,
  PanelDialogSearch,
  PanelDialogTreePanel,
} from "@ui/components/dialogs"

import { Tabs } from "@ui/components/tabs"
import { AdminListTabsList, AdminListTabsTrigger } from "@ui/components/admin"

import { toast } from "@ui/components/sonner"

import {
  bulkMoveStorageFiles,
  fetchStorageFolders,
  type FolderItem,
} from "@workspace/admin-app/lib/admin-uploads"

import { FolderInput, Loader2 } from "lucide-react"

import { FileStorageFolderTree } from "./file-storage-folder-tree"

import type { FileStorageRow, StorageRealm } from "./types"

import {
  REALM_STORAGE_LABELS,
  buildRealmVirtualRoots,
  filterFoldersByRealm,
} from "./utils"

type FileStorageMoveDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  selectedRows: FileStorageRow[]
  onMoved: () => Promise<void>
}

function parseFolderList(payload: unknown): FolderItem[] {
  if (Array.isArray(payload)) return payload

  if (
    payload &&
    typeof payload === "object" &&
    Array.isArray((payload as { data?: unknown }).data)
  ) {
    return (payload as { data: FolderItem[] }).data
  }

  return []
}

export function FileStorageMoveDialog({
  open,

  onOpenChange,

  selectedRows,

  onMoved,
}: FileStorageMoveDialogProps) {
  const [folders, setFolders] = useState<FolderItem[]>([])

  const [loadingFolders, setLoadingFolders] = useState(false)

  const [moving, setMoving] = useState(false)

  const [filter, setFilter] = useState("")

  const [destinationRealm, setDestinationRealm] =
    useState<StorageRealm>("images")

  const [selectedPath, setSelectedPath] = useState("")

  const loadFolders = useCallback(async () => {
    setLoadingFolders(true)

    try {
      const list = await fetchStorageFolders()

      setFolders(parseFolderList(list))
    } catch (err) {
      setFolders([])

      toast.error(
        err instanceof Error ? err.message : "Không tải được danh sách thư mục"
      )
    } finally {
      setLoadingFolders(false)
    }
  }, [])

  useEffect(() => {
    if (!open) return

    setFilter("")

    setSelectedPath("")

    setDestinationRealm("images")

    void loadFolders()
  }, [loadFolders, open])

  const realmFolders = useMemo(
    () => filterFoldersByRealm(folders, destinationRealm),

    [destinationRealm, folders]
  )

  const virtualRoots = useMemo(
    () => buildRealmVirtualRoots(destinationRealm),
    [destinationRealm]
  )

  const handleMove = useCallback(async () => {
    if (!selectedPath.trim()) {
      toast.error("Vui lòng chọn thư mục đích")

      return
    }

    if (!selectedRows.length) return

    setMoving(true)

    const pending = toast.loading(`Đang di chuyển ${selectedRows.length} file…`)

    try {
      const result = await bulkMoveStorageFiles(
        selectedRows.map((row) => row.relativePath),

        selectedPath.trim()
      )

      const parts = [`Đã di chuyển ${result.moved} file`]

      if (result.renamed > 0) {
        parts.push(`${result.renamed} file đổi tên tránh trùng`)
      }

      if (result.skipped > 0) parts.push(`${result.skipped} bỏ qua`)

      toast.success(parts.join(" · "), { id: pending })

      if (result.errors.length > 0) {
        toast.error(
          result.errors
            .slice(0, 2)
            .map((e) => e.message)
            .join("; ")
        )
      }

      await onMoved()

      onOpenChange(false)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Lỗi di chuyển file", {
        id: pending,
      })
    } finally {
      setMoving(false)
    }
  }, [onMoved, onOpenChange, selectedPath, selectedRows])

  return (
    <PanelDialog
      open={open}
      onOpenChange={onOpenChange}
      icon={<FolderInput />}
      title={`Di chuyển ${selectedRows.length} file`}
      description="Chọn loại lưu trữ và thư mục đích. Hỗ trợ di chuyển giữa images, files, videos và audio."
      footerLeading={
        <PanelDialogDestination
          label="Thư mục đích"
          value={selectedPath || "(chưa chọn)"}
          ready={Boolean(selectedPath.trim())}
        />
      }
      footer={
        <>
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={moving}
          >
            Hủy
          </Button>

          <Button
            type="button"
            onClick={() => void handleMove()}
            disabled={moving || !selectedPath.trim()}
          >
            {moving ? <Loader2 className="size-4 animate-spin" /> : null}
            Di chuyển
          </Button>
        </>
      }
    >
      <Tabs
        value={destinationRealm}
        onValueChange={(value) => {
          setDestinationRealm(value as StorageRealm)

          setSelectedPath("")
        }}
      >
        <AdminListTabsList
          wrap
          fullWidth
          className="grid grid-cols-2 sm:grid-cols-4"
        >
          {(Object.keys(REALM_STORAGE_LABELS) as StorageRealm[]).map(
            (realm) => (
              <AdminListTabsTrigger key={realm} value={realm} stretch>
                {REALM_STORAGE_LABELS[realm]}
              </AdminListTabsTrigger>
            )
          )}
        </AdminListTabsList>
      </Tabs>

      <PanelDialogSearch
        id="move-folder-search"
        label="Tìm thư mục đích"
        value={filter}
        onChange={setFilter}
        placeholder="admincp, avatars, docs…"
        disabled={loadingFolders || moving}
      />

      {loadingFolders ? (
        <PanelDialogLoading label="Đang tải cây thư mục…" />
      ) : folders.length === 0 ? (
        <PanelDialogEmpty>
          Không tải được danh sách thư mục. Thử đóng dialog và mở lại.
        </PanelDialogEmpty>
      ) : realmFolders.length === 0 ? (
        <div className="space-y-3">
          <PanelDialogTreePanel heightClassName="h-52">
            <FileStorageFolderTree
              folders={[]}
              filter={filter}
              selectedPath={selectedPath}
              onSelect={setSelectedPath}
              disabled={moving}
              virtualRoots={virtualRoots}
            />
          </PanelDialogTreePanel>

          <PanelDialogHint>
            Chưa có thư mục con trong «{REALM_STORAGE_LABELS[destinationRealm]}
            ». Có thể chọn thư mục gốc ở trên.
          </PanelDialogHint>
        </div>
      ) : (
        <PanelDialogTreePanel>
          <FileStorageFolderTree
            folders={folders}
            filter={filter}
            selectedPath={selectedPath}
            onSelect={setSelectedPath}
            disabled={moving}
            realm={destinationRealm}
            virtualRoots={virtualRoots}
            autoExpandRoots
          />
        </PanelDialogTreePanel>
      )}
    </PanelDialog>
  )
}

"use client"

import { useMemo, type MutableRefObject } from "react"
import { AdminStoragePickerPanel } from "@ui/components/admin/storage"
import { createAdminStoragePickerAdapters } from "@workspace/admin-app/lib/admin-storage-picker-adapters"
import {
  buildProductStorageFolderScope,
  buildProductStorageUploadConfig,
} from "@workspace/admin-app/lib/build-product-storage-picker-config"
import type { ProductImageUploadContext } from "@workspace/admin-app/lib/product-image-storage-stub"

export type { ProductImageUploadContext }

export type FileStoragePickerPanelProps = {
  onPick: (urls: string[]) => void
  imagesOnly?: boolean
  multiSelect?: boolean
  resolveProductUpload?: () => ProductImageUploadContext | null
  className?: string
  onSelectionCountChange?: (count: number) => void
  confirmPickRef?: MutableRefObject<(() => void) | null>
  clearSelectionRef?: MutableRefObject<(() => void) | null>
}

/** @deprecated Dùng `AdminStoragePickerPanel` từ `@ui/components/admin/storage` — wrapper giữ tương thích import cũ. */
export function FileStoragePickerPanel({
  onPick,
  imagesOnly = true,
  multiSelect = true,
  resolveProductUpload,
  className,
  onSelectionCountChange,
  confirmPickRef,
  clearSelectionRef,
}: FileStoragePickerPanelProps) {
  const adapters = useMemo(() => createAdminStoragePickerAdapters(), [])
  const productCtx = resolveProductUpload?.() ?? null

  const folderScope = useMemo(() => {
    if (!resolveProductUpload || !productCtx) return null
    return buildProductStorageFolderScope(productCtx)
  }, [productCtx, resolveProductUpload])

  const upload = useMemo(() => {
    if (!resolveProductUpload) return undefined
    return buildProductStorageUploadConfig(resolveProductUpload, productCtx)
  }, [productCtx, resolveProductUpload])

  return (
    <AdminStoragePickerPanel
      adapters={adapters}
      onPick={onPick}
      imagesOnly={imagesOnly}
      multiSelect={multiSelect}
      folderScope={folderScope}
      upload={upload}
      canDelete
      className={className}
      onSelectionCountChange={onSelectionCountChange}
      confirmPickRef={confirmPickRef}
      clearSelectionRef={clearSelectionRef}
    />
  )
}

"use client"

import { useCallback, useMemo, useState } from "react"

import { Button } from "@ui/components/button"

import { PanelDialog, PanelDialogInfoCard } from "@ui/components/dialogs"

import { ScrollArea } from "@ui/components/scroll-area"

import { toast } from "@ui/components/sonner"

import { reorganizeDateStorageFolders } from "@workspace/admin-app/lib/admin-uploads"

import type { ReorganizeDateFoldersResult } from "@workspace/api-client"

import { FolderTree, Loader2, Shuffle } from "lucide-react"

import type { StorageRealm } from "./types"

import { resolveReorganizeScopePath } from "./utils"

type FileStorageReorganizeDialogProps = {
  open: boolean

  onOpenChange: (open: boolean) => void

  realm: StorageRealm

  activeFolderPath: string

  scopeLabel: string

  onCompleted: () => Promise<void>
}

export function FileStorageReorganizeDialog({
  open,

  onOpenChange,

  realm,

  activeFolderPath,

  scopeLabel,

  onCompleted,
}: FileStorageReorganizeDialogProps) {
  const [loading, setLoading] = useState(false)

  const [preview, setPreview] = useState<ReorganizeDateFoldersResult | null>(
    null
  )

  const scopePath = useMemo(
    () => resolveReorganizeScopePath(realm, activeFolderPath),

    [activeFolderPath, realm]
  )

  const resetState = useCallback(() => {
    setPreview(null)

    setLoading(false)
  }, [])

  const handleOpenChange = useCallback(
    (next: boolean) => {
      if (!next) resetState()

      onOpenChange(next)
    },

    [onOpenChange, resetState]
  )

  const runReorganize = useCallback(
    async (dryRun: boolean) => {
      setLoading(true)

      const pending = toast.loading(
        dryRun ? "Đang xem trước cấu trúc lại…" : "Đang cấu trúc lại folder…"
      )

      try {
        const result = await reorganizeDateStorageFolders({
          scopePath,

          dryRun,
        })

        setPreview(result)

        if (dryRun) {
          toast.success(
            `Tìm thấy ${result.candidates} file cần gom về folder chính`,

            { id: pending }
          )

          return
        }

        const parts = [`Đã di chuyển ${result.moved}/${result.candidates} file`]

        if (result.renamed > 0)
          parts.push(`${result.renamed} file đổi tên tránh trùng`)

        if (result.removedDirs > 0) {
          parts.push(`dọn ${result.removedDirs} folder ngày trống`)
        }

        if (result.skipped > 0) parts.push(`${result.skipped} bỏ qua`)

        toast.success(parts.join(" · "), { id: pending })

        if (result.errors.length > 0) {
          toast.error(
            result.errors
              .slice(0, 2)
              .map((e) => e.message)
              .join("; ")
          )
        }

        await onCompleted()

        handleOpenChange(false)
      } catch (err) {
        toast.error(
          err instanceof Error ? err.message : "Lỗi cấu trúc lại folder",

          { id: pending }
        )
      } finally {
        setLoading(false)
      }
    },

    [handleOpenChange, onCompleted, scopePath]
  )

  return (
    <PanelDialog
      open={open}
      onOpenChange={handleOpenChange}
      icon={<Shuffle />}
      title="Cấu trúc lại folder theo ngày"
      description={
        <>
          Gom file từ các folder{" "}
          <span className="font-mono text-foreground">YYYY/MM/DD</span>,{" "}
          <span className="font-mono text-foreground">YYYY/MM</span> hoặc{" "}
          <span className="font-mono text-foreground">YYYY</span> về folder
          chính trong phạm vi đang xem.
        </>
      }
      footer={
        <>
          <Button
            type="button"
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={loading}
          >
            Đóng
          </Button>

          <Button
            type="button"
            variant="outline"
            onClick={() => void runReorganize(true)}
            disabled={loading}
          >
            {loading ? <Loader2 className="size-4 animate-spin" /> : null}
            Xem trước
          </Button>

          <Button
            type="button"
            onClick={() => void runReorganize(false)}
            disabled={loading || (preview !== null && preview.candidates === 0)}
          >
            {loading ? <Loader2 className="size-4 animate-spin" /> : null}
            Cấu trúc lại
          </Button>
        </>
      }
    >
      <PanelDialogInfoCard icon={<FolderTree />} title="Phạm vi">
        <p>{scopeLabel}</p>

        <p className="mt-1 font-mono text-xs">{scopePath}</p>

        <p className="mt-2 text-xs">
          Ví dụ:{" "}
          <span className="font-mono">images/avatars/2026/05/15/a.jpg</span> →{" "}
          <span className="font-mono">images/avatars/a.jpg</span>. Folder ngày
          trống sẽ được dọn sau khi di chuyển.
        </p>
      </PanelDialogInfoCard>

      {preview ? (
        <div className="space-y-2">
          <p className="text-sm font-medium">
            Xem trước ({preview.candidates} file)
          </p>

          {preview.candidates === 0 ? (
            <p className="text-sm text-muted-foreground">
              Không có file nào trong phạm vi cần cấu trúc lại.
            </p>
          ) : (
            <ScrollArea className="h-44 rounded-xl border border-border/70 bg-card/40 p-2 shadow-sm">
              <ul className="space-y-2 text-xs">
                {preview.preview.map((item) => (
                  <li key={item.from} className="font-mono leading-relaxed">
                    <span className="text-muted-foreground">{item.from}</span>

                    <br />

                    <span className="text-primary">→ {item.to}</span>
                  </li>
                ))}

                {preview.candidates > preview.preview.length ? (
                  <li className="text-muted-foreground">
                    … và {preview.candidates - preview.preview.length} file khác
                  </li>
                ) : null}
              </ul>
            </ScrollArea>
          )}
        </div>
      ) : null}
    </PanelDialog>
  )
}

"use client"

import Link from "next/link"
import { useCallback, useMemo, useState, type ReactNode } from "react"
import type { ColumnFiltersState, OnChangeFn, RowSelectionState } from "@tanstack/react-table"
import { Button, buttonVariants } from "@ui/components/button"
import { AdminPageLoading } from "@ui/components/admin"
import { ImageLightbox } from "@ui/components/image-lightbox"
import type { DataTableUserSearchHandlers } from "@ui/components/data-table"
import { ExternalLink, Loader2, Upload } from "lucide-react"
import { canUserAccess, PERMISSION_CODES } from "@workspace/api-client"
import { useDebouncedValue } from "@workspace/admin-app/hooks/use-debounced-value"
import { api } from "@workspace/admin-app/lib/api"
import { normalizeAdminFilterValue } from "@workspace/admin-app/lib/build-admin-filter-query"
import { useAdminAuth as useAuth, useAdminModulePath } from "@workspace/admin-app/runtime"
import { cn } from "@ui/lib/utils"
import {
  FileStorageCreateFolderButton,
} from "./file-storage-create-folder-button"
import { FileStorageDeleteFolderButton } from "./file-storage-delete-folder-button"
import { FileStorageFolderNav } from "./file-storage-folder-nav"
import { FileStorageUploadDialog } from "./file-storage-upload-dialog"
import { StorageVideoPreview } from "./storage-video-preview"
import { getFileStorageColumns } from "./columns"
import { FileStorageTable } from "./_table"
import { useFileStorageActions, useFileStorageList } from "./_hooks"
import type { FileStorageRow, StorageRealm } from "./types"
import {
  clampFolderPath,
  normalizeFolderPath,
  scopeFolderBreadcrumb,
} from "./folder-domain"
import {
  isImageStorageRow,
  resolveFolderPathAfterCreate,
  resolveStorageAssetUrl,
} from "./utils"

const UPLOAD_OWNER_FILTER_DEBOUNCE_MS = 400

export type FileStorageScopedBrowseProps = {
  realm?: StorageRealm
  /** Folder gốc trong realm (vd. `avatars` → `images/avatars/{MSSV}`). */
  rootFolderPath?: string
  rootFolderLabel?: string
  description?: ReactNode
  tableScopePrefix?: string
  className?: string
  showUpload?: boolean
  showLinkToFullPage?: boolean
}

export function FileStorageScopedBrowse({
  realm = "images",
  rootFolderPath = "",
  rootFolderLabel,
  description,
  tableScopePrefix = "scoped",
  className,
  showUpload = true,
  showLinkToFullPage = true,
}: FileStorageScopedBrowseProps) {
  const { user } = useAuth()
  const fileStoragePath = useAdminModulePath("file-storage")
  const root = normalizeFolderPath(rootFolderPath)

  const canUpload = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_CREATE) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false
  const canDelete = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_DELETE) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false
  const canView = user
    ? canUserAccess(user, PERMISSION_CODES.UPLOADS_VIEW) ||
      canUserAccess(user, PERMISSION_CODES.UPLOADS_MANAGE)
    : false

  const [activeFolderPath, setActiveFolderPath] = useState(root)
  const [includeDescendants, setIncludeDescendants] = useState(false)
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(20)
  const [selectedRowIds, setSelectedRowIds] = useState<RowSelectionState>({})
  const [lightboxOpen, setLightboxOpen] = useState(false)
  const [lightboxIndex, setLightboxIndex] = useState(0)
  const [videoPreviewRow, setVideoPreviewRow] = useState<FileStorageRow | null>(
    null
  )
  const [folderRefreshKey, setFolderRefreshKey] = useState(0)

  const bumpFolderList = useCallback(() => {
    setFolderRefreshKey((key) => key + 1)
  }, [])

  const uploadOwnerFilter = useMemo(() => {
    const raw = columnFilters.find((f) => f.id === "uploadOwnerId")?.value
    return normalizeAdminFilterValue(raw) ?? ""
  }, [columnFilters])

  const debouncedUploadOwnerFilter = useDebouncedValue(
    uploadOwnerFilter,
    UPLOAD_OWNER_FILTER_DEBOUNCE_MS
  )

  const {
    rows,
    childFolders,
    breadcrumb,
    loading,
    isFetching,
    total,
    reload,
  } = useFileStorageList(
    realm,
    activeFolderPath,
    page,
    pageSize,
    includeDescendants,
    debouncedUploadOwnerFilter
  )

  const scopedBreadcrumb = useMemo(
    () => scopeFolderBreadcrumb(breadcrumb, root),
    [breadcrumb, root]
  )

  const navRealmLabel = root
    ? (rootFolderLabel ?? root.split("/").pop() ?? root)
    : realm === "images"
      ? "Hình ảnh"
      : realm

  const currentFolderLabel =
    scopedBreadcrumb[scopedBreadcrumb.length - 1]?.label ?? navRealmLabel

  const {
    uploadDialogOpen,
    setUploadDialogOpen,
    setUploading,
    uploading,
    deletingPath,
    downloadingPath,
    handleDownload,
    handleDelete,
    handleBulkDelete,
    handleBulkDownload,
    openUploadPicker,
  } = useFileStorageActions({
    activeRealm: realm,
    activeFolderPath,
    includeDescendants,
    uploadOwnerFilter: debouncedUploadOwnerFilter,
    reload,
  })

  const lightboxImages = useMemo(
    () =>
      rows
        .filter((r) => isImageStorageRow(r))
        .map((r) => ({
          key: r.relativePath,
          src: resolveStorageAssetUrl(r),
          altText: r.originalName,
        })),
    [rows]
  )

  const openImagePreview = useCallback(
    (row: FileStorageRow) => {
      const idx = lightboxImages.findIndex((li) => li.key === row.relativePath)
      if (idx >= 0) {
        setLightboxIndex(idx)
        setLightboxOpen(true)
      }
    },
    [lightboxImages]
  )

  const handleFolderNavigate = useCallback(
    (folderPath: string) => {
      setActiveFolderPath(clampFolderPath(folderPath, root))
      setPage(1)
      setSelectedRowIds({})
    },
    [root]
  )

  const handleFolderCreated = useCallback(
    async (folderPath: string) => {
      setActiveFolderPath(
        clampFolderPath(resolveFolderPathAfterCreate(folderPath, realm), root)
      )
      setPage(1)
      setSelectedRowIds({})
      bumpFolderList()
      await reload()
    },
    [bumpFolderList, realm, reload, root]
  )

  const handleFolderDeleted = useCallback(async () => {
    const parentPath =
      scopedBreadcrumb.length >= 2
        ? (scopedBreadcrumb.at(-2)?.id ?? root)
        : root
    setActiveFolderPath(parentPath)
    setPage(1)
    setSelectedRowIds({})
    bumpFolderList()
    await reload()
  }, [bumpFolderList, reload, root, scopedBreadcrumb])

  const handleIncludeDescendantsChange = useCallback((value: boolean) => {
    setIncludeDescendants(value)
    setPage(1)
    setSelectedRowIds({})
  }, [])

  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updater) => {
      setColumnFilters(updater)
    },
    []
  )

  const handleClearFilters = useCallback(() => {
    setColumnFilters([])
    setPage(1)
    setSelectedRowIds({})
  }, [])

  const uploadOwnerSearchHandlers = useMemo<DataTableUserSearchHandlers>(
    () => ({
      onSearch: async (q) => {
        const res = await api.users.list({ q, page: 1, limit: 10 })
        return res.items.map((item) => ({
          id: item.id,
          label: item.fullName?.trim() || item.email,
          sublabel: item.email,
        }))
      },
      onResolveUser: async (id) => {
        const item = await api.users.get(id)
        return {
          id: item.id,
          label: item.fullName?.trim() || item.email,
          sublabel: item.email,
        }
      },
    }),
    []
  )

  const columns = useMemo(
    () =>
      getFileStorageColumns({
        canDelete,
        deletingPath,
        downloadingPath,
        onPreviewImage: openImagePreview,
        onPreviewVideo: (row) => setVideoPreviewRow(row),
        onDownload: handleDownload,
        onDelete: handleDelete,
        uploadOwnerSearchHandlers,
      }),
    [
      canDelete,
      deletingPath,
      downloadingPath,
      handleDelete,
      handleDownload,
      openImagePreview,
      uploadOwnerSearchHandlers,
    ]
  )

  const wrappedBulkDelete = useCallback(
    async (selected: FileStorageRow[]) => {
      await handleBulkDelete(selected)
      setSelectedRowIds({})
    },
    [handleBulkDelete]
  )

  if (!canView) {
    return (
      <p className="rounded-lg border border-amber-500/40 bg-amber-500/10 px-4 py-3 text-sm">
        Bạn không có quyền xem kho lưu trữ (`uploads:view`).
      </p>
    )
  }

  return (
    <div className={className}>
      {(description || showLinkToFullPage) && (
        <div className="mb-3 flex flex-wrap items-start justify-between gap-2 text-sm text-muted-foreground">
          {description ? <div className="min-w-0 flex-1">{description}</div> : null}
          {showLinkToFullPage ? (
            <Link
              href={
                root
                  ? `${fileStoragePath()}?realm=${realm}&folder=${encodeURIComponent(root)}`
                  : fileStoragePath()
              }
              className={cn(buttonVariants({ variant: "outline", size: "sm" }), "h-8 shrink-0 gap-1.5")}
            >
              <ExternalLink className="size-3.5" />
              Mở kho đầy đủ
            </Link>
          ) : null}
        </div>
      )}

      {loading && rows.length === 0 ? (
        <AdminPageLoading variant="list" />
      ) : (
        <div className="space-y-4">
          <FileStorageFolderNav
            realm={realm}
            realmLabel={navRealmLabel}
            breadcrumb={scopedBreadcrumb}
            childFolders={childFolders}
            activeFolderPath={activeFolderPath}
            includeDescendants={includeDescendants}
            onIncludeDescendantsChange={handleIncludeDescendantsChange}
            onNavigate={handleFolderNavigate}
            foldersRefreshKey={folderRefreshKey}
            homeFolderPath={root || undefined}
            actions={
              <>
                {showUpload && canUpload ? (
                  <Button
                    type="button"
                    size="sm"
                    className="h-8 gap-1.5"
                    onClick={openUploadPicker}
                    disabled={uploading}
                  >
                    {uploading ? (
                      <Loader2 className="size-3.5 animate-spin" />
                    ) : (
                      <Upload className="size-3.5" />
                    )}
                    Tải lên
                  </Button>
                ) : null}
                {canUpload ? (
                  <FileStorageCreateFolderButton
                    realm={realm}
                    parentFolderPath={activeFolderPath}
                    parentLabel={currentFolderLabel}
                    onCreated={handleFolderCreated}
                    disabled={uploading}
                  />
                ) : null}
                {canDelete && activeFolderPath && activeFolderPath !== root ? (
                  <FileStorageDeleteFolderButton
                    realm={realm}
                    folderPath={activeFolderPath}
                    folderLabel={currentFolderLabel}
                    onDeleted={handleFolderDeleted}
                    disabled={uploading}
                  />
                ) : null}
              </>
            }
          />

          <FileStorageTable
            tableScope={`${tableScopePrefix}-${realm}-${activeFolderPath || "root"}`}
            emptyLabel={`Chưa có file trong «${currentFolderLabel}».`}
            emptySummary={`Không có file trong ${currentFolderLabel}`}
            tabLabel={currentFolderLabel}
            data={rows}
            columns={columns}
            isLoading={loading}
            isFetching={isFetching}
            itemLabel="file"
            page={page}
            pageSize={pageSize}
            total={total}
            onPageChange={setPage}
            onPageSizeChange={setPageSize}
            selectedRowIds={selectedRowIds}
            onSelectedRowIdsChange={setSelectedRowIds}
            onBulkDelete={canDelete ? wrappedBulkDelete : async () => {}}
            onBulkDownload={handleBulkDownload}
            columnFilters={columnFilters}
            onColumnFiltersChange={handleColumnFiltersChange}
            onClearFilters={handleClearFilters}
            includeDescendants={includeDescendants}
            canDelete={canDelete}
            canUpload={showUpload && canUpload}
            uploading={uploading}
            onUpload={openUploadPicker}
          />
        </div>
      )}

      <ImageLightbox
        open={lightboxOpen}
        images={lightboxImages}
        index={lightboxIndex}
        onIndexChange={setLightboxIndex}
        onClose={() => setLightboxOpen(false)}
      />

      <StorageVideoPreview
        row={videoPreviewRow}
        open={videoPreviewRow != null}
        onClose={() => setVideoPreviewRow(null)}
      />

      {showUpload && canUpload ? (
        <FileStorageUploadDialog
          open={uploadDialogOpen}
          onOpenChange={setUploadDialogOpen}
          activeRealm={realm}
          activeFolderPath={activeFolderPath}
          activeTabLabel={currentFolderLabel}
          uploadAccept="image/*"
          onUploaded={reload}
          onUploadingChange={setUploading}
        />
      ) : null}
    </div>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { Button } from "@ui/components/button"
import {
  PanelDialog,
  PanelDialogDestination,
  PanelDialogLoading,
  PanelDialogSearch,
  PanelDialogTreePanel,
} from "@ui/components/dialogs"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import { toast } from "@ui/components/sonner"
import { Tabs, TabsContent } from "@ui/components/tabs"
import { AdminListTabsList, AdminListTabsTrigger } from "@ui/components/admin"
import {
  createStorageFolder,
  fetchStorageFolders,
  type FolderItem,
} from "@workspace/admin-app/lib/admin-uploads"
import { uploadAdminImage } from "@workspace/admin-app/lib/admin-upload"
import { FolderOpen, FolderPlus, Loader2, Upload } from "lucide-react"
import { FileStorageAllowedExtensionsPicker } from "./file-storage-allowed-extensions-picker"
import {
  FileStorageFolderTree,
  STORAGE_ROOT_AUDIO,
  STORAGE_ROOT_FILES,
  STORAGE_ROOT_IMAGES,
  STORAGE_ROOT_VIDEOS,
} from "./file-storage-folder-tree"
import {
  buildAcceptAttribute,
  extensionsFromGroupIds,
  findInheritedFolderExtensions,
  formatExtensionsSummary,
  getRealmDefaultExtensions,
  getRealmDefaultGroupIds,
  type StorageExtensionGroupId,
} from "./storage-upload-policy"
import type { StorageRealm } from "./types"
import {
  buildRealmVirtualRoots,
  inferFolderResourceType,
  resolveDefaultFolderPath,
} from "./utils"

function isVirtualStorageRoot(parentPath: string): boolean {
  return (
    parentPath === STORAGE_ROOT_IMAGES ||
    parentPath === STORAGE_ROOT_FILES ||
    parentPath === STORAGE_ROOT_VIDEOS ||
    parentPath === STORAGE_ROOT_AUDIO
  )
}

function realmFromVirtualRoot(parentPath: string): StorageRealm {
  if (parentPath === STORAGE_ROOT_FILES) return "files"
  if (parentPath === STORAGE_ROOT_VIDEOS) return "videos"
  if (parentPath === STORAGE_ROOT_AUDIO) return "audio"
  return "images"
}

type FileStorageUploadDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  activeRealm: StorageRealm
  activeFolderPath: string
  activeTabLabel?: string
  uploadAccept: string
  onUploaded: () => Promise<void>
  onUploadingChange?: (uploading: boolean) => void
}

export function FileStorageUploadDialog({
  open,
  onOpenChange,
  activeRealm,
  activeFolderPath,
  activeTabLabel,
  uploadAccept,
  onUploaded,
  onUploadingChange,
}: FileStorageUploadDialogProps) {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [folders, setFolders] = useState<FolderItem[]>([])
  const [loadingFolders, setLoadingFolders] = useState(false)
  const [folderMode, setFolderMode] = useState<"existing" | "new">("existing")
  const [selectedPath, setSelectedPath] = useState("")
  const [folderFilter, setFolderFilter] = useState("")
  const [newFolderName, setNewFolderName] = useState("")
  const [newParentPath, setNewParentPath] = useState(STORAGE_ROOT_IMAGES)
  const [newFolderExtensionGroups, setNewFolderExtensionGroups] = useState<
    StorageExtensionGroupId[]
  >(() => getRealmDefaultGroupIds(activeRealm))
  const [uploading, setUploading] = useState(false)

  const realmVirtualRoots = useMemo(
    () => buildRealmVirtualRoots(activeRealm),
    [activeRealm]
  )

  const loadFolders = useCallback(async () => {
    setLoadingFolders(true)
    try {
      const list = await fetchStorageFolders()
      setFolders(list)
      const defaultPath = resolveDefaultFolderPath(
        list,
        activeRealm,
        activeFolderPath
      )
      setSelectedPath(defaultPath)
      const defaultParent =
        activeRealm === "files"
          ? STORAGE_ROOT_FILES
          : activeRealm === "videos"
            ? STORAGE_ROOT_VIDEOS
            : activeRealm === "audio"
              ? STORAGE_ROOT_AUDIO
              : defaultPath || STORAGE_ROOT_IMAGES
      setNewParentPath(
        defaultParent === "files"
          ? STORAGE_ROOT_FILES
          : defaultParent === "videos"
            ? STORAGE_ROOT_VIDEOS
            : defaultParent === "audio"
              ? STORAGE_ROOT_AUDIO
              : defaultParent || STORAGE_ROOT_IMAGES
      )
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Không tải được danh sách thư mục"
      )
    } finally {
      setLoadingFolders(false)
    }
  }, [activeFolderPath, activeRealm])

  useEffect(() => {
    if (!open) return
    setFolderMode("existing")
    setNewFolderName("")
    setFolderFilter("")
    setNewFolderExtensionGroups(getRealmDefaultGroupIds(activeRealm))
    void loadFolders()
  }, [activeRealm, open, loadFolders])

  const effectiveAccept = useMemo(() => {
    if (folderMode === "existing" && selectedPath.trim()) {
      const inherited = findInheritedFolderExtensions(folders, selectedPath)
      if (inherited?.length) return buildAcceptAttribute(inherited)
      return buildAcceptAttribute(
        getRealmDefaultExtensions(inferFolderResourceType(selectedPath))
      )
    }
    if (folderMode === "new") {
      if (isVirtualStorageRoot(newParentPath)) {
        const realm = realmFromVirtualRoot(newParentPath)
        return buildAcceptAttribute(
          extensionsFromGroupIds(realm, newFolderExtensionGroups)
        )
      }
      const inherited = findInheritedFolderExtensions(folders, newParentPath)
      if (inherited?.length) return buildAcceptAttribute(inherited)
      return buildAcceptAttribute(
        getRealmDefaultExtensions(inferFolderResourceType(newParentPath))
      )
    }
    return uploadAccept
  }, [
    folderMode,
    folders,
    newFolderExtensionGroups,
    newParentPath,
    selectedPath,
    uploadAccept,
  ])

  const allowedTypesHint = useMemo(() => {
    const exts = effectiveAccept
      .split(",")
      .map((part) => part.trim())
      .filter((part) => part.startsWith("."))
    return formatExtensionsSummary(
      exts.length ? exts : getRealmDefaultExtensions(activeRealm)
    )
  }, [activeRealm, effectiveAccept])

  const destinationPreview = useMemo(() => {
    if (folderMode === "existing") {
      return selectedPath || "(chưa chọn thư mục)"
    }
    const name = newFolderName.trim()
    if (!name) return "(nhập tên thư mục mới)"
    if (newParentPath === STORAGE_ROOT_IMAGES) return name
    if (newParentPath === STORAGE_ROOT_FILES) return `files/${name}`
    if (newParentPath === STORAGE_ROOT_VIDEOS) return `videos/${name}`
    if (newParentPath === STORAGE_ROOT_AUDIO) return `audio/${name}`
    return `${newParentPath.replace(/\/$/, "")}/${name}`
  }, [folderMode, newFolderName, newParentPath, selectedPath])

  const destinationReady = useMemo(() => {
    if (folderMode === "existing") return Boolean(selectedPath.trim())
    return Boolean(newFolderName.trim())
  }, [folderMode, newFolderName, selectedPath])

  const resolveUploadFolder = useCallback(async (): Promise<{
    folderPath: string
    isExistingFolder: boolean
  }> => {
    if (folderMode === "existing") {
      if (!selectedPath.trim()) {
        throw new Error("Vui lòng chọn thư mục đích")
      }
      return { folderPath: selectedPath.trim(), isExistingFolder: true }
    }

    const name = newFolderName.trim()
    if (!name) {
      throw new Error("Vui lòng nhập tên thư mục mới")
    }

    let parentPath: string | undefined
    let resourceType: "images" | "files" | "videos" | "audio" = "images"
    if (newParentPath === STORAGE_ROOT_FILES) {
      resourceType = "files"
      parentPath = undefined
    } else if (newParentPath === STORAGE_ROOT_VIDEOS) {
      resourceType = "videos"
      parentPath = undefined
    } else if (newParentPath === STORAGE_ROOT_AUDIO) {
      resourceType = "audio"
      parentPath = undefined
    } else if (newParentPath === STORAGE_ROOT_IMAGES) {
      resourceType = "images"
      parentPath = undefined
    } else {
      parentPath = newParentPath
      resourceType = inferFolderResourceType(newParentPath)
    }

    const created = await createStorageFolder({
      folderName: name,
      parentPath,
      resourceType,
      allowedExtensions: isVirtualStorageRoot(newParentPath)
        ? extensionsFromGroupIds(resourceType, newFolderExtensionGroups)
        : undefined,
    })
    return {
      folderPath: created.folderPath,
      isExistingFolder: true,
    }
  }, [
    folderMode,
    newFolderExtensionGroups,
    newFolderName,
    newParentPath,
    selectedPath,
  ])

  const runUpload = useCallback(
    async (files: File[]) => {
      if (!files.length) return
      setUploading(true)
      onUploadingChange?.(true)
      const pending = toast.loading(`Đang tải lên ${files.length} file…`)
      try {
        const { folderPath, isExistingFolder } = await resolveUploadFolder()
        let success = 0
        let fail = 0
        for (const file of files) {
          try {
            await uploadAdminImage(file, { folderPath, isExistingFolder })
            success++
          } catch {
            fail++
          }
        }
        if (success > 0) {
          toast.success(`Đã lưu ${success} file vào «${folderPath}»`, {
            id: pending,
          })
        }
        if (fail > 0) {
          toast.error(`${fail} file tải lên thất bại`, { id: pending })
        }
        await onUploaded()
        onOpenChange(false)
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Lỗi tải lên", {
          id: pending,
        })
      } finally {
        setUploading(false)
        onUploadingChange?.(false)
        if (fileInputRef.current) fileInputRef.current.value = ""
      }
    },
    [onOpenChange, onUploaded, onUploadingChange, resolveUploadFolder]
  )

  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = Array.from(e.target.files ?? [])
      void runUpload(files)
    },
    [runUpload]
  )

  return (
    <PanelDialog
      open={open}
      onOpenChange={onOpenChange}
      size="lg"
      icon={<Upload />}
      title="Tải file lên kho"
      description={
        <>
          Chọn thư mục có sẵn hoặc tạo thư mục mới trước khi lưu file
          {activeTabLabel ? ` (tab «${activeTabLabel}»)` : ""}. Định dạng cho
          phép: {allowedTypesHint}.
        </>
      }
      footerLeading={
        <PanelDialogDestination
          label="Đích lưu"
          value={destinationPreview}
          ready={destinationReady}
        />
      }
      footer={
        <>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept={effectiveAccept}
            className="hidden"
            onChange={(e) => void handleFileChange(e)}
          />
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={uploading}
          >
            Hủy
          </Button>
          <Button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading || loadingFolders || !destinationReady}
          >
            {uploading ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <Upload className="size-4" />
            )}
            {uploading ? "Đang tải lên…" : "Chọn file và tải lên"}
          </Button>
        </>
      }
    >
      <Tabs
        value={folderMode}
        onValueChange={(v) => setFolderMode(v === "new" ? "new" : "existing")}
      >
        <AdminListTabsList fullWidth className="grid grid-cols-2">
          <AdminListTabsTrigger value="existing" stretch>
            <FolderOpen className="size-3.5" />
            Thư mục có sẵn
          </AdminListTabsTrigger>
          <AdminListTabsTrigger value="new" stretch>
            <FolderPlus className="size-3.5" />
            Tạo mới
          </AdminListTabsTrigger>
        </AdminListTabsList>

        <TabsContent value="existing" className="mt-4 space-y-3">
          <PanelDialogSearch
            id="folder-search"
            label="Tìm trong cây thư mục"
            value={folderFilter}
            onChange={setFolderFilter}
            placeholder="avatars, admincp, 2026…"
            disabled={loadingFolders || uploading}
          />

          {loadingFolders ? (
            <PanelDialogLoading label="Đang tải cây thư mục…" />
          ) : (
            <PanelDialogTreePanel>
              <FileStorageFolderTree
                folders={folders}
                filter={folderFilter}
                selectedPath={selectedPath}
                onSelect={setSelectedPath}
                disabled={uploading}
                realm={activeRealm}
                virtualRoots={realmVirtualRoots}
                autoExpandRoots
              />
            </PanelDialogTreePanel>
          )}
        </TabsContent>

        <TabsContent value="new" className="mt-4 space-y-4">
          <div className="space-y-2">
            <Label>Thư mục cha (cây thư mục)</Label>
            <PanelDialogSearch
              id="new-folder-parent-search"
              value={folderFilter}
              onChange={setFolderFilter}
              placeholder="Lọc cây thư mục cha…"
              disabled={loadingFolders || uploading}
            />
            <PanelDialogTreePanel heightClassName="h-44">
              <FileStorageFolderTree
                folders={folders}
                filter={folderFilter}
                selectedPath={newParentPath}
                onSelect={setNewParentPath}
                disabled={uploading || loadingFolders}
                showVirtualRoots
              />
            </PanelDialogTreePanel>
          </div>
          <div className="space-y-2">
            <Label htmlFor="new-folder-name">Tên thư mục mới</Label>
            <Input
              id="new-folder-name"
              value={newFolderName}
              onChange={(e) => setNewFolderName(e.target.value)}
              placeholder="vd. buh_slidehome, 2026/06"
              disabled={uploading}
            />
            <p className="text-xs text-muted-foreground">
              Ký tự đặc biệt sẽ được chuyển thành dấu gạch dưới trên server.
            </p>
          </div>
          {isVirtualStorageRoot(newParentPath) ? (
            <FileStorageAllowedExtensionsPicker
              realm={realmFromVirtualRoot(newParentPath)}
              value={newFolderExtensionGroups}
              onChange={setNewFolderExtensionGroups}
              disabled={uploading}
            />
          ) : null}
        </TabsContent>
      </Tabs>
    </PanelDialog>
  )
}

