"use client"

import { useEffect } from "react"
import { useRouter } from "next/navigation"
import { useAdminModulePath } from "@workspace/admin-app/runtime"

/** Giữ URL cũ `/hanet-avatars` → tab Avatar trên trang HANET. */
export default function HanetAvatarsRedirectPage() {
  const router = useRouter()
  const hanetPath = useAdminModulePath("hanet")

  useEffect(() => {
    router.replace(`${hanetPath()}/avatar`)
  }, [router, hanetPath])

  return null
}

src/modules/hanet/ket-noi/page.tsx.content:
"use client"

import { useState } from "react"
import {
  CheckCircle2,
  Globe,
  KeyRound,
  Loader2,
  MapPin,
  PlugZap,
  UserCircle2,
  XCircle,
} from "lucide-react"
import { useQuery } from "@tanstack/react-query"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  FieldSectionDivider,
  FieldSectionField,
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { cn } from "@ui/lib/utils"
import { api } from "@workspace/admin-app/lib/api"
import { HANET_PAGE_ENDPOINTS } from "@workspace/admin-app/lib/hanet-postman"
import { useHanetStatusQuery } from "@workspace/admin-app/modules/events/_component/_query"
import { HanetJsonPreview } from "../_component/hanet-json-preview"
import { HanetModuleShell } from "../_component/hanet-module-shell"

function StatusPill({
  ok,
  label,
}: {
  ok: boolean
  label: string
}) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px]",
        ok
          ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-800 dark:text-emerald-200"
          : "border-border bg-muted/40 text-muted-foreground"
      )}
    >
      {ok ? (
        <CheckCircle2 className="size-3 shrink-0" aria-hidden />
      ) : (
        <XCircle className="size-3 shrink-0 opacity-60" aria-hidden />
      )}
      {label}
    </span>
  )
}

function ProfilePanel({ data }: { data: unknown }) {
  const record =
    data && typeof data === "object" && !Array.isArray(data)
      ? (data as Record<string, unknown>)
      : null

  const email =
    typeof record?.email === "string" ? record.email.trim() : ""
  const name = typeof record?.name === "string" ? record.name.trim() : ""
  const id =
    record?.id != null && String(record.id).trim()
      ? String(record.id)
      : ""

  if (!email && !name && !id) {
    return <HanetJsonPreview data={data} />
  }

  return (
    <div className="flex gap-3">
      <div className="flex size-10 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary">
        <UserCircle2 className="size-5" aria-hidden />
      </div>
      <dl className="min-w-0 flex-1 space-y-0.5 text-sm">
        <dt className="sr-only">Tên</dt>
        <dd className="font-medium leading-tight">
          {name || (email || "Partner account")}
        </dd>
        {email && name ? (
          <>
            <dt className="sr-only">Email</dt>
            <dd className="truncate text-xs text-muted-foreground">{email}</dd>
          </>
        ) : null}
        {id ? (
          <>
            <dt className="sr-only">ID</dt>
            <dd>
              <code className="text-[10px] text-muted-foreground">id: {id}</code>
            </dd>
          </>
        ) : null}
      </dl>
    </div>
  )
}

function KetNoiContent() {
  const { data: hanetStatus, isLoading: statusLoading } = useHanetStatusQuery()
  const [profileEnabled, setProfileEnabled] = useState(false)

  const profileQuery = useQuery({
    queryKey: ["hanet", "profile"],
    queryFn: () => api.hanet.getProfile(),
    enabled: profileEnabled && hanetStatus?.configured === true,
  })

  const oauthMutation = useAdminMutation({
    mutationKey: ["hanet", "test-connection"],
    mutationFn: () => api.hanet.testConnection(),
    toast: {
      loading: "Đang kiểm tra OAuth…",
      success: (res) => res.message,
      error: (err) =>
        err instanceof Error ? err.message : "OAuth HANET thất bại",
    },
  })

  if (statusLoading) {
    return (
      <div className="flex items-center justify-center gap-2 py-12 text-sm text-muted-foreground">
        <Loader2 className="size-4 animate-spin" />
        Đang tải…
      </div>
    )
  }

  const configured = hanetStatus?.configured === true

  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <FieldSet variant="section">
        <FieldSectionLegend
          icon={PlugZap}
          title="OAuth & .env API"
          description="Client ID, token và partner base URL."
          badge={
            configured ? (
              <Badge className="h-5 text-[10px]">Sẵn sàng</Badge>
            ) : (
              <Badge variant="outline" className="h-5 text-[10px]">
                Chưa cấu hình
              </Badge>
            )
          }
        />
        <FieldSetContent variant="section" className="space-y-4 pt-0">
          {configured && hanetStatus ? (
            <>
              <div className="flex flex-wrap gap-1.5">
                <StatusPill ok={configured} label="OAuth" />
                <StatusPill
                  ok={hanetStatus.hasAccessToken}
                  label="Access token"
                />
                <StatusPill
                  ok={hanetStatus.hasRefreshToken}
                  label="Refresh token"
                />
              </div>

              <div className="space-y-3">
                <FieldSectionField
                  label="API base"
                  icon={Globe}
                  copyable
                  copyText={hanetStatus.apiBaseUrl}
                >
                  <code className="font-mono text-xs break-all">
                    {hanetStatus.apiBaseUrl}
                  </code>
                </FieldSectionField>
                {hanetStatus.clientId ? (
                  <FieldSectionField
                    label="Client ID"
                    icon={KeyRound}
                    copyable
                    copyText={hanetStatus.clientId}
                  >
                    <code className="font-mono text-xs break-all">
                      {hanetStatus.clientId}
                    </code>
                  </FieldSectionField>
                ) : null}
                {hanetStatus.defaultPlaceId ? (
                  <FieldSectionField
                    label="Place mặc định"
                    icon={MapPin}
                    copyable
                    copyText={hanetStatus.defaultPlaceId}
                  >
                    <code className="font-mono text-xs break-all">
                      {hanetStatus.defaultPlaceId}
                    </code>
                  </FieldSectionField>
                ) : null}
              </div>
            </>
          ) : (
            <p className="text-xs leading-relaxed text-amber-800 dark:text-amber-200">
              Đặt <code className="text-[10px]">HANET_CLIENT_ID</code>,{" "}
              <code className="text-[10px]">HANET_CLIENT_SECRET</code>,{" "}
              <code className="text-[10px]">HANET_REFRESH_TOKEN</code> trong{" "}
              <code className="text-[10px]">.env</code> API.
            </p>
          )}

          <FieldSectionDivider />

          <div className="flex flex-wrap items-center gap-2 pt-1">
            <Button
              type="button"
              variant="default"
              size="sm"
              className="h-8 gap-1.5"
              disabled={!configured || oauthMutation.isPending}
              onClick={() => oauthMutation.mutate()}
            >
              {oauthMutation.isPending ? (
                <Loader2 className="size-3.5 shrink-0 animate-spin" />
              ) : (
                <PlugZap className="size-3.5 shrink-0" />
              )}
              <span className="leading-none">Test OAuth</span>
            </Button>
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="h-8 gap-1.5"
              disabled={!configured || profileQuery.isFetching}
              onClick={() => setProfileEnabled(true)}
            >
              {profileQuery.isFetching ? (
                <Loader2 className="size-3.5 shrink-0 animate-spin" />
              ) : (
                <UserCircle2 className="size-3.5 shrink-0" />
              )}
              <span className="leading-none">getProfile</span>
            </Button>
          </div>
        </FieldSetContent>
      </FieldSet>

      <FieldSet variant="section">
        <FieldSectionLegend
          icon={UserCircle2}
          title="Partner profile"
          description="Kết quả /profile/getProfile"
        />
        <FieldSetContent variant="section" className="pt-0">
          {profileQuery.isFetching ? (
            <div className="flex min-h-[8rem] items-center justify-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="size-4 animate-spin" />
              Đang gọi API…
            </div>
          ) : profileQuery.data ? (
            <FieldSectionField
              label="Tài khoản partner"
              icon={Globe}
              copyable
              copyText={
                typeof (profileQuery.data as { email?: string })?.email ===
                "string"
                  ? (profileQuery.data as { email: string }).email
                  : undefined
              }
            >
              <ProfilePanel data={profileQuery.data} />
            </FieldSectionField>
          ) : profileQuery.error ? (
            <p className="text-sm text-destructive">{profileQuery.error.message}</p>
          ) : (
            <FieldSectionField label="Chưa tải" icon={KeyRound}>
              <p className="text-xs text-muted-foreground">
                Bấm <strong className="font-medium">getProfile</strong> ở cột
                trái để kiểm tra tài khoản partner.
              </p>
            </FieldSectionField>
          )}
        </FieldSetContent>
      </FieldSet>
    </div>
  )
}

export default function HanetKetNoiPage() {
  return (
    <HanetModuleShell
      icon={PlugZap}
      title="Kết nối HANET"
      subtitle="Kiểm tra OAuth và profile partner."
      endpoints={HANET_PAGE_ENDPOINTS.ketNoi}
    >
      <KetNoiContent />
    </HanetModuleShell>
  )
}

src/modules/hanet/nguoi/page.tsx.content:
"use client"

import { useState } from "react"
import { List, Search, Trash2, UserPlus, Users } from "lucide-react"
import { useQuery, useQueryClient } from "@tanstack/react-query"
import { Button } from "@ui/components/button"
import {
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { Tabs, TabsContent } from "@ui/components/tabs"
import { AdminListTabsList, AdminListTabsTrigger } from "@ui/components/admin"
import { api } from "@workspace/admin-app/lib/api"
import type { HanetPersonActionId } from "@workspace/admin-app/lib/hanet-person-api-actions"
import { readHanetAdminPlaceId } from "@workspace/admin-app/lib/hanet-place-storage"
import { HANET_PAGE_ENDPOINTS } from "@workspace/admin-app/lib/hanet-postman"
import { HanetPlaceSelect } from "@workspace/admin-app/modules/hanet/_component/hanet-place-select"
import { useHanetStatusQuery } from "@workspace/admin-app/modules/events/_component/_query"
import { HanetModuleShell } from "../_component/hanet-module-shell"
import { HanetPersonActionDialog } from "../_component/hanet-person-action-dialog"
import { HanetPersonLookupPanel } from "../_component/hanet-person-lookup-panel"
import { HanetPersonsTable } from "../_component/hanet-persons-table"
import type { HanetPersonRow } from "../_component/hanet-persons-table"
import { HanetRegisterFaceDialog } from "../_component/hanet-register-face-dialog"

const DEFAULT_PAGE_SIZE = 50

function NguoiContent() {
  const queryClient = useQueryClient()
  const { data: hanetStatus } = useHanetStatusQuery()
  const [selectedPlaceId, setSelectedPlaceId] = useState(readHanetAdminPlaceId)
  const [pageIndex, setPageIndex] = useState(0)
  const [pageSize, setPageSize] = useState(DEFAULT_PAGE_SIZE)
  const [registerByUrlOpen, setRegisterByUrlOpen] = useState(false)
  const [personActionId, setPersonActionId] =
    useState<HanetPersonActionId | null>(null)
  const [personActionRow, setPersonActionRow] = useState<HanetPersonRow | null>(
    null,
  )

  const effectivePlaceId =
    selectedPlaceId || hanetStatus?.defaultPlaceId || ""

  const personsQuery = useQuery({
    queryKey: ["hanet", "persons", effectivePlaceId, pageIndex, pageSize],
    queryFn: () =>
      api.hanet.listPersons({
        placeId: effectivePlaceId || undefined,
        pageIndex,
        pageSize,
      }),
    enabled: hanetStatus?.configured === true && Boolean(effectivePlaceId),
  })

  const invalidatePersons = () => {
    void queryClient.invalidateQueries({ queryKey: ["hanet", "persons"] })
  }

  const openPersonAction = (
    actionId: HanetPersonActionId,
    person: HanetPersonRow | null = null,
  ) => {
    setPersonActionId(actionId)
    setPersonActionRow(person)
  }

  const closePersonAction = () => {
    setPersonActionId(null)
    setPersonActionRow(null)
  }

  if (!hanetStatus?.configured) {
    return (
      <FieldSet variant="section">
        <FieldSectionLegend
          title="Chưa cấu hình OAuth"
          description="Thiết lập client ID, secret và token trong .env API trước khi gọi person/getListByPlace."
        />
        <FieldSetContent>
          <p className="rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-2.5 text-sm text-amber-950 dark:text-amber-100">
            Cấu hình OAuth trong .env API, sau đó kiểm tra tại trang{" "}
            <strong>Kết nối</strong>.
          </p>
        </FieldSetContent>
      </FieldSet>
    )
  }

  const items = personsQuery.data?.items ?? []

  return (
    <div className="space-y-4">
      <Tabs defaultValue="list" className="space-y-3">
        <AdminListTabsList fullWidth className="max-w-md grid grid-cols-2">
          <AdminListTabsTrigger value="list" stretch>
            <List className="size-3.5 shrink-0" />
            Danh sách
          </AdminListTabsTrigger>
          <AdminListTabsTrigger value="lookup" stretch>
            <Search className="size-3.5 shrink-0" />
            Tra cứu
          </AdminListTabsTrigger>
        </AdminListTabsList>

        <TabsContent value="list" className="mt-0 space-y-3">
          <div className="flex flex-wrap items-center gap-2 rounded-lg border border-border/70 bg-muted/20 px-4 py-3">
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="h-8 gap-1.5"
              disabled={!effectivePlaceId}
              onClick={() => openPersonAction("register")}
            >
              <UserPlus className="size-3.5" />
              register
            </Button>
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="h-8 gap-1.5"
              disabled={!effectivePlaceId}
              onClick={() => setRegisterByUrlOpen(true)}
            >
              <UserPlus className="size-3.5" />
              registerByUrl
            </Button>
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="h-8 gap-1.5"
              disabled={!effectivePlaceId}
              onClick={() => openPersonAction("remove-by-alias-ids")}
            >
              <Trash2 className="size-3.5" />
              Xóa theo aliasIDs
            </Button>
            <Button
              type="button"
              size="sm"
              variant="destructive"
              className="h-8 gap-1.5"
              disabled={!effectivePlaceId}
              onClick={() => openPersonAction("remove-all-in-place")}
            >
              <Trash2 className="size-3.5" />
              Xóa toàn bộ place
            </Button>
          </div>

          <HanetPersonsTable
            data={items}
            isLoading={personsQuery.isLoading}
            emptyLabel={
              effectivePlaceId
                ? "Không có person cho địa điểm này."
                : "Chọn địa điểm HANET để tải danh sách người."
            }
            pageIndex={pageIndex}
            pageSize={pageSize}
            total={personsQuery.data?.total}
            hanetTotal={personsQuery.data?.hanetTotal}
            listLimited={personsQuery.data?.listLimited}
            onPageIndexChange={setPageIndex}
            onPageSizeChange={(size) => {
              setPageSize(size)
              setPageIndex(0)
            }}
            onPersonAction={(actionId, person) =>
              openPersonAction(actionId, person)
            }
            filterToolbarExtra={
              <HanetPlaceSelect
                layout="stacked"
                value={selectedPlaceId}
                onChange={(id) => {
                  setSelectedPlaceId(id)
                  setPageIndex(0)
                }}
                defaultPlaceId={hanetStatus.defaultPlaceId}
              />
            }
          />
        </TabsContent>

        <TabsContent value="lookup" className="mt-0">
          <HanetPersonLookupPanel
            placeId={effectivePlaceId}
            selectedPlaceId={selectedPlaceId}
            onPlaceChange={setSelectedPlaceId}
            defaultPlaceId={hanetStatus.defaultPlaceId}
          />
        </TabsContent>
      </Tabs>

      <HanetPersonActionDialog
        open={personActionId != null}
        actionId={personActionId}
        placeId={effectivePlaceId}
        person={personActionRow}
        onClose={closePersonAction}
        onSuccess={invalidatePersons}
      />

      <HanetRegisterFaceDialog
        open={registerByUrlOpen}
        placeId={effectivePlaceId}
        onClose={() => setRegisterByUrlOpen(false)}
        onSuccess={invalidatePersons}
      />
    </div>
  )
}

export default function HanetNguoiPage() {
  return (
    <HanetModuleShell
      icon={Users}
      title="Người đăng ký"
      subtitle="getListByPlace · đủ 16 Person API Partner (đăng ký, tra cứu, cập nhật, xóa)."
      endpoints={HANET_PAGE_ENDPOINTS.nguoi}
      contentClassName="max-w-full"
    >
      <NguoiContent />
    </HanetModuleShell>
  )
}

