"use client"

import { useCallback, useState } from "react"
import type { LucideIcon } from "lucide-react"
import {
  Check,
  Clock3,
  Copy,
  ExternalLink,
  Fingerprint,
  GraduationCap,
  Hash,
  Mail,
  ScanFace,
  UserRound,
} from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { Card, CardContent, CardFooter } from "@ui/components/card"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@ui/components/tooltip"
import type { HanetStoredAvatarRow } from "@workspace/api-client"
import { cn } from "@ui/lib/utils"
import {
  formatHanetAvatarDate,
  hanetAliasFieldLabel,
  hanetAvatarInitials,
  hanetAvatarLabel,
  hanetAvatarSrc,
  truncateMiddleId,
} from "./hanet-avatar-utils"

function CopyIconButton({
  value,
  label,
}: {
  value: string
  label: string
}) {
  const [copied, setCopied] = useState(false)

  const onCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1400)
    } catch {
      // ignore
    }
  }, [value])

  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-7 shrink-0 text-muted-foreground hover:text-foreground"
            aria-label={`Sao chép ${label}`}
            onClick={() => void onCopy()}
          />
        }
      >
        {copied ? (
          <Check className="size-3.5 text-success" aria-hidden />
        ) : (
          <Copy className="size-3.5" aria-hidden />
        )}
      </TooltipTrigger>
      <TooltipContent>{copied ? "Đã sao chép" : `Sao chép ${label}`}</TooltipContent>
    </Tooltip>
  )
}

function InfoLine({
  icon: Icon,
  label,
  value,
  displayValue,
  copyLabel,
}: {
  icon: LucideIcon
  label: string
  value: string
  displayValue?: string
  copyLabel: string
}) {
  const shown = displayValue ?? value

  return (
    <div className="flex min-w-0 items-center gap-2 py-2 first:pt-0 last:pb-0">
      <div className="flex size-7 shrink-0 items-center justify-center rounded-md bg-muted/80 text-muted-foreground">
        <Icon className="size-3.5" aria-hidden />
      </div>
      <div className="min-w-0 flex-1">
        <p className="truncate text-[11px] leading-none text-muted-foreground">{label}</p>
        <p
          className="mt-0.5 truncate font-mono text-xs font-medium text-foreground"
          title={value}
        >
          {shown}
        </p>
      </div>
      <CopyIconButton value={value} label={copyLabel} />
    </div>
  )
}

function HanetAvatarInlineCard({
  row,
  label,
  src,
  alias,
  personId,
  aliasLabel,
}: {
  row: HanetStoredAvatarRow
  label: string
  src: string
  alias: string
  personId: string
  aliasLabel: string
}) {
  return (
    <div className="flex min-w-0 items-stretch gap-2.5 overflow-hidden rounded-lg border border-border/70 bg-card p-2 shadow-sm transition-colors hover:border-primary/30">
      <div className="relative h-[4.5rem] w-14 shrink-0 overflow-hidden rounded-md bg-muted">
        {src ? (
          <img
            src={src}
            alt={label}
            className="size-full object-cover object-top"
            loading="lazy"
          />
        ) : (
          <div className="flex size-full items-center justify-center bg-muted text-xs font-semibold text-muted-foreground">
            {hanetAvatarInitials(label)}
          </div>
        )}
        {row.userId ? (
          <span className="absolute top-0.5 right-0.5 size-2 rounded-full bg-success ring-2 ring-card" title={`User #${row.userId}`} />
        ) : null}
      </div>

      <div className="min-w-0 flex-1 space-y-0.5 py-0.5">
        <p className="truncate text-sm font-semibold leading-tight text-foreground" title={label}>
          {label}
        </p>
        {alias ? (
          <p className="truncate text-xs text-muted-foreground" title={alias}>
            <span className="font-medium text-foreground/80">{aliasLabel}:</span> {alias}
          </p>
        ) : null}
        {personId ? (
          <p className="truncate font-mono text-[10px] text-muted-foreground" title={personId}>
            HANET {truncateMiddleId(personId, 8, 4)}
          </p>
        ) : null}
      </div>

      {src ? (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          nativeButton={false}
          className="size-8 shrink-0 self-center"
          render={
            <a href={src} target="_blank" rel="noopener noreferrer" aria-label={`Xem ảnh ${label}`} />
          }
        >
          <ExternalLink className="size-3.5" aria-hidden />
        </Button>
      ) : null}
    </div>
  )
}

export function HanetAvatarCard({
  row,
  compact = false,
}: {
  row: HanetStoredAvatarRow
  compact?: boolean
}) {
  const label = hanetAvatarLabel(row)
  const src = hanetAvatarSrc(row.imagePath)
  const alias = row.hanetAliasId?.trim() ?? ""
  const personId = row.hanetPersonId?.trim() ?? ""
  const updatedLabel = formatHanetAvatarDate(row.updatedAt ?? row.createdAt)
  const hasLocalPlaceholder = row.imagePath.trim().startsWith("hanet:person:")
  const aliasLabel = alias ? hanetAliasFieldLabel(alias) : ""
  const AliasIcon = alias.includes("@") ? Mail : GraduationCap

  if (compact) {
    return (
      <HanetAvatarInlineCard
        row={row}
        label={label}
        src={src}
        alias={alias}
        personId={personId}
        aliasLabel={aliasLabel}
      />
    )
  }

  return (
    <TooltipProvider delay={250}>
      <Card
        size="sm"
        className="gap-0 overflow-hidden border-border/70 py-0 shadow-sm transition-all hover:border-primary/35 hover:shadow-md"
      >
        <div
          className={cn(
            "relative w-full overflow-hidden bg-muted",
            "aspect-[3/4]",
          )}
        >
          {src ? (
            <img
              src={src}
              alt={label}
              className="size-full object-cover object-top transition-transform duration-300 group-hover/card:scale-[1.02]"
              loading="lazy"
            />
          ) : (
            <div className="flex size-full flex-col items-center justify-center gap-2 bg-gradient-to-b from-muted/40 to-muted text-muted-foreground">
              <div className="flex size-12 items-center justify-center rounded-full bg-background text-base font-semibold text-foreground shadow-sm">
                {hanetAvatarInitials(label)}
              </div>
              <ScanFace className="size-4 opacity-50" aria-hidden />
            </div>
          )}

          <div className="pointer-events-none absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 via-black/45 to-transparent px-3 pt-10 pb-2.5">
            <p
              className="line-clamp-2 text-sm font-semibold leading-tight text-white"
              title={label}
            >
              {label}
            </p>
            {updatedLabel ? (
              <p className="mt-0.5 flex items-center gap-1 text-[10px] text-white/75">
                <Clock3 className="size-3 shrink-0" aria-hidden />
                {updatedLabel}
              </p>
            ) : null}
          </div>

          {(row.userId || hasLocalPlaceholder) && (
            <div className="absolute top-2 right-2 flex max-w-[calc(100%-1rem)] flex-col items-end gap-1">
              {row.userId ? (
                <Badge
                  variant="success"
                  className="h-5 gap-1 border-0 bg-success/90 px-1.5 text-[10px] text-white shadow-sm"
                >
                  <UserRound className="size-3" aria-hidden />
                  User #{row.userId}
                </Badge>
              ) : null}
              {hasLocalPlaceholder ? (
                <Badge
                  variant="secondary"
                  className="h-5 border-0 bg-background/90 px-1.5 text-[10px] shadow-sm"
                >
                  Chưa có ảnh
                </Badge>
              ) : null}
            </div>
          )}
        </div>

        <CardContent className="space-y-0 px-3 py-2.5">
          <div className="divide-y divide-border/50">
            {alias ? (
              <InfoLine
                icon={AliasIcon}
                label={aliasLabel}
                value={alias}
                copyLabel={aliasLabel}
              />
            ) : null}
            {personId ? (
              <InfoLine
                icon={Fingerprint}
                label="Person ID · HANET"
                value={personId}
                displayValue={truncateMiddleId(personId)}
                copyLabel="Person ID"
              />
            ) : null}
            <InfoLine
              icon={Hash}
              label="Bản ghi local"
              value={String(row.id)}
              copyLabel="ID face_data"
            />
          </div>
        </CardContent>

        {src ? (
          <CardFooter className="gap-2 border-t border-border/50 bg-muted/30 p-2">
            <Button
              variant="outline"
              size="sm"
              nativeButton={false}
              className="h-8 w-full gap-1.5 text-xs"
              render={
                <a href={src} target="_blank" rel="noopener noreferrer" />
              }
            >
              <ExternalLink className="size-3.5" aria-hidden />
              Xem ảnh gốc
            </Button>
          </CardFooter>
        ) : null}
      </Card>
    </TooltipProvider>
  )
}

import { resolveMediaUrl } from "@ui/lib/resolve-media-url"

export function hanetAvatarSrc(imagePath: string): string {
  const trimmed = imagePath.trim()
  if (!trimmed || trimmed.startsWith("hanet:person:")) return ""
  if (/^https?:\/\//i.test(trimmed)) return trimmed
  return resolveMediaUrl(trimmed, 240)
}

export function hanetAvatarInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "?"
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase()
  return `${parts[0]![0] ?? ""}${parts[parts.length - 1]![0] ?? ""}`.toUpperCase()
}

export function hanetAvatarLabel(row: {
  displayName?: string | null
  hanetAliasId?: string | null
  hanetPersonId?: string | null
}): string {
  return (
    row.displayName?.trim() ||
    row.hanetAliasId?.trim() ||
    row.hanetPersonId?.trim() ||
    "—"
  )
}

/** Nhãn field cho alias HANET (mã SV, email, …). */
export function hanetAliasFieldLabel(alias: string): string {
  const value = alias.trim()
  if (!value) return "Alias"
  if (value.includes("@")) return "Email"
  if (/^\d{6,}$/.test(value)) return "Mã SV"
  return "Alias ID"
}

export function formatHanetAvatarDate(iso: string | null | undefined): string {
  if (!iso?.trim()) return ""
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ""
  return new Intl.DateTimeFormat("vi-VN", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date)
}

/** Rút gọn ID dài giữa chừng — hiển thị gọn trên thẻ. */
export function truncateMiddleId(
  value: string,
  head = 10,
  tail = 6,
): string {
  const trimmed = value.trim()
  if (trimmed.length <= head + tail + 1) return trimmed
  return `${trimmed.slice(0, head)}…${trimmed.slice(-tail)}`
}

"use client"

import { useState } from "react"
import Link from "next/link"
import { Loader2, RefreshCw, UserPlus } from "lucide-react"
import { useQuery, useQueryClient } from "@tanstack/react-query"
import { Button } from "@ui/components/button"
import {
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { api } from "@workspace/admin-app/lib/api"
import type { HanetFaceActionId } from "@workspace/admin-app/lib/hanet-face-actions"
import type { HanetSyncAvatarsResult } from "@workspace/api-client"
import { readHanetAdminPlaceId } from "@workspace/admin-app/lib/hanet-place-storage"
import { useHanetStatusQuery } from "@workspace/admin-app/modules/events/_component/_query"
import { HanetPlaceSelect } from "@workspace/admin-app/modules/hanet/_component/hanet-place-select"
import { HanetFaceActionDialog } from "./hanet-face-action-dialog"
import { HanetRegisterFaceDialog } from "./hanet-register-face-dialog"
import { HanetPersonsTable } from "./hanet-persons-table"
import type { HanetPersonRow } from "./hanet-persons-table"

const DEFAULT_PAGE_SIZE = 50

export function HanetAvatarsTab() {
  const queryClient = useQueryClient()
  const { data: hanetStatus } = useHanetStatusQuery()
  const [selectedPlaceId, setSelectedPlaceId] = useState(readHanetAdminPlaceId)
  const [pageIndex, setPageIndex] = useState(0)
  const [pageSize, setPageSize] = useState(DEFAULT_PAGE_SIZE)
  const [registerOpen, setRegisterOpen] = useState(false)
  const [faceActionId, setFaceActionId] = useState<HanetFaceActionId | null>(
    null,
  )
  const [facePerson, setFacePerson] = useState<HanetPersonRow | null>(null)

  const effectivePlaceId =
    selectedPlaceId || hanetStatus?.defaultPlaceId || ""

  const personsQuery = useQuery({
    queryKey: [
      "hanet",
      "persons",
      effectivePlaceId,
      pageIndex,
      pageSize,
    ],
    queryFn: () =>
      api.hanet.listPersons({
        placeId: effectivePlaceId || undefined,
        pageIndex,
        pageSize,
      }),
    enabled: hanetStatus?.configured === true && Boolean(effectivePlaceId),
  })

  const syncMutation = useAdminMutation({
    mutationKey: ["hanet", "avatars", "sync"],
    mutationFn: () =>
      api.hanet.syncPersonAvatars(effectivePlaceId || undefined),
    toast: {
      loading: "Đang đồng bộ avatar từ HANET vào face_data…",
      success: (res: HanetSyncAvatarsResult) =>
        res.listLimited && res.hanetTotal != null
          ? `Đã đồng bộ ${res.fetched} người (HANET có ${res.hanetTotal} — API chỉ trả ~${res.hanetListCap ?? 50}/lần)`
          : `Đã đồng bộ ${res.fetched} người (${res.created} mới, ${res.updated} cập nhật)`,
      error: (err) =>
        err instanceof Error ? err.message : "Không đồng bộ được avatar HANET",
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["hanet", "avatars"] })
      void queryClient.invalidateQueries({ queryKey: ["hanet", "persons"] })
    },
  })

  if (!hanetStatus?.configured) {
    return (
      <FieldSet variant="section">
        <FieldSectionLegend
          title="Chưa cấu hình OAuth"
          description="Thiết lập client ID, secret và token trong .env API trước khi gọi person/getListByPlace."
        />
        <FieldSetContent>
          <p className="rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-2.5 text-sm text-amber-950 dark:text-amber-100">
            Cấu hình OAuth trong .env API, sau đó kiểm tra tại trang{" "}
            <strong>Kết nối</strong>.
          </p>
        </FieldSetContent>
      </FieldSet>
    )
  }

  const items = personsQuery.data?.items ?? []

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-border/70 bg-muted/20 px-4 py-3 text-sm">
        <p className="text-muted-foreground">
          {personsQuery.data?.listLimited &&
          personsQuery.data.hanetTotal != null ? (
            <>
              HANET báo{" "}
              <span className="font-medium text-foreground">
                {personsQuery.data.hanetTotal}
              </span>{" "}
              người · hiển thị được{" "}
              <span className="font-medium text-foreground">
                {personsQuery.data.total}
              </span>
            </>
          ) : (
            <>
              Tổng{" "}
              <span className="font-medium text-foreground">
                {personsQuery.data?.total ?? "—"}
              </span>{" "}
              người
            </>
          )}
          {personsQuery.data?.syncedTotal != null &&
          personsQuery.data.syncedTotal > 0 ? (
            <>
              {" "}
              · đã sync local{" "}
              <span className="font-medium text-foreground">
                {personsQuery.data.syncedTotal}
              </span>
            </>
          ) : null}
          {items.length > 0 ? (
            <>
              {" "}
              · trang {pageIndex + 1} hiển thị {items.length} dòng
            </>
          ) : null}
        </p>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="gap-1.5"
          disabled={!effectivePlaceId}
          onClick={() => setRegisterOpen(true)}
        >
          <UserPlus className="size-4" />
          registerByUrl
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="ml-auto gap-1.5"
          disabled={syncMutation.isPending || !effectivePlaceId}
          onClick={() => syncMutation.mutate()}
        >
          {syncMutation.isPending ? (
            <Loader2 className="size-4 animate-spin" />
          ) : (
            <RefreshCw className="size-4" />
          )}
          Đồng bộ vào face_data
        </Button>
        <Link
          href="https://developers.hanet.ai/document"
          target="_blank"
          rel="noopener noreferrer"
          className="text-xs text-primary hover:underline"
        >
          Tài liệu HANET
        </Link>
      </div>

      {personsQuery.data?.listLimited ? (
        <p className="rounded-lg border border-amber-500/40 bg-amber-500/10 px-4 py-3 text-sm text-amber-950 dark:text-amber-100">
          Partner API <code className="text-xs">person/getListByPlace</code> chỉ
          trả tối đa ~{personsQuery.data.hanetListCap ?? 50} người mỗi lần gọi
          (mọi <code className="text-xs">pageIndex</code> đều trùng danh sách).
          Hub không thể kéo đủ{" "}
          {personsQuery.data.hanetTotal ?? "tổng HANET"} người qua API này — cần
          gói cloud HANET hoặc tích lũy qua webhook Face Data. Đã lưu local:{" "}
          {personsQuery.data.syncedTotal ?? 0} bản ghi.
        </p>
      ) : null}

      {hanetStatus.configured && !effectivePlaceId ? (
        <p className="rounded-lg border border-amber-500/40 bg-amber-500/10 px-4 py-3 text-sm text-amber-900 dark:text-amber-200">
          Chọn địa điểm HANET bên dưới để tải danh sách avatar.
        </p>
      ) : null}

      <HanetPersonsTable
        data={items}
        isLoading={personsQuery.isLoading}
        emptyLabel={
          effectivePlaceId
            ? pageIndex > 0 && items.length === 0
              ? "Trang này chưa có dữ liệu — bấm «Đồng bộ vào face_data» để kéo thêm từ HANET (API HANET hiện chỉ trả ~50 người/lần)."
              : "Không có person cho địa điểm này."
            : "Chọn địa điểm HANET để tải danh sách avatar."
        }
        pageIndex={pageIndex}
        pageSize={pageSize}
        total={personsQuery.data?.total}
        hanetTotal={personsQuery.data?.hanetTotal}
        listLimited={personsQuery.data?.listLimited}
        onPageIndexChange={setPageIndex}
        onPageSizeChange={(size) => {
          setPageSize(size)
          setPageIndex(0)
        }}
        onFaceAction={(actionId, person) => {
          setFaceActionId(actionId)
          setFacePerson(person)
        }}
        filterToolbarExtra={
          <HanetPlaceSelect
            layout="stacked"
            value={selectedPlaceId}
            onChange={(id) => {
              setSelectedPlaceId(id)
              setPageIndex(0)
            }}
            defaultPlaceId={hanetStatus.defaultPlaceId}
            disabled={syncMutation.isPending}
          />
        }
      />

      <HanetRegisterFaceDialog
        open={registerOpen}
        placeId={effectivePlaceId}
        onClose={() => setRegisterOpen(false)}
        onSuccess={() => {
          void queryClient.invalidateQueries({ queryKey: ["hanet", "persons"] })
          void queryClient.invalidateQueries({ queryKey: ["hanet", "avatars"] })
        }}
      />

      <HanetFaceActionDialog
        open={faceActionId != null}
        actionId={faceActionId}
        placeId={effectivePlaceId}
        person={facePerson}
        onClose={() => {
          setFaceActionId(null)
          setFacePerson(null)
        }}
        onSuccess={() => {
          void queryClient.invalidateQueries({ queryKey: ["hanet", "persons"] })
          void queryClient.invalidateQueries({ queryKey: ["hanet", "avatars"] })
        }}
      />
    </div>
  )
}

