"use client"

import { useCallback, useMemo, useState } from "react"
import { Check, Copy, Loader2, Pause, Play, Radio } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { toast } from "@ui/components/sonner"
import { cn } from "@ui/lib/utils"
import type { EventHanetSyncSocketPayload } from "@workspace/api-client/realtime"

export type HanetCheckinLiveBarProps = {
  liveEnabled: boolean
  onLiveEnabledChange: (enabled: boolean) => void
  lastSyncAt: Date | null
  lastPayload: EventHanetSyncSocketPayload | null
  isFetching: boolean
  pollIntervalMs?: number | null
  socketConnected?: boolean
  socketError?: boolean
  webhookLocalhost?: boolean
  webhookUrl?: string | null
  lastWebhookAt?: string | null
}

function buildHanetLiveIssueReport(options: {
  webhookLocalhost?: boolean
  webhookUrl?: string | null
  lastWebhookAt?: string | null
  socketConnected?: boolean
  socketError?: boolean
  pollIntervalMs?: number | null
}): string {
  const lines = [
    "[HANET check-in] Báo cáo vấn đề realtime",
    "",
    "Trạng thái:",
    `- Webhook URL Hub: ${options.webhookUrl?.trim() || "—"}`,
    `- Webhook localhost: ${options.webhookLocalhost ? "Có (HANET cloud không gọi được)" : "Không"}`,
    `- Socket admin: ${options.socketError ? "Lỗi" : options.socketConnected ? "OK" : "Chưa kết nối"}`,
    `- Poll dự phòng: ${options.pollIntervalMs ? `${Math.round(options.pollIntervalMs / 1000)}s` : "—"}`,
    `- Webhook gần nhất tới Hub: ${options.lastWebhookAt?.trim() || "Chưa có"}`,
    "",
  ]

  if (options.webhookLocalhost) {
    lines.push(
      "Vấn đề:",
      "Webhook đang trỏ localhost — HANET cloud không thể POST tới máy dev.",
      "",
      "Cách khắc phục:",
      "1. Chạy tunnel public tới API (vd. ngrok http 3002)",
      "2. .env API (apps/hub-checkin/api hoặc hub-parent/api):",
      "   API_PUBLIC_URL=https://<tunnel-host>",
      "   (có thể thêm /api — Hub tự chuẩn hóa URL webhook)",
      "3. Restart API (pnpm dev:checkin hoặc pnpm dev:parent)",
      "4. Đăng ký URL trên https://developers.hanet.ai:",
      "   https://<tunnel-host>/api/public/hanet/webhook",
      "5. Quét face → kiểm tra GET /api/admin/hanet/webhook/recent",
      "",
      "URL đăng ký mẫu:",
      "https://<API_PUBLIC_URL>/api/public/hanet/webhook",
    )
  } else if (!options.lastWebhookAt) {
    lines.push(
      "Vấn đề:",
      "Chưa thấy webhook nào tới Hub sau khi quét.",
      "",
      "Kiểm tra:",
      "1. URL webhook trên developers.hanet.ai khớp URL Hub ở trên",
      "2. API đang chạy và reachable từ internet",
      "3. GET /api/admin/hanet/webhook/recent sau khi quét",
      "4. Log API có dòng: HANET webhook ← device=...",
    )
  } else {
    lines.push(
      "Ghi chú:",
      "Webhook đã tới Hub — nếu bảng chưa cập nhật, kiểm tra placeID và tab realtime.",
    )
  }

  return lines.join("\n")
}

export function HanetCheckinLiveBar({
  liveEnabled,
  onLiveEnabledChange,
  lastSyncAt,
  lastPayload,
  isFetching,
  pollIntervalMs,
  socketConnected,
  socketError,
  webhookLocalhost,
  webhookUrl,
  lastWebhookAt,
}: HanetCheckinLiveBarProps) {
  const [copied, setCopied] = useState(false)

  const lastSummary =
    lastPayload?.summary?.trim() ||
    (lastPayload?.kind === "checkin"
      ? "Check-in mới"
      : lastPayload?.kind === "checkout"
        ? "Check-out mới"
        : null)

  const showIssueHint =
    liveEnabled && (webhookLocalhost || (!webhookLocalhost && !lastWebhookAt))

  const issueReport = useMemo(
    () =>
      buildHanetLiveIssueReport({
        webhookLocalhost,
        webhookUrl,
        lastWebhookAt,
        socketConnected,
        socketError,
        pollIntervalMs,
      }),
    [
      webhookLocalhost,
      webhookUrl,
      lastWebhookAt,
      socketConnected,
      socketError,
      pollIntervalMs,
    ],
  )

  const onCopyIssue = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(issueReport)
      setCopied(true)
      toast.success("Đã copy báo cáo vấn đề webhook")
      window.setTimeout(() => setCopied(false), 1600)
    } catch {
      toast.error("Không copy được — thử chọn và copy thủ công")
    }
  }, [issueReport])

  return (
    <div className="flex flex-col gap-2 rounded-lg border border-border/70 bg-card px-3 py-2.5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <span
            className={cn(
              "relative flex size-2.5 shrink-0 rounded-full",
              liveEnabled ? "bg-emerald-500" : "bg-muted-foreground/40",
            )}
          >
            {liveEnabled ? (
              <span className="absolute inline-flex size-full animate-ping rounded-full bg-emerald-400 opacity-60" />
            ) : null}
          </span>
          <Radio className="size-4 shrink-0 text-primary" aria-hidden />
          <span className="text-sm font-medium">Theo dõi realtime</span>
          {liveEnabled ? (
            <Badge variant="secondary" className="text-[10px]">
              Webhook · poll{" "}
              {pollIntervalMs ? `${Math.round(pollIntervalMs / 1000)}s` : "—"}
            </Badge>
          ) : null}
          {liveEnabled ? (
            <Badge
              variant={
                socketError ? "destructive" : socketConnected ? "default" : "outline"
              }
              className="text-[10px]"
            >
              Socket {socketError ? "lỗi" : socketConnected ? "OK" : "…"}
            </Badge>
          ) : null}
          {isFetching ? (
            <Loader2
              className="size-3.5 shrink-0 animate-spin text-muted-foreground"
              aria-label="Đang tải lại"
            />
          ) : null}
          {liveEnabled && lastSyncAt ? (
            <span className="truncate text-xs text-muted-foreground">
              Cập nhật {lastSyncAt.toLocaleTimeString("vi-VN")}
              {lastSummary ? ` · ${lastSummary}` : ""}
            </span>
          ) : liveEnabled ? (
            <span className="text-xs text-muted-foreground">
              {socketError
                ? "Socket chưa kết nối — cần đăng nhập admin và webhook HANET tới API."
                : "Chờ webhook HANET (1–3 giây sau khi quét)…"}
            </span>
          ) : null}
        </div>
        <Button
          type="button"
          variant={liveEnabled ? "secondary" : "default"}
          size="sm"
          className="h-8 shrink-0 text-xs"
          onClick={() => onLiveEnabledChange(!liveEnabled)}
        >
          {liveEnabled ? (
            <>
              <Pause className="size-3.5" />
              Tạm dừng
            </>
          ) : (
            <>
              <Play className="size-3.5" />
              Bật realtime
            </>
          )}
        </Button>
      </div>

      {showIssueHint ? (
        <div
          className={cn(
            "flex flex-wrap items-start justify-between gap-2 rounded-md border px-2.5 py-2",
            webhookLocalhost
              ? "border-amber-500/40 bg-amber-500/5"
              : "border-border/60 bg-muted/30",
          )}
        >
          <p
            className={cn(
              "min-w-0 flex-1 text-xs leading-relaxed",
              webhookLocalhost
                ? "text-amber-800 dark:text-amber-300"
                : "text-muted-foreground",
            )}
          >
            {webhookLocalhost ? (
              <>
                Webhook đang trỏ{" "}
                <code className="rounded bg-muted px-1">{webhookUrl || "localhost"}</code> — HANET
                cloud không gọi được. Dùng ngrok/tunnel +{" "}
                <code className="rounded bg-muted px-1">API_PUBLIC_URL</code>, rồi đăng ký URL
                trên developers.hanet.ai.
              </>
            ) : (
              <>
                Chưa thấy webhook nào tới Hub — quét thử face rồi kiểm tra{" "}
                <code className="rounded bg-muted px-1">
                  GET /admin/hanet/webhook/recent
                </code>
                .
              </>
            )}
          </p>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-7 shrink-0 gap-1.5 px-2 text-[11px]"
            onClick={() => void onCopyIssue()}
          >
            {copied ? (
              <Check className="size-3.5 text-success" aria-hidden />
            ) : (
              <Copy className="size-3.5" aria-hidden />
            )}
            Copy vấn đề
          </Button>
        </div>
      ) : null}
    </div>
  )
}

"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { Clock, LogIn, LogOut, User, UserRoundX } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { FieldCopyButton } from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import type { HanetCheckinRow } from "@workspace/admin-app/lib/hanet-checkin-parse"

/** Khớp cột «Xem trước» trên /admin/file-storage */
export const HANET_CHECKIN_PREVIEW_COLUMN_CLASS =
  "w-[120px] min-w-[120px] max-w-[120px]"

const CHECKIN_PREVIEW_FRAME_CLASS =
  "flex aspect-square w-full cursor-pointer items-center justify-center overflow-hidden rounded-md border border-border bg-muted"

function HanetCheckinTypeCell({ type }: { type: string }) {
  const label = type.trim()
  if (!label) return <>—</>

  const isCheckin = label === "Check-in"
  const isCheckout = label === "Check-out"
  const isUnknown = label === "Chưa nhận diện"

  const Icon = isCheckin
    ? LogIn
    : isCheckout
      ? LogOut
      : isUnknown
        ? UserRoundX
        : User

  return (
    <div className="flex min-w-0 items-center gap-2">
      <div
        className={cn(
          "flex size-7 shrink-0 items-center justify-center rounded-full",
          isCheckin &&
            "bg-emerald-500/15 text-emerald-700 dark:text-emerald-400",
          isCheckout &&
            "bg-amber-500/15 text-amber-700 dark:text-amber-400",
          isUnknown &&
            "bg-rose-500/10 text-rose-700 dark:text-rose-400",
          !isCheckin &&
            !isCheckout &&
            !isUnknown &&
            "bg-muted text-muted-foreground",
        )}
        aria-hidden
      >
        <Icon className="size-3.5" />
      </div>
      <Badge
        variant={isCheckin ? "default" : "secondary"}
        className={cn(
          "h-5 shrink-0 text-[10px] font-medium",
          isCheckin &&
            "border-emerald-600/30 bg-emerald-600 text-white hover:bg-emerald-600/90 dark:border-emerald-500/40",
          isCheckout &&
            "border-amber-300/80 bg-amber-100 text-amber-900 hover:bg-amber-100 dark:border-amber-700 dark:bg-amber-950 dark:text-amber-200",
          isUnknown &&
            "border-rose-300/80 bg-rose-50 text-rose-800 hover:bg-rose-50 dark:border-rose-800 dark:bg-rose-950 dark:text-rose-200",
          !isCheckin &&
            !isCheckout &&
            !isUnknown &&
            "font-normal",
        )}
      >
        {label}
      </Badge>
    </div>
  )
}

export type HanetCheckinColumnsOptions = {
  onPreviewImage?: (row: HanetCheckinRow) => void
  /** Danh sách camera HANET — dùng cho `filterVariant: select` trên cột deviceID. */
  deviceSelectOptions?: { value: string; label: string }[]
}

/** Chuỗi hiển thị `checkinAt` (vi-VN) → `YYYY-MM-DD` cho date-range filter. */
function parseHanetCheckinDisplayDate(value: unknown): string | null {
  const text = String(value ?? "").trim()
  if (!text || text === "—") return null

  const viMatch = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/)
  if (viMatch) {
    const dd = viMatch[1]
    const mm = viMatch[2]
    const yyyy = viMatch[3]
    if (!dd || !mm || !yyyy) return null
    return `${yyyy}-${mm.padStart(2, "0")}-${dd.padStart(2, "0")}`
  }

  if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.slice(0, 10)

  const parsed = new Date(text)
  return Number.isNaN(parsed.getTime())
    ? null
    : parsed.toISOString().slice(0, 10)
}

function hanetCheckinDateRangeFilterFn(
  row: { getValue: (columnId: string) => unknown },
  columnId: string,
  filterValue: unknown,
): boolean {
  if (filterValue == null || filterValue === "") return true
  const rowDate = parseHanetCheckinDisplayDate(row.getValue(columnId))
  if (!rowDate) return false
  const [fromStr = "", toStr = ""] = String(filterValue).split(",")
  if (fromStr && rowDate < fromStr) return false
  if (toStr && rowDate > toStr) return false
  return true
}

export function getHanetCheckinColumns(
  options?: HanetCheckinColumnsOptions,
): ColumnDef<HanetCheckinRow>[] {
  return [
    {
      accessorKey: "avatarUrl",
      header: "Ảnh",
      enableColumnFilter: false,
      enableHiding: false,
      size: 120,
      minSize: 120,
      meta: {
        disableCellLineClamp: true,
        className: cn(HANET_CHECKIN_PREVIEW_COLUMN_CLASS, "py-2"),
      },
      cell: ({ row, getValue }) => {
        const avatar = String(getValue() ?? "").trim()
        if (!avatar) {
          return (
            <div
              className={cn(
                CHECKIN_PREVIEW_FRAME_CLASS,
                "cursor-default text-sm text-muted-foreground",
              )}
            >
              —
            </div>
          )
        }

        const image = (
          <img
            src={avatar}
            alt=""
            className="size-full object-cover"
            loading="lazy"
            decoding="async"
          />
        )

        if (options?.onPreviewImage) {
          return (
            <button
              type="button"
              onClick={() => options.onPreviewImage?.(row.original)}
              className={CHECKIN_PREVIEW_FRAME_CLASS}
              title="Xem ảnh check-in"
            >
              {image}
            </button>
          )
        }

        return (
          <a
            href={avatar}
            target="_blank"
            rel="noopener noreferrer"
