"use client"

import { CheckCircle2, Loader2, Wifi, WifiOff, XCircle } from "lucide-react"
import { Badge } from "@ui/components/badge"
import {
  FieldCopyButton,
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import { HanetJsonPreview } from "./hanet-json-preview"

export type HanetDeviceConnectionRow = {
  deviceId: string
  online: boolean
}

/** Parse `{ deviceID: true|false }` từ `getConnectionStatus`. */
export function parseHanetConnectionStatus(
  data: unknown
): HanetDeviceConnectionRow[] {
  if (!data || typeof data !== "object" || Array.isArray(data)) return []

  return Object.entries(data as Record<string, unknown>)
    .filter(([, value]) => typeof value === "boolean")
    .map(([deviceId, online]) => ({
      deviceId,
      online: online as boolean,
    }))
}

export function ConnectionStatusBadge({ online }: { online: boolean }) {
  return (
    <Badge
      variant={online ? "success" : "destructive"}
      className="h-6 gap-1 px-2 text-[11px] font-medium"
    >
      {online ? (
        <Wifi className="size-3 shrink-0" aria-hidden />
      ) : (
        <WifiOff className="size-3 shrink-0" aria-hidden />
      )}
      {online ? "Online" : "Offline"}
    </Badge>
  )
}

function ConnectionRow({ deviceId, online }: HanetDeviceConnectionRow) {
  return (
    <div
      className={cn(
        "flex flex-wrap items-center justify-between gap-3 rounded-md border px-3 py-2.5",
        online
          ? "border-emerald-500/30 bg-emerald-500/5"
          : "border-rose-500/30 bg-rose-500/5"
      )}
    >
      <div className="flex min-w-0 items-center gap-2">
        {online ? (
          <CheckCircle2
            className="size-4 shrink-0 text-emerald-600 dark:text-emerald-400"
            aria-hidden
          />
        ) : (
          <XCircle
            className="size-4 shrink-0 text-rose-600 dark:text-rose-400"
            aria-hidden
          />
        )}
        <div className="min-w-0">
          <p className="text-xs text-muted-foreground">deviceID</p>
          <div className="flex items-center gap-2">
            <code className="text-sm font-medium">{deviceId}</code>
            <FieldCopyButton text={deviceId} />
          </div>
        </div>
      </div>
      <ConnectionStatusBadge online={online} />
    </div>
  )
}

export type HanetDeviceConnectionPanelProps = {
  deviceId: string
  data: unknown
  isLoading?: boolean
}

export function HanetDeviceConnectionPanel({
  deviceId,
  data,
  isLoading = false,
}: HanetDeviceConnectionPanelProps) {
  const rows = parseHanetConnectionStatus(data)
  const hasStructuredRows = rows.length > 0

  return (
    <FieldSet variant="section">
      <FieldSectionLegend
        title="Trạng thái kết nối"
        description="Kết quả POST /device/getConnectionStatus — thiết bị online khi camera đang kết nối HANET."
      />
      <FieldSetContent className="space-y-3">
        {isLoading ? (
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Loader2 className="size-4 animate-spin" aria-hidden />
            Đang kiểm tra <code className="text-xs">{deviceId}</code>…
          </div>
        ) : null}

        {!isLoading && hasStructuredRows ? (
          <div className="space-y-2">
            {rows.map((row) => (
              <ConnectionRow key={row.deviceId} {...row} />
            ))}
          </div>
        ) : null}

        {!isLoading && !hasStructuredRows && data != null ? (
          <HanetJsonPreview data={data} />
        ) : null}
      </FieldSetContent>
    </FieldSet>
  )
}

"use client"

import { Camera, Copy, Radio } from "lucide-react"
import {
  DataTableRowActionsMenu,
  TABLE_ACTIONS_COLUMN_META,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import type { HanetDeviceOption } from "@workspace/admin-app/lib/hanet-device-parse"

export type HanetDeviceRowActionsProps = {
  device: HanetDeviceOption
  busy?: boolean
  ensureBusy?: boolean
  onCheckConnection: () => void
  onEnsureCamera?: () => void
}

export function HanetDeviceRowActions({
  device,
  busy,
  ensureBusy,
  onCheckConnection,
  onEnsureCamera,
}: HanetDeviceRowActionsProps) {
  const actions: DataTableRowActionItem[] = [
    {
      key: "check-connection",
      label: "Kiểm tra kết nối",
      hint: "Gọi getConnectionStatus cho thiết bị này",
      onClick: onCheckConnection,
      icon: <Radio />,
      group: "primary",
      disabled: busy,
    },
  ]

  if (onEnsureCamera) {
    actions.push({
      key: "ensure-camera",
      label: "Gắn camera Hub",
      hint: "Tạo/cập nhật bản ghi cameras theo deviceID (gắn sự kiện)",
      onClick: onEnsureCamera,
      icon: <Camera />,
      group: "primary",
      disabled: ensureBusy,
    })
  }

  if (device.deviceId) {
    actions.push({
      key: "copy-device-id",
      label: "Sao chép deviceID",
      hint: device.deviceId,
      onClick: () => {
        void navigator.clipboard.writeText(device.deviceId)
      },
      icon: <Copy />,
      group: "primary",
    })
  }

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={busy || ensureBusy}
      autoConfirmDangerousActions={false}
      triggerLabel={`Thao tác thiết bị ${device.name || device.deviceId}`}
      groups={{
        primary: { label: "Thao tác", sublabel: false },
      }}
    />
  )
}

export const hanetDeviceActionsColumnMeta = {
  ...TABLE_ACTIONS_COLUMN_META,
  className: `${TABLE_ACTIONS_COLUMN_META.className} sticky right-0 z-[10]`,
}

"use client"

import { useMemo, type ReactNode } from "react"
import type { ColumnDef } from "@tanstack/react-table"
import { Camera, Loader2 } from "lucide-react"
import { AdminDataTable, defineDataTableActionsColumn } from "@ui/components/data-table"
import { FieldCopyButton } from "@ui/components/field"
import type { HanetDeviceOption } from "@workspace/admin-app/lib/hanet-device-parse"
import { ConnectionStatusBadge } from "./hanet-device-connection-panel"
import {
  HanetDeviceRowActions,
  hanetDeviceActionsColumnMeta,
} from "./hanet-device-row-actions"

export type HanetDeviceConnectionStatusMap = Record<string, boolean | undefined>

export type HanetDevicesTableProps = {
  data: HanetDeviceOption[]
  isLoading?: boolean
  emptyLabel?: string
  filterToolbarExtra?: ReactNode
  connectionStatusByDeviceId?: HanetDeviceConnectionStatusMap
  checkingDeviceId?: string | null
  isCheckingConnection?: boolean
  ensuringDeviceId?: string | null
  isEnsuringCamera?: boolean
  onCheckConnection: (deviceId: string) => void
  onEnsureCamera?: (device: HanetDeviceOption) => void
}

export function HanetDevicesTable({
  data,
  isLoading = false,
  emptyLabel = "Không có thiết bị cho địa điểm này.",
  filterToolbarExtra,
  connectionStatusByDeviceId = {},
  checkingDeviceId = null,
  isCheckingConnection = false,
  ensuringDeviceId = null,
  isEnsuringCamera = false,
  onCheckConnection,
  onEnsureCamera,
}: HanetDevicesTableProps) {
  const columns = useMemo<ColumnDef<HanetDeviceOption>[]>(
    () => [
      {
        accessorKey: "deviceId",
        header: "deviceID",
        enableColumnFilter: false,
        size: 200,
        cell: ({ getValue }) => {
          const deviceId = String(getValue() ?? "").trim()
          if (!deviceId) return "—"
          return (
            <div className="flex items-center gap-2">
              <code className="text-xs font-medium">{deviceId}</code>
              <FieldCopyButton text={deviceId} />
            </div>
          )
        },
      },
      {
        accessorKey: "name",
        header: "Tên",
        enableColumnFilter: false,
        cell: ({ getValue }) => {
          const name = String(getValue() ?? "").trim() || "—"
          return (
            <div className="flex min-w-0 items-center gap-2">
              <Camera
                className="size-3.5 shrink-0 text-muted-foreground"
                aria-hidden
              />
              <span className="min-w-0 truncate">{name}</span>
            </div>
          )
        },
      },
      {
        id: "status",
        header: "Trạng thái",
        enableColumnFilter: false,
        size: 120,
        cell: ({ row }) => {
          const deviceId = row.original.deviceId
          const isChecking =
            isCheckingConnection && checkingDeviceId === deviceId
          const online = connectionStatusByDeviceId[deviceId]

          if (isChecking) {
            return (
              <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                <Loader2 className="size-3.5 animate-spin" aria-hidden />
                Đang kiểm tra…
              </span>
            )
          }

          if (online === undefined) {
            return (
              <span className="text-xs text-muted-foreground">Chưa kiểm tra</span>
            )
          }

          return <ConnectionStatusBadge online={online} />
        },
      },
      defineDataTableActionsColumn<HanetDeviceOption>({
        columnMeta: hanetDeviceActionsColumnMeta,
        cell: ({ row }) => {
          const deviceId = row.original.deviceId
          const isBusy =
            isCheckingConnection && checkingDeviceId === deviceId
          const isEnsuring =
            isEnsuringCamera && ensuringDeviceId === deviceId

          return (
            <HanetDeviceRowActions
              device={row.original}
              busy={isBusy}
              ensureBusy={isEnsuring}
              onCheckConnection={() => onCheckConnection(deviceId)}
              onEnsureCamera={
                onEnsureCamera
                  ? () => onEnsureCamera(row.original)
                  : undefined
              }
            />
          )
        },
      }),
    ],
    [
      checkingDeviceId,
      connectionStatusByDeviceId,
      ensuringDeviceId,
      isCheckingConnection,
      isEnsuringCamera,
      onCheckConnection,
      onEnsureCamera,
    ]
  )

  return (
    <AdminDataTable<HanetDeviceOption>
      tableScope="hanet-devices"
      data={data}
      columns={columns}
      getRowId={(row) => row.deviceId}
      isLoading={isLoading}
      emptyLabel={emptyLabel}
      globalFilterPlaceholder="Tìm theo deviceID hoặc tên thiết bị…"
      globalFilterLabel="Tìm kiếm"
      getGlobalFilterText={(row) =>
        [row.deviceId, row.name].filter(Boolean).join(" ")
      }
      filterToolbarExtra={filterToolbarExtra}
      footer={
        <p className="text-sm text-muted-foreground">
          {isLoading
            ? "Đang tải…"
            : `Tổng ${data.length} thiết bị`}
        </p>
      }
    />
  )
}

