"use client"

import { useState } from "react"
import Link from "next/link"
import {
  AlertTriangle,
  BookOpen,
  CheckCircle2,
  ExternalLink,
  Layers,
} from "lucide-react"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@ui/components/dialog"
import { toast } from "@ui/components/sonner"
import { cn } from "@ui/lib/utils"
import { summarizePartnerEndpoints } from "@workspace/admin-app/lib/hanet-partner-api-format"
import {
  HANET_PARTNER_API_BASE,
  HANET_POSTMAN_DOCS_URL,
  type HanetPartnerEndpoint,
} from "@workspace/admin-app/lib/hanet-postman"
import {
  HanetPartnerApiTable,
} from "./hanet-partner-api-list"

function StatCard({
  label,
  value,
  tone = "default",
  icon: Icon,
}: {
  label: string
  value: number
  tone?: "default" | "success" | "warning"
  icon: typeof Layers
}) {
  return (
    <div
      className={cn(
        "rounded-lg border px-3 py-2.5",
        tone === "success" &&
          "border-emerald-500/30 bg-emerald-500/5",
        tone === "warning" &&
          "border-amber-500/35 bg-amber-500/8",
        tone === "default" && "border-border/60 bg-muted/20"
      )}
    >
      <div className="flex items-center gap-2 text-muted-foreground">
        <Icon className="size-3.5 shrink-0" aria-hidden />
        <span className="text-[11px] font-medium uppercase tracking-wide">
          {label}
        </span>
      </div>
      <p className="mt-1 text-2xl font-semibold tabular-nums">{value}</p>
    </div>
  )
}

export function HanetPartnerApiDialog({
  open,
  onOpenChange,
  endpoints,
  title = "Đối chiếu HANET ↔ Hub",
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  endpoints: readonly HanetPartnerEndpoint[]
  title?: string
}) {
  if (endpoints.length === 0) return null

  const stats = summarizePartnerEndpoints(endpoints)

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[92vh] max-w-7xl flex-col gap-0 overflow-hidden p-4">
        <DialogHeader className="shrink-0 space-y-3 border-b border-border/60 bg-gradient-to-b from-muted/40 to-background px-6 py-5 text-left">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div className="space-y-1">
              <DialogTitle className="text-lg">{title}</DialogTitle>
              <DialogDescription className="text-sm">
                So khớp Postman Partner API với route Nest Hub Admin — xác định
                endpoint nào chưa được proxy.
              </DialogDescription>
            </div>
            <Link
              href={HANET_POSTMAN_DOCS_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex h-9 shrink-0 items-center gap-1.5 rounded-md border border-border/60 bg-background px-3 text-xs font-medium text-primary shadow-sm hover:bg-muted/40"
            >
              Postman
              <ExternalLink className="size-3.5" aria-hidden />
            </Link>
          </div>

          <div className="grid gap-2 sm:grid-cols-3">
            <StatCard
              label="Tổng endpoint"
              value={stats.total}
              icon={Layers}
            />
            <StatCard
              label="Đã có Hub"
              value={stats.proxied}
              tone="success"
              icon={CheckCircle2}
            />
            <StatCard
              label="Chưa cấu hình Hub"
              value={stats.missing}
              tone={stats.missing > 0 ? "warning" : "default"}
              icon={AlertTriangle}
            />
          </div>

          <p className="text-xs text-muted-foreground">
            Partner base:{" "}
            <code className="rounded bg-muted px-1 py-0.5">
              {HANET_PARTNER_API_BASE}
            </code>
          </p>
        </DialogHeader>

        <div className="min-h-0 flex-1 overflow-y-auto px-6 py-4">
          <HanetPartnerApiTable
            endpoints={endpoints}
            tableScope="hanet-partner-api-dialog"
            onCopied={(label) =>
              toast.success(`Đã copy ${label} vào clipboard`)
            }
          />
        </div>
      </DialogContent>
    </Dialog>
  )
}

/** Nút mở dialog đối chiếu API — header trang HANET. */
export function HanetPartnerApiDialogTrigger({
  endpoints,
}: {
  endpoints: readonly HanetPartnerEndpoint[]
}) {
  const [open, setOpen] = useState(false)

  if (endpoints.length === 0) return null

  const stats = summarizePartnerEndpoints(endpoints)

  return (
    <>
      <Button
        type="button"
        variant="outline"
        size="sm"
        className={cn(
          "gap-1.5 shadow-sm",
          stats.missing > 0 &&
            "border-amber-500/40 bg-amber-500/5 hover:bg-amber-500/10"
        )}
        onClick={() => setOpen(true)}
      >
        <BookOpen className="size-4 text-primary" aria-hidden />
        <span>Partner API</span>
        <Badge variant="secondary" className="h-5 px-1.5 text-[10px] font-normal">
          {stats.total}
        </Badge>
        {stats.missing > 0 ? (
          <Badge
            variant="outline"
            className="h-5 gap-0.5 border-amber-500/40 bg-amber-500/10 px-1.5 text-[10px] text-amber-900 dark:text-amber-100"
          >
            <AlertTriangle className="size-3" aria-hidden />
            {stats.missing} thiếu Hub
          </Badge>
        ) : null}
      </Button>
      <HanetPartnerApiDialog
        open={open}
        onOpenChange={setOpen}
        endpoints={endpoints}
      />
    </>
  )
}

"use client"

import { useMemo, useState } from "react"
import type { ColumnDef } from "@tanstack/react-table"
import { AlertTriangle, CheckCircle2, Copy } from "lucide-react"
import { AdminDataTable } from "@ui/components/data-table"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import { FieldCopyButton } from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import {
  buildMissingHubConfigText,
  buildPartnerHubComparisonMarkdown,
  copyTextToClipboard,
  formatEndpointMappingLine,
  formatHubEndpointLine,
  formatPartnerEndpointLine,
  isHanetEndpointProxied,
  summarizePartnerEndpoints,
} from "@workspace/admin-app/lib/hanet-partner-api-format"
import {
  HANET_PARTNER_API_BASE,
  type HanetPartnerEndpoint,
} from "@workspace/admin-app/lib/hanet-postman"

type HttpMethod =
  | HanetPartnerEndpoint["partnerMethod"]
  | NonNullable<HanetPartnerEndpoint["hubMethod"]>

export type HanetPartnerApiTableRow = HanetPartnerEndpoint & {
  rowId: string
  hubConfigured: boolean
}

const METHOD_STYLES: Record<string, string> = {
  GET: "bg-emerald-600 text-white dark:bg-emerald-700",
  POST: "bg-amber-600 text-white dark:bg-amber-700",
  PATCH: "bg-sky-600 text-white dark:bg-sky-700",
  DELETE: "bg-rose-600 text-white dark:bg-rose-700",
}

function HttpMethodBadge({ method }: { method: HttpMethod }) {
  return (
    <span
      className={cn(
        "inline-flex w-[3.25rem] shrink-0 items-center justify-center rounded px-1 py-0.5 text-[10px] font-bold tracking-wide uppercase",
        METHOD_STYLES[method] ?? "bg-muted text-muted-foreground"
      )}
    >
      {method}
    </span>
  )
}

function HubProxyStatusBadge({ configured }: { configured: boolean }) {
  if (configured) {
    return (
      <Badge
        variant="outline"
        className="gap-1 border-emerald-500/40 bg-emerald-500/10 text-emerald-800 dark:text-emerald-200"
      >
        <CheckCircle2 className="size-3" aria-hidden />
        Hub ✓
      </Badge>
    )
  }
  return (
    <Badge
      variant="outline"
      className="gap-1 border-amber-500/40 bg-amber-500/10 text-amber-900 dark:text-amber-100"
    >
      <AlertTriangle className="size-3" aria-hidden />
      Chưa proxy
    </Badge>
  )
}

function toTableRows(
  endpoints: readonly HanetPartnerEndpoint[]
): HanetPartnerApiTableRow[] {
  return endpoints.map((endpoint) => ({
    ...endpoint,
    rowId: `${endpoint.group}-${endpoint.partnerPath}-${endpoint.hubPath ?? "partner"}`,
    hubConfigured: isHanetEndpointProxied(endpoint),
  }))
}

function useHanetPartnerApiColumns() {
  return useMemo<ColumnDef<HanetPartnerApiTableRow>[]>(
    () => [
      {
        id: "status",
        header: "Hub",
        enableColumnFilter: false,
        size: 50,
        minSize: 50,
        cell: ({ row }) => (
          <HubProxyStatusBadge configured={row.original.hubConfigured} />
        ),
      },
      {
        accessorKey: "group",
        header: "Nhóm",
        enableColumnFilter: false,
        size: 50,
        minSize: 50,
        cell: ({ getValue }) => (
          <span className="text-sm font-medium">{String(getValue() ?? "")}</span>
        ),
      },
      {
        id: "partner",
        header: "HANET Partner",
        enableColumnFilter: false,
        size: 300,
        minSize: 300,
        cell: ({ row }) => (
          <div className="min-w-0 space-y-1 py-0.5">
            <div className="flex min-w-0 items-start gap-2">
              <HttpMethodBadge method={row.original.partnerMethod} />
              <code className="min-w-0 flex-1 text-xs leading-snug break-all">
                {row.original.partnerPath}
              </code>
              <FieldCopyButton
                text={formatPartnerEndpointLine(row.original)}
                successMessage="Đã copy Partner API"
              />
            </div>
          </div>
        ),
      },
      {
        id: "hub",
        header: "Hub Admin",
        enableColumnFilter: false,
        size: 300,
        minSize: 300,
        cell: ({ row }) => {
          const hubLine = formatHubEndpointLine(row.original)
          if (!hubLine) {
            return (
              <span className="text-xs text-muted-foreground">
                Chưa cấu hình route Nest
              </span>
            )
          }
          const [method, ...pathParts] = hubLine.split(" ")
          const path = pathParts.join(" ")
          return (
            <div className="flex min-w-0 items-start gap-2 py-0.5">
              <HttpMethodBadge method={method as HttpMethod} />
              <code className="min-w-0 flex-1 text-xs leading-snug break-all">
                {path}
              </code>
              <FieldCopyButton
                text={hubLine}
                successMessage="Đã copy Hub API"
              />
            </div>
          )
        },
      },
      {
        id: "mapping",
        header: "Đối chiếu",
        enableColumnFilter: false,
        size: 72,
        meta: { isActionsColumn: true },
        cell: ({ row }) => (
          <FieldCopyButton
            text={formatEndpointMappingLine(row.original)}
            successMessage="Đã copy mapping"
          />
        ),
      },
    ],
    []
  )
}

function HanetPartnerApiCopyToolbar({
  endpoints,
  onlyMissing,
  onOnlyMissingChange,
  onCopied,
}: {
  endpoints: readonly HanetPartnerEndpoint[]
  onlyMissing: boolean
  onOnlyMissingChange: (value: boolean) => void
  onCopied?: (label: string) => void
}) {
  const stats = summarizePartnerEndpoints(endpoints)

  const copyAll = async () => {
    const ok = await copyTextToClipboard(
      buildPartnerHubComparisonMarkdown(endpoints)
    )
    if (ok) onCopied?.("bảng đối chiếu")
  }

  const copyMissing = async () => {
    const ok = await copyTextToClipboard(buildMissingHubConfigText(endpoints))
    if (ok) onCopied?.("API chưa có Hub")
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      <Button
        type="button"
        variant={onlyMissing ? "secondary" : "outline"}
        size="sm"
        className="h-9 gap-1.5"
        onClick={() => onOnlyMissingChange(!onlyMissing)}
      >
        <AlertTriangle className="size-3.5" aria-hidden />
        Chưa proxy
        {stats.missing > 0 ? (
          <Badge variant="secondary" className="h-5 px-1.5 text-[10px]">
            {stats.missing}
          </Badge>
        ) : null}
      </Button>
      <Button
        type="button"
        variant="outline"
        size="sm"
        className="h-9 gap-1.5"
        onClick={() => void copyAll()}
      >
        <Copy className="size-3.5" aria-hidden />
        Copy đối chiếu
      </Button>
      <Button
        type="button"
        variant="outline"
        size="sm"
        className="h-9 gap-1.5"
        disabled={stats.missing === 0}
        onClick={() => void copyMissing()}
      >
        <Copy className="size-3.5" aria-hidden />
        Copy thiếu Hub
      </Button>
    </div>
  )
}

export function HanetPartnerApiTable({
  endpoints,
  tableScope,
  onCopied,
}: {
  endpoints: readonly HanetPartnerEndpoint[]
  tableScope: string
  onCopied?: (label: string) => void
}) {
  const [onlyMissing, setOnlyMissing] = useState(false)
  const columns = useHanetPartnerApiColumns()
  const allRows = useMemo(() => toTableRows(endpoints), [endpoints])
  const data = useMemo(
    () =>
      onlyMissing ? allRows.filter((row) => !row.hubConfigured) : allRows,
    [allRows, onlyMissing]
  )

  return (
    <AdminDataTable<HanetPartnerApiTableRow>
      tableScope={tableScope}
      data={data}
      columns={columns}
      getRowId={(row) => row.rowId}
      emptyLabel={
        onlyMissing
          ? "Tất cả endpoint trên trang này đã có Hub proxy."
          : "Không có endpoint."
      }
      globalFilterPlaceholder="Tìm theo nhóm, path HANET hoặc Hub…"
      globalFilterLabel="Tìm kiếm"
      getGlobalFilterText={(row) =>
        [
          row.group,
          row.partnerMethod,
          row.partnerPath,
          row.hubMethod,
          row.hubPath,
          row.hubConfigured ? "đã proxy" : "chưa proxy",
        ]
          .filter(Boolean)
          .join(" ")
      }
      filterToolbarExtra={
        <HanetPartnerApiCopyToolbar
          endpoints={endpoints}
          onlyMissing={onlyMissing}
          onOnlyMissingChange={setOnlyMissing}
          onCopied={onCopied}
        />
      }
      clientPagination={{
        initialPageSize: 10,
        pageSizeOptions: [10, 20, 50],
        itemLabel: "endpoint",
      }}
      footer={
        <p className="text-sm text-muted-foreground">
          <code className="text-xs">{HANET_PARTNER_API_BASE}</code>
          <span className="mx-1.5">·</span>
          {onlyMissing
            ? `Đang lọc ${data.length} endpoint chưa có Hub`
            : `${endpoints.length} endpoint · copy từng dòng hoặc dùng «Copy đối chiếu»`}
        </p>
      }
    />
  )
}

export { summarizePartnerEndpoints }

src/modules/hanet/_component/hanet-perso.content:
"use client"

import { useEffect, useMemo, useState } from "react"
import { FolderOpen, Loader2, Users } from "lucide-react"
import { Button } from "@ui/components/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@ui/components/dialog"
import {
  DataTableUserSearchFilter,
} from "@ui/components/data-table"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import { Textarea } from "@ui/components/textarea"
import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { api } from "@workspace/admin-app/lib/api"
import {
  createHanetUserSearchHandlers,
  fetchLocalAvatarAsFile,
  isNumericUserId,
  pickHanetAliasId,
} from "@workspace/admin-app/lib/hanet-user-pick"
import { StorageImagePickerDialog } from "@workspace/admin-app/lib/storage-image-picker-dialog"
import {
  getHanetPersonActionMeta,
  type HanetPersonActionId,
} from "@workspace/admin-app/lib/hanet-person-api-actions"
import type { HanetPersonRow } from "./hanet-persons-table"

function readFileAsBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(String(reader.result ?? ""))
    reader.onerror = () => reject(reader.error)
    reader.readAsDataURL(file)
  })
}

function parseAliasIds(raw: string): string[] {
  return raw
    .split(/[\n,;]+/)
    .map((item) => item.trim())
    .filter(Boolean)
}

function parseExtraFields(raw: string): Record<string, string> {
  const trimmed = raw.trim()
  if (!trimmed) return {}
  try {
    const parsed = JSON.parse(trimmed) as Record<string, unknown>
    const out: Record<string, string> = {}
    for (const [key, value] of Object.entries(parsed)) {
      if (value == null) continue
      out[key] = String(value)
    }
    return out
  } catch {
    return {}
  }
}

export function HanetPersonActionDialog({
  open,
  actionId,
  placeId,
  person,
  onClose,
  onSuccess,
}: {
  open: boolean
  actionId: HanetPersonActionId | null
  placeId: string
  person: HanetPersonRow | null
  onClose: () => void
  onSuccess?: () => void
}) {
  const meta = actionId ? getHanetPersonActionMeta(actionId) : null
  const [personId, setPersonId] = useState("")
  const [aliasId, setAliasId] = useState("")
  const [name, setName] = useState("")
  const [aliasIdsText, setAliasIdsText] = useState("")
  const [extraJson, setExtraJson] = useState("")
  const [file, setFile] = useState<File | null>(null)
  const [selectedUserId, setSelectedUserId] = useState<string | undefined>()
  const [loadingUser, setLoadingUser] = useState(false)
  const [avatarSkippedHint, setAvatarSkippedHint] = useState<string | null>(
    null,
  )
  const [storagePickerOpen, setStoragePickerOpen] = useState(false)

  const userSearchHandlers = useMemo(() => createHanetUserSearchHandlers(), [])

  useEffect(() => {
    if (!open || !actionId) return
    setPersonId(person?.personId ?? "")
    setAliasId(person?.aliasId ?? "")
    setName(person?.displayName ?? "")
    setAliasIdsText(person?.aliasId ?? "")
    setExtraJson("")
    setFile(null)
    setSelectedUserId(undefined)
    setLoadingUser(false)
    setAvatarSkippedHint(null)
    setStoragePickerOpen(false)
  }, [open, actionId, person])

  useEffect(() => {
    if (actionId !== "register" || !isNumericUserId(selectedUserId)) return
    let cancelled = false
    setLoadingUser(true)
    void api.users
      .get(selectedUserId)
      .then(async (user) => {
        if (cancelled) return
        setName(user.fullName?.trim() || "")
        setAliasId(pickHanetAliasId(user))
        const rawAvatar = user.avatar?.trim() ?? ""
        const avatarFile = rawAvatar
          ? await fetchLocalAvatarAsFile(rawAvatar)
          : null
        if (avatarFile) {
          setFile(avatarFile)
          setAvatarSkippedHint(null)
        } else if (rawAvatar) {
          setFile(null)
          setAvatarSkippedHint(
            "Avatar user không tải được (Google/WebP/URL ngoài) — chọn file hoặc bấm Kho.",
          )
        } else {
          setFile(null)
          setAvatarSkippedHint(
            "User chưa có avatar — chọn file JPEG/PNG hoặc bấm Kho.",
          )
        }
      })
      .catch(() => {
        if (!cancelled) return
      })
      .finally(() => {
        if (!cancelled) setLoadingUser(false)
      })
    return () => {
      cancelled = true
    }
  }, [actionId, selectedUserId])

  const mutation = useAdminMutation({
    mutationKey: ["hanet", "person-action", actionId, person?.personId],
    mutationFn: async () => {
      if (!actionId) throw new Error("Thiếu thao tác")
      const pid = personId.trim()
      const alias = aliasId.trim()
      const extra = parseExtraFields(extraJson)
      const body = {
        placeId,
        ...extra,
        ...(pid ? { personId: pid } : {}),
        ...(alias ? { aliasId: alias } : {}),
        ...(name.trim() ? { name: name.trim() } : {}),
      }

      switch (actionId) {
        case "register": {
          if (!name.trim()) throw new Error("Thiếu tên")
          if (!alias) throw new Error("Thiếu aliasID")
          if (!file) {
            throw new Error(
              "Chọn file ảnh JPEG/PNG — HANET register yêu cầu multipart file",
            )
          }
          return api.hanet.registerPerson({
            placeId,
            name: name.trim(),
            aliasId: alias,
            fileBase64: await readFileAsBase64(file),
            personType:
              extra.personType != null ? Number(extra.personType) : 1,
          })
        }
        case "update":
          return api.hanet.updatePerson(body)
        case "update-info":
          return api.hanet.updatePersonInfo(body)
        case "update-alias-id":
          return api.hanet.updatePersonAliasId(body)
        case "remove":
          return api.hanet.removePerson({ personId: pid })
        case "remove-by-place":
          return api.hanet.removePersonByPlace({ placeId, aliasId: alias })
        case "remove-by-id":
          return api.hanet.removePersonById({ personId: pid })
        case "remove-by-alias-ids": {
          const aliasIds = parseAliasIds(aliasIdsText)
          if (!aliasIds.length) throw new Error("Nhập ít nhất một aliasID")
          return api.hanet.removePersonsByAliasIds({ placeId, aliasIds })
        }
        case "remove-all-in-place":
          return api.hanet.removeAllPersonsInPlace(placeId)
        default:
          throw new Error("Thao tác không hỗ trợ trong dialog")
      }
    },
    toast: {
      loading: meta ? `Đang gọi ${meta.label}…` : "Đang gọi HANET…",
      success: meta ? `Đã gọi ${meta.label} thành công` : "Thành công",
      error: (err) =>
        err instanceof Error ? err.message : "Gọi API person HANET thất bại",
    },
    onSuccess: () => {
      onSuccess?.()
      onClose()
    },
  })

  return (
    <>
      <Dialog
        open={open}
        onOpenChange={(next) => {
          if (!next) onClose()
        }}
      >
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Users className="size-5 text-primary" />
            Person API HANET
          </DialogTitle>
          <DialogDescription>
            {meta?.label ?? "—"} · placeID{" "}
            <code className="text-xs">{placeId || "—"}</code>
          </DialogDescription>
        </DialogHeader>

        {meta ? (
          <div className="space-y-3 text-sm">
            <div className="rounded-md border border-border/70 bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
              <p>
                Partner:{" "}
                <code className="text-foreground">{meta.partnerPath}</code>
              </p>
              <p className="mt-1">
                Hub:{" "}
                <code className="text-foreground">
                  {meta.hubMethod} {meta.hubPath}
                </code>
              </p>
            </div>

            {actionId === "register" ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-reg-user">Người dùng</Label>
                <DataTableUserSearchFilter
                  controlId="hanet-person-reg-user"
                  value={selectedUserId ?? ""}
                  onChange={setSelectedUserId}
                  placeholder="Tìm tên, email hoặc ID…"
                  handlers={userSearchHandlers}
                />
                <p className="text-xs text-muted-foreground">
                  Chọn user để điền <strong>Tên</strong>,{" "}
                  <strong>aliasID</strong> và ảnh từ avatar (nếu lưu trên
                  server).
                </p>
                {loadingUser ? (
                  <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
                    <Loader2 className="size-3.5 animate-spin" />
                    Đang tải thông tin user…
                  </p>
                ) : null}
                {avatarSkippedHint ? (
                  <p className="text-xs text-amber-700 dark:text-amber-400">
                    {avatarSkippedHint}
                  </p>
                ) : null}
              </div>
            ) : null}

            {meta.needsPersonId ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-id">personID</Label>
                <Input
                  id="hanet-person-id"
                  value={personId}
                  onChange={(e) => setPersonId(e.target.value)}
                  className="h-9 font-mono text-xs"
                />
              </div>
            ) : null}

            {meta.needsAliasId ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-alias">aliasID</Label>
                <Input
                  id="hanet-person-alias"
                  value={aliasId}
                  onChange={(e) => setAliasId(e.target.value)}
                  className="h-9"
                />
              </div>
            ) : null}

            {meta.needsName ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-name">Tên</Label>
                <Input
                  id="hanet-person-name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="h-9"
                />
              </div>
            ) : null}

            {meta.needsFile ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-file">
                  Ảnh khuôn mặt (JPEG/PNG) — bắt buộc
                </Label>
                <div className="flex gap-2">
                  <Input
                    id="hanet-person-file"
                    type="file"
                    accept="image/jpeg,image/png,.jpg,.jpeg,.png"
                    className="h-9 min-w-0 flex-1 py-1"
                    onChange={(e) => {
                      setFile(e.target.files?.[0] ?? null)
                      setAvatarSkippedHint(null)
                    }}
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-9 shrink-0 gap-1.5"
                    onClick={() => setStoragePickerOpen(true)}
                  >
                    <FolderOpen className="size-3.5" />
                    Kho
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  HANET <code>/person/register</code> yêu cầu upload file. Hoặc
                  dùng <strong>registerByUrl</strong> nếu chỉ có URL public.
                </p>
              </div>
            ) : null}

            {meta.needsAliasIds ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-alias-ids">
                  aliasIDs (mỗi dòng hoặc dấu phẩy)
                </Label>
                <Textarea
                  id="hanet-person-alias-ids"
                  value={aliasIdsText}
                  onChange={(e) => setAliasIdsText(e.target.value)}
                  rows={4}
                  className="font-mono text-xs"
                />
              </div>
            ) : null}

            {meta.kind === "write" &&
            actionId !== "register" &&
            actionId !== "remove-by-alias-ids" ? (
              <div className="grid gap-1.5">
                <Label htmlFor="hanet-person-extra">
                  Field bổ sung (JSON, tùy chọn)
                </Label>
                <Textarea
                  id="hanet-person-extra"
                  value={extraJson}
                  onChange={(e) => setExtraJson(e.target.value)}
                  placeholder='{"personType":1,"name":"Tên mới"}'
                  rows={3}
                  className="font-mono text-xs"
                />
              </div>
            ) : null}

            {meta.dangerous ? (
              <p className="text-xs text-destructive">
                Thao tác xóa trên HANET — không hoàn tác.
              </p>
            ) : null}
          </div>
        ) : null}

        <DialogFooter>
          <Button type="button" variant="outline" onClick={onClose}>
            Hủy
          </Button>
          <Button
            type="button"
            variant={meta?.dangerous ? "destructive" : "default"}
            disabled={
              !meta ||
              !placeId ||
              mutation.isPending ||
              loadingUser ||
              (meta.needsFile && !file) ||
              (meta.needsName && !name.trim()) ||
              (meta.needsAliasId && !aliasId.trim())
            }
            onClick={() => mutation.mutate()}
          >
            {mutation.isPending ? (
              <Loader2 className="size-4 animate-spin" />
            ) : null}
            {meta?.dangerous ? "Xóa trên HANET" : "Gọi API"}
          </Button>
        </DialogFooter>
      </DialogContent>
      </Dialog>

      <StorageImagePickerDialog
        open={storagePickerOpen}
        multiSelect={false}
        title="Chọn ảnh khuôn mặt (JPG/PNG)"
        onOpenChange={setStoragePickerOpen}
        onSelect={async (urls) => {
          const next = urls[0]?.trim()
          if (next) {
            const picked = await fetchLocalAvatarAsFile(next)
            if (picked) {
              setFile(picked)
              setAvatarSkippedHint(null)
            }
          }
          setStoragePickerOpen(false)
        }}
      />
    </>
  )
}

"use client"

import { useMemo, useState } from "react"
import { ChevronDown, Loader2, Search } from "lucide-react"
import { useQuery } from "@tanstack/react-query"
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert"
import { Badge } from "@ui/components/badge"
import { Button } from "@ui/components/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@ui/components/collapsible"
import { DataTableToolbarField } from "@ui/components/data-table"
import {
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "@ui/components/field"
import { Input } from "@ui/components/input"
import {
  SelectPicker,
  type SelectPickerOption,
} from "@ui/components/pickers"
import { cn } from "@ui/lib/utils"
import { api } from "@workspace/admin-app/lib/api"
import {
  getHanetPersonActionMeta,
  HANET_PERSON_LOOKUP_ACTIONS,
  type HanetPersonActionId,
} from "@workspace/admin-app/lib/hanet-person-api-actions"
import {
  parseHanetPersonLookupResult,
  type HanetPersonParsedRow,
} from "@workspace/admin-app/lib/hanet-person-parse"
import { HanetPlaceSelect } from "@workspace/admin-app/modules/hanet/_component/hanet-place-select"
import { HanetJsonPreview } from "./hanet-json-preview"
import { HanetPersonsTable } from "./hanet-persons-table"

type LookupMode = HanetPersonActionId

function lookupQueryKey(
  mode: LookupMode,
  placeId: string,
  aliasId: string,
  personId: string,
) {
  return ["hanet", "person-lookup", mode, placeId, aliasId, personId] as const
}

async function fetchPersonLookup(
  mode: LookupMode,
  placeId: string,
  aliasId: string,
  personId: string,
): Promise<unknown> {
  const alias = aliasId.trim()
  const pid = personId.trim()
  switch (mode) {
    case "lookup-by-alias-all":
      return api.hanet.listPersonByAliasAll(alias)
    case "lookup-by-alias":
      return api.hanet.listPersonByAlias({
        aliasId: alias,
        placeId: placeId || undefined,
      })
    case "lookup-user-by-alias":
      return api.hanet.getPersonUserByAlias({
        aliasId: alias,
        placeId: placeId || undefined,
      })
    case "lookup-user-by-id":
      return api.hanet.getPersonUserById({
        personId: pid,
        placeId: placeId || undefined,
      })
    default:
      throw new Error("Loại tra cứu không hỗ trợ")
  }
}

function validateLookup(
  mode: LookupMode,
  placeId: string,
  aliasId: string,
  personId: string,
): string | null {
  const meta = getHanetPersonActionMeta(mode)
  if (meta.needsPlace && !placeId.trim()) {
    return "Chọn địa điểm HANET trước khi tra cứu."
  }
  if (meta.needsAliasId && !aliasId.trim()) {
    return "Nhập aliasID (email hoặc mã định danh)."
  }
  if (meta.needsPersonId && !personId.trim()) {
    return "Nhập personID."
  }
  return null
}

export function HanetPersonLookupPanel({
  placeId,
  selectedPlaceId,
  onPlaceChange,
  defaultPlaceId,
}: {
  placeId: string
  selectedPlaceId: string
  onPlaceChange: (placeId: string) => void
  defaultPlaceId?: string | null
}) {
  const [mode, setMode] = useState<LookupMode>("lookup-by-alias")
  const [aliasId, setAliasId] = useState("")
  const [personId, setPersonId] = useState("")
  const [fetchEnabled, setFetchEnabled] = useState(false)
  const [validationError, setValidationError] = useState<string | null>(null)
  const [rawOpen, setRawOpen] = useState(false)

  const modeMeta = getHanetPersonActionMeta(mode)

  const lookupOptions = useMemo<SelectPickerOption[]>(
    () =>
      HANET_PERSON_LOOKUP_ACTIONS.map((action) => ({
        value: action.id,
        label: action.label,
        render: () => (
          <span className="flex min-w-0 flex-col items-start gap-0.5 text-left">
            <span className="font-medium">{action.label}</span>
            <span className="text-xs font-normal text-muted-foreground">
              {action.hint}
            </span>
          </span>
        ),
      })),
    [],
  )

  const lookupQuery = useQuery({
    queryKey: lookupQueryKey(mode, placeId, aliasId, personId),
    queryFn: () => fetchPersonLookup(mode, placeId, aliasId, personId),
    enabled:
      fetchEnabled &&
      !validateLookup(mode, placeId, aliasId, personId),
  })

  const parsed = useMemo(
    () =>
      lookupQuery.data != null
        ? parseHanetPersonLookupResult(lookupQuery.data)
        : { items: [] as HanetPersonParsedRow[], total: undefined },
    [lookupQuery.data],
  )

  const runLookup = () => {
    const err = validateLookup(mode, placeId, aliasId, personId)
    setValidationError(err)
    if (err) return
    setFetchEnabled(true)
    if (fetchEnabled) {
      void lookupQuery.refetch()
    }
  }

  const summaryLine =
    fetchEnabled && lookupQuery.isSuccess && !lookupQuery.isFetching
      ? parsed.items.length > 0
        ? `Tìm thấy ${parsed.total ?? parsed.items.length} kết quả · ${modeMeta.label} · placeID ${placeId || "—"}`
        : `Không có person khớp · ${modeMeta.label}`
      : null

  const emptyLabel = !fetchEnabled
    ? "Chọn loại tra cứu, nhập thông tin và bấm Tra cứu."
    : lookupQuery.error
      ? "Không tra cứu được dữ liệu."
      : parsed.items.length === 0
        ? "Không tìm thấy person phù hợp."
        : ""

  return (
    <div className="space-y-3">
      {lookupQuery.error ? (
        <Alert variant="destructive">
          <AlertTitle>Tra cứu thất bại</AlertTitle>
          <AlertDescription>
            {lookupQuery.error instanceof Error
              ? lookupQuery.error.message
              : "Gọi API person HANET thất bại"}
          </AlertDescription>
        </Alert>
      ) : null}

      {validationError ? (
        <Alert variant="destructive">
          <AlertTitle>Thiếu thông tin tra cứu</AlertTitle>
          <AlertDescription>{validationError}</AlertDescription>
        </Alert>
      ) : null}

      <FieldSet variant="section">
        <FieldSectionLegend
          title="Tra cứu person"
          description={modeMeta.hint}
        />
        <FieldSetContent className="space-y-2 p-3">
          <div className="flex flex-wrap items-end gap-2">
            <DataTableToolbarField
              label="Loại tra cứu"
              className="w-full min-w-[10rem] flex-1 sm:max-w-[11rem]"
            >
              <SelectPicker
                value={mode}
                onChange={(next) => {
                  if (typeof next !== "string" || !next) return
                  setMode(next as LookupMode)
                  setFetchEnabled(false)
                  setValidationError(null)
                }}
                options={lookupOptions}
                placeholder="Chọn loại"
                size="sm"
                className="w-full"
              />
            </DataTableToolbarField>

            {modeMeta.needsPlace ? (
              <HanetPlaceSelect
                layout="stacked"
                value={selectedPlaceId}
                onChange={onPlaceChange}
                defaultPlaceId={defaultPlaceId}
                className="w-full min-w-[10rem] flex-1 sm:max-w-[11rem]"
              />
            ) : null}

            {modeMeta.needsAliasId ? (
              <DataTableToolbarField
                label="aliasID"
                className="w-full min-w-[10rem] flex-1 sm:max-w-xs"
              >
                <Input
                  value={aliasId}
                  onChange={(e) => setAliasId(e.target.value)}
                  placeholder="email@…"
                  className="h-8 text-sm"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") runLookup()
                  }}
                />
              </DataTableToolbarField>
            ) : null}

            {modeMeta.needsPersonId ? (
              <DataTableToolbarField
                label="personID"
                className="w-full min-w-[9rem] flex-1 sm:max-w-[10rem]"
              >
                <Input
                  value={personId}
                  onChange={(e) => setPersonId(e.target.value)}
                  placeholder="ID HANET"
                  className="h-8 font-mono text-xs"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") runLookup()
                  }}
                />
              </DataTableToolbarField>
            ) : null}

            <Button
              type="button"
              size="sm"
              className="h-8 shrink-0 gap-1.5"
              disabled={lookupQuery.isFetching}
              onClick={runLookup}
            >
              {lookupQuery.isFetching ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <Search className="size-4" />
              )}
              Tra cứu
            </Button>
          </div>

          <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            <Badge variant="outline" className="font-mono text-[10px]">
              {modeMeta.hubMethod}
            </Badge>
            <code className="truncate text-[11px]">{modeMeta.hubPath}</code>
            <span className="hidden text-border sm:inline">·</span>
            <code className="truncate text-[11px] text-muted-foreground/80">
              Partner {modeMeta.partnerPath}
            </code>
          </div>
        </FieldSetContent>
      </FieldSet>

      {summaryLine ? (
        <p className="text-sm text-muted-foreground">{summaryLine}</p>
      ) : null}

      {fetchEnabled ? (
        <HanetPersonsTable
          data={parsed.items}
          isLoading={lookupQuery.isFetching}
          emptyLabel={emptyLabel}
          pageIndex={0}
          pageSize={parsed.items.length || 20}
          total={parsed.total ?? parsed.items.length}
          onPageIndexChange={() => {}}
          onPageSizeChange={() => {}}
          compact
        />
      ) : null}

      {fetchEnabled && lookupQuery.isSuccess && lookupQuery.data != null ? (
        <Collapsible open={rawOpen} onOpenChange={setRawOpen}>
          <CollapsibleTrigger
            className={cn(
              "inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-md px-2 text-xs text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground",
              rawOpen && "text-foreground",
            )}
          >
            <ChevronDown
              className={cn(
                "size-3.5 transition-transform",
                rawOpen && "rotate-180",
              )}
            />
            Phản hồi thô từ HANET
          </CollapsibleTrigger>
          <CollapsibleContent className="pt-2">
            <HanetJsonPreview data={lookupQuery.data} />
          </CollapsibleContent>
        </Collapsible>
      ) : null}
    </div>
  )
}

"use client"

import {
  Camera,
  Copy,
  ExternalLink,
  Pencil,
  ScanFace,
  Trash2,
  UserCog,
} from "lucide-react"
import {
  DataTableRowActionsMenu,
  TABLE_ACTIONS_COLUMN_META,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import { HANET_FACE_ACTIONS, type HanetFaceActionId } from "@workspace/admin-app/lib/hanet-face-actions"
import {
  HANET_PERSON_ROW_ACTIONS,
  type HanetPersonActionId,
} from "@workspace/admin-app/lib/hanet-person-api-actions"
import type { HanetPersonRow } from "./hanet-persons-table"

export type HanetPersonRowActionsProps = {
  person: HanetPersonRow
  onFaceAction?: (actionId: HanetFaceActionId, person: HanetPersonRow) => void
  onPersonAction?: (actionId: HanetPersonActionId, person: HanetPersonRow) => void
}

function resolveAvatarUrl(person: HanetPersonRow): string {
  const avatar = String(person.avatar ?? "").trim()
  if (!avatar || avatar.startsWith("hanet:person:")) return ""
  return avatar
}

function personActionIcon(actionId: HanetPersonActionId) {
  if (actionId.startsWith("remove")) return <Trash2 />
  if (actionId.startsWith("update")) return <Pencil />
  return <UserCog />
}

export function HanetPersonRowActions({
  person,
  onFaceAction,
  onPersonAction,
}: HanetPersonRowActionsProps) {
  const avatarUrl = resolveAvatarUrl(person)
  const actions: DataTableRowActionItem[] = []

  if (avatarUrl) {
    actions.push({
      key: "open-avatar",
      label: "Mở ảnh đại diện",
      hint: "Xem avatar gốc trên HANET",
      onClick: () => {
        window.open(avatarUrl, "_blank", "noopener,noreferrer")
      },
      icon: <ExternalLink />,
      group: "primary",
    })
  }

  if (onPersonAction) {
    for (const personAction of HANET_PERSON_ROW_ACTIONS) {
      actions.push({
        key: `person-${personAction.id}`,
        label: personAction.label,
        hint: personAction.hint,
        onClick: () => onPersonAction(personAction.id, person),
        icon: personActionIcon(personAction.id),
        group: personAction.dangerous ? "danger" : "status",
        ...(personAction.dangerous ? { menuVariant: "destructive" as const } : {}),
      })
    }
  }

  if (onFaceAction) {
    for (const faceAction of HANET_FACE_ACTIONS) {
      actions.push({
        key: `face-${faceAction.id}`,
        label: faceAction.label,
        hint: faceAction.hint,
        onClick: () => onFaceAction(faceAction.id, person),
        icon:
          faceAction.id === "take-picture" ? (
            <Camera />
          ) : (
            <ScanFace />
          ),
        group: "status",
      })
    }
  }

  if (person.personId) {
    actions.push({
      key: "copy-person-id",
      label: "Sao chép personID",
      hint: person.personId,
      onClick: () => {
        void navigator.clipboard.writeText(person.personId)
      },
      icon: <Copy />,
      group: "primary",
    })
  }

  return (
    <DataTableRowActionsMenu
      actions={actions}
      autoConfirmDangerousActions={false}
      triggerLabel={`Thao tác ${person.displayName || person.personId}`}
      groups={{
        primary: { label: "Xem / sao chép", sublabel: false },
        status: { label: "Person / Face API HANET", sublabel: true },
        danger: { label: "Xóa trên HANET", sublabel: true },
      }}
    />
  )
}

export const hanetPersonActionsColumnMeta = {
  ...TABLE_ACTIONS_COLUMN_META,
  className: `${TABLE_ACTIONS_COLUMN_META.className} sticky right-0 z-[10]`,
}

"use client"

import { useMemo, type ReactNode } from "react"
import type { ColumnDef } from "@tanstack/react-table"
import { User } from "lucide-react"
import { AdminDataTable, defineDataTableActionsColumn } from "@ui/components/data-table"
import { FieldCopyButton } from "@ui/components/field"
import { cn } from "@ui/lib/utils"
import type { HanetPersonListPage } from "@workspace/api-client"
import type { HanetFaceActionId } from "@workspace/admin-app/lib/hanet-face-actions"
import type { HanetPersonActionId } from "@workspace/admin-app/lib/hanet-person-api-actions"
import {
  HanetPersonRowActions,
  hanetPersonActionsColumnMeta,
} from "./hanet-person-row-actions"

/** Khớp cột preview file-storage / check-in HANET */
const HANET_PERSON_PREVIEW_COLUMN_CLASS =
  "w-[50px] min-w-[50px] max-w-[50px]"

const PERSON_PREVIEW_FRAME_CLASS =
  "flex aspect-square w-full items-center justify-center overflow-hidden rounded-md border border-border bg-muted"

export type HanetPersonRow = HanetPersonListPage["items"][number]

export type HanetPersonsTableProps = {
  data: HanetPersonRow[]
  isLoading?: boolean
  emptyLabel?: string
  filterToolbarExtra?: ReactNode
  pageIndex: number
  pageSize: number
  total?: number
  hanetTotal?: number
  listLimited?: boolean
  onPageIndexChange: (pageIndex: number) => void
  onPageSizeChange: (pageSize: number) => void
  onFaceAction?: (actionId: HanetFaceActionId, person: HanetPersonRow) => void
  onPersonAction?: (actionId: HanetPersonActionId, person: HanetPersonRow) => void
  /** Tra cứu: ẩn phân trang và cột thao tác. */
  compact?: boolean
}

export function HanetPersonsTable({
  data,
  isLoading = false,
  emptyLabel = "Không có person cho địa điểm này.",
  filterToolbarExtra,
  pageIndex,
  pageSize,
  total = 0,
  hanetTotal,
  listLimited = false,
  onPageIndexChange,
  onPageSizeChange,
  onFaceAction,
  onPersonAction,
  compact = false,
}: HanetPersonsTableProps) {
  const resolvedTotal =
    total != null && Number.isFinite(total) && total > 0
      ? total
      : data.length < pageSize
        ? pageIndex * pageSize + data.length
        : (pageIndex + 1) * pageSize

  const columns = useMemo<ColumnDef<HanetPersonRow>[]>(
    () => [
      {
        accessorKey: "avatar",
        header: "Ảnh",
        enableColumnFilter: false,
        enableHiding: false,
        size: 50,
        minSize: 50,
        meta: {
          disableCellLineClamp: true,
          className: HANET_PERSON_PREVIEW_COLUMN_CLASS,
        },
        cell: ({ getValue }) => {
          const avatar = String(getValue() ?? "").trim()
          if (!avatar || avatar.startsWith("hanet:person:")) {
            return (
              <div
                className={cn(
                  PERSON_PREVIEW_FRAME_CLASS,
                  "text-sm text-muted-foreground",
                )}
              >
                —
              </div>
            )
          }
          return (
            <a
              href={avatar}
              target="_blank"
              rel="noopener noreferrer"
              className={cn(
                PERSON_PREVIEW_FRAME_CLASS,
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              )}
              title="Mở ảnh"
            >
              <img
                src={avatar}
                alt=""
                className="size-full object-cover"
                loading="lazy"
                decoding="async"
              />
            </a>
          )
        },
      },
      {
        accessorKey: "displayName",
        header: "Tên",
        enableColumnFilter: false,
        size: 220,
        cell: ({ getValue }) => {
          const name = String(getValue() ?? "").trim() || "—"
          return (
            <div className="flex min-w-0 items-start gap-2 py-0.5">
              <User
                className="mt-0.5 size-3.5 shrink-0 text-muted-foreground"
                aria-hidden
              />
              <span className="min-w-0 whitespace-normal break-words font-medium leading-snug">
                {name}
              </span>
            </div>
          )
        },
      },
      {
        accessorKey: "personId",
        header: "personID",
        enableColumnFilter: false,
        size: 160,
        cell: ({ getValue }) => {
          const personId = String(getValue() ?? "").trim()
          if (!personId) return "—"
          return (
            <div className="flex items-start gap-2 py-0.5">
              <code className="text-xs font-medium break-all leading-snug">
                {personId}
              </code>
              <FieldCopyButton text={personId} />
            </div>
          )
        },
      },
      {
        accessorKey: "aliasId",
        header: "aliasID",
        enableColumnFilter: false,
        size: 120,
        cell: ({ getValue }) => {
          const aliasId = String(getValue() ?? "").trim()
          if (!aliasId) return "—"
          return (
            <div className="flex items-start gap-2 py-0.5">
              <span className="text-sm whitespace-normal break-all leading-snug">
                {aliasId}
              </span>
              <FieldCopyButton text={aliasId} />
            </div>
          )
        },
      },
      ...(compact
        ? []
        : [
            defineDataTableActionsColumn<HanetPersonRow>({
              columnMeta: hanetPersonActionsColumnMeta,
              cell: ({ row }) => (
                <HanetPersonRowActions
                  person={row.original}
                  onFaceAction={onFaceAction}
                  onPersonAction={onPersonAction}
                />
              ),
            }),
          ]),
    ],
    [compact, onFaceAction, onPersonAction],
  )

  return (
    <AdminDataTable<HanetPersonRow>
      tableScope="hanet-persons"
      data={data}
      columns={columns}
      getRowId={(row) => row.personId}
      isLoading={isLoading}
      emptyLabel={emptyLabel}
      globalFilterPlaceholder="Tìm theo tên, personID hoặc aliasID…"
      globalFilterLabel="Tìm kiếm"
      getGlobalFilterText={(row) =>
        [row.displayName, row.personId, row.aliasId].filter(Boolean).join(" ")
      }
      filterToolbarExtra={filterToolbarExtra}
      pagination={
        compact
          ? undefined
          : {
              page: pageIndex + 1,
              pageSize,
              total: resolvedTotal,
              currentPageRowCount: data.length,
              appliedPage: pageIndex + 1,
              appliedPageSize: pageSize,
              onPageChange: (nextPage) =>
                onPageIndexChange(Math.max(0, nextPage - 1)),
              onPageSizeChange: (nextSize) => {
                onPageSizeChange(nextSize)
                onPageIndexChange(0)
              },
              itemLabel: "người",
              isLoading,
              pageSizeOptions: [20, 50, 100],
            }
      }
      footer={
        compact ? (
          <p className="text-sm text-muted-foreground">
            {isLoading
              ? "Đang tải…"
              : `Hiển thị ${data.length} kết quả tra cứu`}
          </p>
        ) : (
          <p className="text-sm text-muted-foreground">
            {isLoading
              ? "Đang tải…"
              : listLimited && hanetTotal != null && hanetTotal > resolvedTotal
                ? `Hiển thị ${resolvedTotal} / ${hanetTotal} người trên HANET (Partner API chỉ trả ~50/lần) · trang ${pageIndex + 1}`
                : `Tổng ${resolvedTotal} người · trang ${pageIndex + 1}`}
          </p>
        )
      }
    />
  )
}

