"use client"

import { Loader2, Trash2 } from "lucide-react"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@ui/components/alert-dialog"
import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { api } from "@workspace/admin-app/lib/api"
import type { HanetPlaceOption } from "@workspace/admin-app/lib/hanet-place-parse"

export function HanetPlaceDeleteDialog({
  open,
  place,
  onClose,
  onSuccess,
}: {
  open: boolean
  place: HanetPlaceOption | null
  onClose: () => void
  onSuccess: () => void
}) {
  const mutation = useAdminMutation({
    mutationKey: ["hanet", "places", "remove"],
    mutationFn: async () => {
      if (!place?.placeId) throw new Error("Thiếu placeID")
      return api.hanet.removePlace(place.placeId)
    },
    toast: {
      loading: "Đang xóa địa điểm…",
      success: "Đã xóa địa điểm HANET",
      error: (err) =>
        err instanceof Error
          ? err.message
          : "Không xóa được — place có thể còn thiết bị/người (PLACE_NOT_EMPTY)",
    },
    onSuccess: () => {
      onSuccess()
      onClose()
    },
  })

  return (
    <AlertDialog
      open={open}
      onOpenChange={(next) => {
        if (!next) onClose()
      }}
    >
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle className="flex items-center justify-center gap-2 sm:justify-start">
            <Trash2 className="size-5 text-destructive" aria-hidden />
            Xóa địa điểm?
          </AlertDialogTitle>
          <AlertDialogDescription>
            Xóa vĩnh viễn{" "}
            <strong>{place?.name || place?.placeId}</strong> (
            <code className="text-xs">{place?.placeId}</code>) trên HANET và gỡ
            khỏi app partner. Thao tác không hoàn tác.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={mutation.isPending}>Hủy</AlertDialogCancel>
          <AlertDialogAction
            variant="destructive"
            disabled={mutation.isPending}
            onClick={() => mutation.mutate()}
          >
            {mutation.isPending ? (
              <Loader2 className="size-4 animate-spin" />
            ) : null}
            Xóa
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Loader2, MapPin } from "lucide-react"
import { Button } from "@ui/components/button"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@ui/components/dialog"
import { Input } from "@ui/components/input"
import { Label } from "@ui/components/label"
import { SelectPicker } from "@ui/components/pickers"
import { useAdminMutation } from "@ui/hooks/use-admin-mutation"
import { api } from "@workspace/admin-app/lib/api"
import {
  parseHanetPlaceDetail,
  type HanetPlaceOption,
} from "@workspace/admin-app/lib/hanet-place-parse"

const PLACE_TYPE_OPTIONS = [
  { value: "0", label: "Công ty" },
  { value: "1", label: "Gia đình" },
] as const

export function HanetPlaceFormDialog({
  open,
  place,
  onClose,
  onSuccess,
}: {
  open: boolean
  place: HanetPlaceOption | null
  onClose: () => void
  onSuccess: () => void
}) {
  const isEdit = Boolean(place?.placeId)
  const [placeName, setPlaceName] = useState("")
  const [address, setAddress] = useState("")
  const [placeType, setPlaceType] = useState("0")
  const [loadingDetail, setLoadingDetail] = useState(false)

  useEffect(() => {
    if (!open) return

    if (!place) {
      setPlaceName("")
      setAddress("")
      setPlaceType("0")
      return
    }

    setPlaceName(place.name)
    setAddress("")
    setPlaceType("0")
    setLoadingDetail(true)

    void api.hanet
      .getPlaceInfo(place.placeId)
      .then((data) => {
        const detail = parseHanetPlaceDetail(data)
        if (detail.placeName) setPlaceName(detail.placeName)
        if (detail.address) setAddress(detail.address)
        if (detail.type != null) setPlaceType(String(detail.type))
      })
      .catch(() => {
        // Giữ tên từ danh sách nếu getPlaceInfo lỗi.
      })
      .finally(() => setLoadingDetail(false))
  }, [open, place])

  const mutation = useAdminMutation({
    mutationKey: ["hanet", "places", isEdit ? "update" : "create"],
    mutationFn: async () => {
      const trimmedName = placeName.trim()
      if (!trimmedName) {
        throw new Error("Nhập tên địa điểm")
      }

      const type = Number.parseInt(placeType, 10)
      const addressValue = address.trim()

      if (isEdit && place) {
        return api.hanet.updatePlace({
          placeId: place.placeId,
          placeName: trimmedName,
          ...(addressValue ? { address: addressValue } : {}),
        })
      }

      return api.hanet.createPlace({
        placeName: trimmedName,
        ...(addressValue ? { address: addressValue } : {}),
        type: Number.isFinite(type) ? type : 0,
      })
    },
    toast: {
      loading: isEdit ? "Đang cập nhật địa điểm…" : "Đang tạo địa điểm…",
      success: isEdit ? "Đã cập nhật địa điểm HANET" : "Đã tạo địa điểm HANET",
      error: (err) =>
        err instanceof Error ? err.message : "Không lưu được địa điểm",
    },
    onSuccess: () => {
      onSuccess()
      onClose()
    },
  })

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) onClose()
      }}
    >
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MapPin className="size-5 shrink-0" aria-hidden />
            {isEdit ? "Sửa địa điểm" : "Thêm địa điểm"}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-1">
          {isEdit ? (
            <div className="space-y-1.5">
              <Label>placeID</Label>
              <Input value={place?.placeId ?? ""} readOnly disabled />
            </div>
          ) : null}

          <div className="space-y-1.5">
            <Label htmlFor="hanet-place-name">
              Tên địa điểm <span className="text-destructive">*</span>
            </Label>
            <Input
              id="hanet-place-name"
              value={placeName}
              onChange={(e) => setPlaceName(e.target.value)}
              placeholder="VD: HUB – Cơ sở Thủ Đức"
              autoFocus={!isEdit}
              disabled={loadingDetail || mutation.isPending}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="hanet-place-address">Địa chỉ</Label>
            <Input
              id="hanet-place-address"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              placeholder="Tùy chọn"
              disabled={loadingDetail || mutation.isPending}
            />
          </div>

          {!isEdit ? (
            <div className="space-y-1.5">
              <Label>Loại địa điểm</Label>
              <SelectPicker
                value={placeType}
                onChange={(value) =>
                  setPlaceType(typeof value === "string" ? value : "0")
                }
                options={PLACE_TYPE_OPTIONS.map((option) => ({
                  value: option.value,
                  label: option.label,
                }))}
                placeholder="Chọn loại"
                disabled={mutation.isPending}
                allowClear={false}
                className="w-full"
              />
            </div>
          ) : null}

          {loadingDetail ? (
            <p className="flex items-center gap-2 text-xs text-muted-foreground">
              <Loader2 className="size-3.5 animate-spin" />
              Đang tải chi tiết từ HANET…
            </p>
          ) : null}
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            disabled={mutation.isPending}
          >
            Hủy
          </Button>
          <Button
            type="button"
            onClick={() => mutation.mutate()}
            disabled={mutation.isPending || loadingDetail}
          >
            {mutation.isPending ? (
              <Loader2 className="size-4 animate-spin" />
            ) : null}
            {isEdit ? "Lưu thay đổi" : "Tạo địa điểm"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { Pencil, Trash2 } from "lucide-react"
import {
  DataTableRowActionsMenu,
  TABLE_ACTIONS_COLUMN_META,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import type { HanetPlaceOption } from "@workspace/admin-app/lib/hanet-place-parse"

export type HanetPlaceRowActionsProps = {
  place: HanetPlaceOption
  canWrite: boolean
  onEdit?: () => void
  onDelete?: () => void
}

export function HanetPlaceRowActions({
  place,
  canWrite,
  onEdit,
  onDelete,
}: HanetPlaceRowActionsProps) {
  const actions: DataTableRowActionItem[] = []

  if (canWrite && onEdit) {
    actions.push({
      key: "edit",
      label: "Sửa địa điểm",
      hint: "Cập nhật tên và địa chỉ trên HANET",
      onClick: onEdit,
      icon: <Pencil />,
      group: "primary",
    })
  }

  if (canWrite && onDelete) {
    actions.push({
      key: "delete",
      label: "Xóa địa điểm",
      hint: "Gỡ place khỏi HANET và app partner",
      onClick: onDelete,
      icon: <Trash2 />,
      group: "danger",
      menuVariant: "destructive",
    })
  }

  return (
    <DataTableRowActionsMenu
      actions={actions}
      autoConfirmDangerousActions={false}
      triggerLabel={`Thao tác địa điểm ${place.name || place.placeId}`}
      groups={{
        primary: { label: "Thao tác", sublabel: false },
        danger: { label: "Xóa", sublabel: true },
      }}
    />
  )
}

export const hanetPlaceActionsColumnMeta = {
  ...TABLE_ACTIONS_COLUMN_META,
  className: `${TABLE_ACTIONS_COLUMN_META.className} sticky right-0 z-[10]`,
}

"use client"

import { useEffect, useId, useMemo } from "react"
import { Loader2, RefreshCw } from "lucide-react"
import { Button } from "@ui/components/button"
import { DataTableToolbarField } from "@ui/components/data-table"
import {
  SelectPicker,
  type SelectPickerOption,
  type PickerSize,
} from "@ui/components/pickers"
import { cn } from "@ui/lib/utils"
import { useHanetPlacesQuery } from "./use-hanet-places-query"
import { HANET_ADMIN_PLACE_STORAGE_KEY } from "@workspace/admin-app/lib/hanet-place-storage"

const STORAGE_KEY = HANET_ADMIN_PLACE_STORAGE_KEY

export function useHanetSelectedPlaceId(defaultPlaceId?: string | null) {
  const placesQuery = useHanetPlacesQuery(Boolean(defaultPlaceId) || true)

  const places = useMemo(() => placesQuery.data ?? [], [placesQuery.data])

  const resolvedDefault = useMemo(() => {
    if (defaultPlaceId?.trim()) return defaultPlaceId.trim()
    if (typeof window !== "undefined") {
      const saved = window.localStorage.getItem(STORAGE_KEY)?.trim()
      if (saved && places.some((p) => p.placeId === saved)) return saved
    }
    if (places.length === 1) return places[0]!.placeId
    return ""
  }, [defaultPlaceId, places])

  return { placesQuery, places, resolvedDefault, storageKey: STORAGE_KEY }
}

export function HanetPlaceSelect({
  value,
  onChange,
  defaultPlaceId,
  disabled,
  layout = "inline",
  pickerSize,
  className,
}: {
  value: string
  onChange: (placeId: string) => void
  defaultPlaceId?: string | null
  disabled?: boolean
  /** `stacked` — label trên, dùng trong toolbar DataTable. */
  layout?: "inline" | "stacked"
  /** Mặc định: `sm` khi stacked, `default` khi inline. */
  pickerSize?: PickerSize
  className?: string
}) {
  const selectId = useId()
  const { placesQuery, places, resolvedDefault } =
    useHanetSelectedPlaceId(defaultPlaceId)

  useEffect(() => {
    if (!value && resolvedDefault) {
      onChange(resolvedDefault)
    }
  }, [value, resolvedDefault, onChange])

  useEffect(() => {
    if (!value) return
    try {
      window.localStorage.setItem(STORAGE_KEY, value)
    } catch {
      // ignore quota / private mode
    }
  }, [value])

  const selectedPlaceId = value || resolvedDefault

  const placeOptions = useMemo<SelectPickerOption[]>(
    () =>
      places.map((place) => ({
        value: place.placeId,
        label: place.name,
        render: () => (
          <>
            {place.name}{" "}
            <span className="font-mono text-xs text-muted-foreground">
              ({place.placeId})
            </span>
          </>
        ),
      })),
    [places]
  )

  if (placesQuery.isLoading) {
    return (
      <div className="flex items-center gap-2 text-sm text-muted-foreground">
        <Loader2 className="size-4 animate-spin" />
        Đang tải địa điểm HANET…
      </div>
    )
  }

  if (placesQuery.isError) {
    const detail =
      placesQuery.error instanceof Error
        ? placesQuery.error.message
        : "Lỗi không xác định"
    return (
      <div className="space-y-2 text-sm text-destructive">
        <p>Không tải được danh sách place — kiểm tra OAuth HANET.</p>
        <p className="text-xs text-muted-foreground">{detail}</p>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="h-8"
          onClick={() => void placesQuery.refetch()}
        >
          <RefreshCw className="mr-1.5 size-3.5" />
          Tải lại places
        </Button>
      </div>
    )
  }

  if (!places.length) {
    return (
      <p className="text-sm text-amber-700 dark:text-amber-400">
        Tài khoản HANET chưa có place — tạo địa điểm trên{" "}
        <a
          href="https://developers.hanet.ai"
          target="_blank"
          rel="noopener noreferrer"
          className="underline"
        >
          developers.hanet.ai
        </a>{" "}
        hoặc đặt{" "}
        <code className="text-xs">HANET_DEFAULT_PLACE_ID</code> trong .env API.
      </p>
    )
  }

  const resolvedPickerSize =
    pickerSize ?? (layout === "stacked" ? "sm" : "default")

  const selectControl = (
    <SelectPicker
      id={selectId}
      value={selectedPlaceId}
      onChange={(placeId) => {
        if (typeof placeId === "string" && placeId) onChange(placeId)
      }}
      options={placeOptions}
      placeholder="Chọn địa điểm"
      disabled={disabled}
      allowClear={false}
      size={resolvedPickerSize}
      className={layout === "stacked" ? "w-full" : "max-w-xs"}
    />
  )

  if (layout === "stacked") {
    return (
      <DataTableToolbarField
        label="Địa điểm HANET"
        htmlFor={selectId}
        className={cn("min-w-0", className)}
      >
        {selectControl}
      </DataTableToolbarField>
    )
  }

  return (
    <div className={cn("flex flex-wrap items-center gap-2", className)}>
      <span className="text-sm text-muted-foreground">Địa điểm HANET</span>
      {selectControl}
    </div>
  )
}

"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { MapPin } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { defineDataTableActionsColumn } from "@ui/components/data-table"
import { FieldCopyButton } from "@ui/components/field"
import type { HanetPlaceOption } from "@workspace/admin-app/lib/hanet-place-parse"
import {
  HanetPlaceRowActions,
  hanetPlaceActionsColumnMeta,
} from "./hanet-place-row-actions"

export function getHanetPlaceColumns({
  defaultPlaceId = "",
  canWrite = false,
  onEdit,
  onDelete,
}: {
  defaultPlaceId?: string
  canWrite?: boolean
  onEdit?: (place: HanetPlaceOption) => void
  onDelete?: (place: HanetPlaceOption) => void
}): ColumnDef<HanetPlaceOption>[] {
  const normalizedDefault = defaultPlaceId.trim()

  const dataColumns: ColumnDef<HanetPlaceOption>[] = [
    {
      accessorKey: "placeId",
      header: "placeID",
      enableColumnFilter: false,
      size: 160,
      cell: ({ getValue }) => {
        const placeId = String(getValue() ?? "").trim()
        if (!placeId) return "—"
        return (
          <div className="flex items-center gap-2">
            <code className="text-xs font-medium">{placeId}</code>
            <FieldCopyButton text={placeId} />
          </div>
        )
      },
    },
    {
      accessorKey: "name",
      header: "Tên địa điểm",
      enableColumnFilter: false,
      cell: ({ row, getValue }) => {
        const name = String(getValue() ?? "").trim() || "—"
        const isDefault =
          normalizedDefault &&
          row.original.placeId.trim() === normalizedDefault

        return (
          <div className="flex min-w-0 items-center gap-2">
            <MapPin
              className="size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
            <span className="min-w-0 truncate">{name}</span>
            {isDefault ? (
              <Badge variant="secondary" className="h-5 shrink-0 text-[10px]">
                Mặc định
              </Badge>
            ) : null}
          </div>
        )
      },
    },
  ]

  if (!canWrite || (!onEdit && !onDelete)) {
    return dataColumns
  }

  return [
    ...dataColumns,
    defineDataTableActionsColumn<HanetPlaceOption>({
      columnMeta: hanetPlaceActionsColumnMeta,
      cell: ({ row }) => (
        <HanetPlaceRowActions
          place={row.original}
          canWrite={canWrite}
          onEdit={onEdit ? () => onEdit(row.original) : undefined}
          onDelete={onDelete ? () => onDelete(row.original) : undefined}
        />
      ),
    }),
  ]
}

"use client"

import { useMemo, type ReactNode } from "react"
import { AdminDataTable } from "@ui/components/data-table"
import type { HanetPlaceOption } from "@workspace/admin-app/lib/hanet-place-parse"
import { getHanetPlaceColumns } from "./hanet-places-columns"

export type HanetPlacesTableProps = {
  data: HanetPlaceOption[]
  isLoading?: boolean
  defaultPlaceId?: string | null
  filterToolbarExtra?: ReactNode
  canWrite?: boolean
  onEdit?: (place: HanetPlaceOption) => void
  onDelete?: (place: HanetPlaceOption) => void
}

export function HanetPlacesTable({
  data,
  isLoading = false,
  defaultPlaceId,
  filterToolbarExtra,
  canWrite = false,
  onEdit,
  onDelete,
}: HanetPlacesTableProps) {
  const columns = useMemo(
    () =>
      getHanetPlaceColumns({
        defaultPlaceId: defaultPlaceId ?? "",
        canWrite,
        onEdit,
        onDelete,
      }),
    [canWrite, defaultPlaceId, onDelete, onEdit]
  )

  return (
    <AdminDataTable<HanetPlaceOption>
      tableScope="hanet-places"
      data={data}
      columns={columns}
      getRowId={(row) => row.placeId}
      isLoading={isLoading}
      emptyLabel="Không có địa điểm — bấm Thêm địa điểm hoặc kiểm tra tài khoản HANET."
      globalFilterPlaceholder="Tìm theo placeID hoặc tên địa điểm…"
      globalFilterLabel="Tìm kiếm"
      getGlobalFilterText={(row) => [row.placeId, row.name].filter(Boolean).join(" ")}
      filterToolbarExtra={filterToolbarExtra}
      footer={
        <p className="text-sm text-muted-foreground">
          {isLoading
            ? "Đang tải…"
            : `Tổng ${data.length} địa điểm từ HANET`}
        </p>
      }
    />
  )
}

