"use client"

import type { ColumnDef } from "@tanstack/react-table"
import Link from "next/link"
import { CalendarDays } from "lucide-react"
import {
  formatEventDateTime,
  formatEventScheduleText,
  formatEventTimeDateLine,
  getEventLocationLabel,
  getPosterUrl,
} from "../_lib/event-display"
import { FORMAT_LABELS } from "../_lib/registration-format"
import {
  DateTimeTableCell,
  EventScheduleTableCell,
} from "./event-schedule-cells"
import { defineDataTableActionsColumn } from "@ui/components/data-table"
import {
  MyRegisteredEventRowActions,
  type MyRegisteredEventRowActionHandlers,
} from "./my-registered-events-row-actions"
import {
  ATTENDANCE_STATUS_LABELS,
  REGISTRATION_STATUS_LABELS,
  type MyRegisteredEventRow,
} from "./types"
import { RegistrationStatusBadge } from "./registration-status-badge"
import { eventHref } from "./utils"

export function getMyRegisteredEventColumns({
  actionHandlers,
  eventDetailPathPrefix = "/su-kien",
  registrantColumnLabel = "Sinh viên",
}: {
  actionHandlers: MyRegisteredEventRowActionHandlers
  eventDetailPathPrefix?: string
  registrantColumnLabel?: string
}): ColumnDef<MyRegisteredEventRow, unknown>[] {
  return [
    {
      id: "eventTitle",
      accessorFn: (row) => row.event.title,
      header: "Sự kiện",
      enableColumnFilter: true,
      cell: ({ row }) => {
        const event = row.original.event
        const posterUrl = getPosterUrl(event.poster)
        return (
          <div className="flex gap-3">
            <div className="aspect-[4/3] w-20 shrink-0 overflow-hidden rounded-lg bg-muted ring-1 ring-border">
              {posterUrl ? (
                <img
                  src={posterUrl}
                  alt=""
                  className="size-full object-cover"
                  loading="lazy"
                />
              ) : (
                <div className="flex size-full items-center justify-center text-primary">
                  <CalendarDays className="size-6" />
                </div>
              )}
            </div>
            <div className="min-w-0 space-y-1">
              <Link
                href={eventHref(row.original, eventDetailPathPrefix)}
                className="line-clamp-2 font-semibold text-foreground underline-offset-4 hover:text-primary hover:underline"
              >
                {event.title}
              </Link>
              <div className="flex flex-wrap gap-1.5 text-xs text-muted-foreground">
                <span>{FORMAT_LABELS[event.format] ?? "Offline"}</span>
                {getEventLocationLabel(event) ? (
                  <>
                    <span>·</span>
                    <span className="line-clamp-1">
                      {getEventLocationLabel(event)}
                    </span>
                  </>
                ) : null}
              </div>
            </div>
          </div>
        )
      },
      meta: {
        className: "min-w-[260px]",
        filterPlaceholder: "Lọc theo tên sự kiện",
        exportHeader: "Tên sự kiện",
        exportValue: (row: MyRegisteredEventRow) => row.event.title,
        exportWidth: 38,
        exportWrap: true,
      },
    },
    {
      accessorKey: "id",
      header: "Mã đăng ký",
      enableColumnFilter: true,
      cell: ({ getValue }) => (
        <span className="font-mono text-xs text-muted-foreground">
          {String(getValue() ?? "").slice(0, 8)}
        </span>
      ),
      meta: {
        className: "min-w-[120px]",
        filterPlaceholder: "Lọc mã đăng ký",
        exportHeader: "Mã đăng ký",
        exportWidth: 28,
      },
    },
    {
      accessorKey: "fullName",
      header: registrantColumnLabel,
      meta: {
        hideInTable: true,
        exportHeader: `${registrantColumnLabel} đăng ký`,
        exportValue: (row: MyRegisteredEventRow) => row.fullName,
        exportWidth: 28,
        exportWrap: true,
      },
    },
    {
      accessorKey: "email",
      header: "Email",
      meta: {
        hideInTable: true,
        exportHeader: "Email",
        exportValue: (row: MyRegisteredEventRow) => row.email,
        exportWidth: 30,
      },
    },
    {
      accessorKey: "phone",
      header: "Số điện thoại",
      meta: {
        hideInTable: true,
        exportHeader: "Số điện thoại",
        exportValue: (row: MyRegisteredEventRow) => row.phone ?? "",
        exportWidth: 18,
      },
    },
    {
      id: "eventFormat",
      header: "Hình thức",
      accessorFn: (row) => FORMAT_LABELS[row.event.format] ?? "Offline",
      meta: {
        hideInTable: true,
        exportHeader: "Hình thức tổ chức",
        exportValue: (row: MyRegisteredEventRow) =>
          FORMAT_LABELS[row.event.format] ?? "Offline",
        exportWidth: 18,
      },
    },
    {
      accessorKey: "registeredAt",
      header: "Ngày đăng ký",
      enableColumnFilter: true,
      cell: ({ getValue }) => (
        <DateTimeTableCell value={getValue() as string | null} />
      ),
      meta: {
        className: "min-w-[120px]",
        filterVariant: "date-range",
        filterPlaceholder: "Khoảng ngày đăng ký",
        exportHeader: "Ngày đăng ký",
        exportValue: (row: MyRegisteredEventRow) =>
          formatEventTimeDateLine(row.registeredAt) ?? "",
        exportWidth: 22,
      },
    },
    {
      id: "eventStartDate",
      accessorFn: (row) => row.event.startDate,
      header: "Thời gian sự kiện",
      enableColumnFilter: true,
      cell: ({ row }) => (
        <EventScheduleTableCell
          start={row.original.event.startDate}
          end={row.original.event.endDate}
        />
      ),
      meta: {
        className: "min-w-[160px]",
        filterVariant: "date-range",
        filterPlaceholder: "Khoảng thời gian sự kiện",
        exportHeader: "Thời gian sự kiện",
        exportValue: (row: MyRegisteredEventRow) =>
          formatEventScheduleText(
            row.event.startDate,
            row.event.endDate,
          ) ?? "",
        exportWidth: 28,
        exportWrap: true,
      },
    },
    {
      accessorKey: "event.endDate",
      header: "Thời gian kết thúc",
      meta: {
        hideInTable: true,
        exportHeader: "Thời gian kết thúc",
        exportValue: (row: MyRegisteredEventRow) =>
          formatEventDateTime(row.event.endDate) ?? "",
        exportWidth: 22,
      },
    },
    {
      accessorKey: "event.registrationEnd",
      header: "Hạn đăng ký",
      meta: {
        hideInTable: true,
        exportHeader: "Hạn đăng ký",
        exportValue: (row: MyRegisteredEventRow) =>
          formatEventDateTime(row.event.registrationEnd) ?? "",
        exportWidth: 22,
      },
    },
    {
      id: "location",
      header: "Địa điểm",
      accessorFn: (row) => getEventLocationLabel(row.event) ?? "",
      enableColumnFilter: true,
      cell: ({ row }) => (
        <span className="line-clamp-2 text-sm text-muted-foreground">
          {getEventLocationLabel(row.original.event) || "—"}
        </span>
      ),
      meta: {
        className: "min-w-[120px]",
        filterPlaceholder: "Lọc địa điểm",
        exportHeader: "Địa điểm tổ chức",
        exportValue: (row: MyRegisteredEventRow) =>
          getEventLocationLabel(row.event) ?? "",
        exportWidth: 42,
        exportWrap: true,
      },
    },
    {
      accessorKey: "status",
      header: "Trạng thái",
      enableColumnFilter: true,
      filterFn: (row, _columnId, filterValue) => {
        if (filterValue == null || filterValue === "") return true
        return String(row.original.status) === String(filterValue)
      },
      cell: ({ row }) => (
        <div className="space-y-1">
          <RegistrationStatusBadge row={row.original} />
        </div>
      ),
      meta: {
        filterVariant: "select",
        selectOptions: [
          { value: "0", label: "Chờ xử lý" },
          { value: "1", label: "Đã xác nhận" },
          { value: "2", label: "Đã hủy" },
        ],
        exportHeader: "Trạng thái đăng ký",
        exportValue: (row: MyRegisteredEventRow) => {
          const registration =
            REGISTRATION_STATUS_LABELS[row.status] ??
            `Trạng thái ${row.status}`
          const attendance =
            ATTENDANCE_STATUS_LABELS[row.attendanceStatus] ?? "Không xác định"
          return `${registration}\nTham dự: ${attendance}\nCheck-in: ${
            row.hasCheckin ? "Đã check-in" : "Chưa check-in"
          }`
        },
        exportWidth: 28,
        exportWrap: true,
      },
    },
    defineDataTableActionsColumn<MyRegisteredEventRow>({
      cell: ({ row }) => (
        <MyRegisteredEventRowActions
          row={row.original}
          handlers={actionHandlers}
        />
      ),
    }),
  ]
}

"use client"

import {
  formatEventTimeDateParts,
  getEventScheduleDisplay,
  type EventTimeDateParts,
} from "../_lib/event-display"

export function DateTimeTableCell({ value }: { value?: string | null }) {
  const parts = formatEventTimeDateParts(value)
  if (!parts) {
    return <span className="text-sm text-muted-foreground">—</span>
  }
  return (
    <div className="space-y-0.5 tabular-nums">
      <p className="text-sm font-medium leading-none">{parts.time}</p>
      <p className="text-xs leading-snug text-muted-foreground">{parts.date}</p>
    </div>
  )
}

function SchedulePoint({
  label,
  parts,
}: {
  label: string
  parts: EventTimeDateParts
}) {
  return (
    <div className="space-y-0.5">
      <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
        {label}
      </p>
      <p className="text-sm font-medium tabular-nums leading-none">
        {parts.time}
      </p>
      <p className="text-xs tabular-nums leading-snug text-muted-foreground">
        {parts.date}
      </p>
    </div>
  )
}

export function EventScheduleTableCell({
  start,
  end,
}: {
  start?: string | null
  end?: string | null
}) {
  const display = getEventScheduleDisplay(start, end)

  if (display.kind === "empty") {
    return <span className="text-sm text-muted-foreground">—</span>
  }

  if (display.kind === "single") {
    return <DateTimeTableCell value={start} />
  }

  if (display.kind === "same-day") {
    return (
      <div className="space-y-0.5 tabular-nums">
        <p className="text-sm font-medium leading-none">{display.timeRange}</p>
        <p className="text-xs leading-snug text-muted-foreground">
          {display.date}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-2">
      <SchedulePoint label="Bắt đầu" parts={display.start} />
      <SchedulePoint label="Kết thúc" parts={display.end} />
    </div>
  )
}

"use client"

import type { Dispatch, SetStateAction } from "react"
import { XCircle } from "lucide-react"
import { toast } from "sonner"
import type { AdminDataTableBulkAction } from "@ui/components/data-table"
import type { createStoreSyncSdk } from "@workspace/api-client"
import {
  cancelMyEventRegistration,
  type MyRegisteredEvent,
} from "../_lib/my-registered-events"
import type { MyRegisteredEventRow } from "./types"
import { canCancelRegistrationRow } from "./utils"

export function buildMyRegisteredEventsBulkActions({
  api,
  setRows,
  reload,
}: {
  api: ReturnType<typeof createStoreSyncSdk>
  setRows: Dispatch<SetStateAction<MyRegisteredEvent[]>>
  reload: (options?: { silent?: boolean }) => Promise<void>
}): AdminDataTableBulkAction<MyRegisteredEventRow>[] {
  return [
    {
      id: "cancel",
      label: "Hủy đăng ký",
      variant: "destructive",
      icon: <XCircle className="size-4" />,
      disabled: (selectedRows) =>
        selectedRows.length === 0 ||
        selectedRows.some((row) => !canCancelRegistrationRow(row)),
      confirm: {
        title: "Hủy các đăng ký đã chọn?",
        description:
          "Chỉ hủy được khi còn trong thời gian đăng ký, chưa check-in và sự kiện chưa bắt đầu.",
        confirmLabel: "Hủy đăng ký",
        destructive: true,
      },
      onAction: async (selectedRows) => {
        if (selectedRows.some((row) => !canCancelRegistrationRow(row))) {
          toast.error(
            "Có đăng ký đã chọn không thể hủy (ngoài thời gian đăng ký, đã check-in hoặc sự kiện đã bắt đầu).",
          )
          return
        }
        if (selectedRows.length === 0) {
          toast.error("Vui lòng chọn ít nhất một đăng ký có thể hủy.")
          return
        }

        try {
          const updatedRows = await Promise.all(
            selectedRows.map((row) => cancelMyEventRegistration(api, row.id)),
          )
          const updatedById = new Map(
            updatedRows.map((row) => [row.id, row] as const),
          )
          setRows((current) =>
            current.map((item) => updatedById.get(item.id) ?? item),
          )
          toast.success(
            selectedRows.length === 1
              ? "Đã hủy đăng ký sự kiện."
              : `Đã hủy ${selectedRows.length} đăng ký sự kiện.`,
          )
        } catch (err) {
          toast.error(
            err instanceof Error ? err.message : "Không thể hủy đăng ký.",
          )
          await reload({ silent: true })
          throw err
        }
      },
    },
  ]
}

"use client"

import { useMemo } from "react"
import { useRouter } from "next/navigation"
import { CalendarDays, RefreshCw } from "lucide-react"
import { Alert, AlertDescription, AlertTitle } from "@ui/components/alert"
import {
  AdminListPageHeader,
  AdminPageSection,
} from "@ui/components/admin"
import { Button } from "@ui/components/button"
import { useAdminApi } from "@workspace/admin-app/runtime"
import { canCancelMyRegistration } from "../_lib/my-registered-events"
import type { MyRegisteredEventsPageConfig } from "../_config"
import { MyRegisteredEventsTable } from "./_table"
import { useMyRegisteredEvents } from "./_query"
import { getMyRegisteredEventColumns } from "./columns"
import { buildMyRegisteredEventsBulkActions } from "./my-registered-events-bulk-actions"
import { MyRegisteredEventsStatCards } from "./my-registered-events-stat-cards"
import { eventHref } from "./utils"

function MyRegisteredEventsPageInner({
  config,
}: {
  config: MyRegisteredEventsPageConfig
}) {
  const router = useRouter()
  const api = useAdminApi()
  const eventDetailPathPrefix = config.eventDetailPathPrefix ?? "/su-kien"
  const tableScope =
    config.tableScope ?? `checkin-${config.role}-my-registered-events`
  const exportAudienceLabel =
    config.exportAudienceLabel ?? config.role
  const registrantColumnLabel =
    config.registrantColumnLabel ?? "Người đăng ký"

  const {
    session,
    rows,
    setRows,
    loading,
    error,
    load,
    stats,
    cancellingId,
    cancelRegistration,
  } = useMyRegisteredEvents()

  const exportGeneratedAt = useMemo(
    () =>
      new Intl.DateTimeFormat("vi-VN", {
        dateStyle: "medium",
        timeStyle: "short",
      }).format(new Date()),
    [],
  )

  const actionHandlers = useMemo(
    () => ({
      onView: (row: (typeof rows)[number]) => {
        router.push(eventHref(row, eventDetailPathPrefix))
      },
      onCancel: async (row: (typeof rows)[number]) => {
        if (!canCancelMyRegistration(row)) return
        await cancelRegistration(row)
      },
      cancellingId,
    }),
    [cancelRegistration, cancellingId, eventDetailPathPrefix, router],
  )

  const columns = useMemo(
    () =>
      getMyRegisteredEventColumns({
        actionHandlers,
        eventDetailPathPrefix,
        registrantColumnLabel,
      }),
    [actionHandlers, eventDetailPathPrefix, registrantColumnLabel],
  )

  const bulkActions = useMemo(
    () => buildMyRegisteredEventsBulkActions({ api, setRows, reload: load }),
    [api, load, setRows],
  )

  if (!session) {
    return null
  }

  return (
    <AdminPageSection className="space-y-6">
      <AdminListPageHeader
        icon={CalendarDays}
        title="Sự kiện của tôi"
        subtitle="Danh sách đăng ký, trạng thái check-in và hủy đăng ký khi còn thời hạn."
        actions={
          <Button
            variant="outline"
            onClick={() => void load()}
            className="h-11 font-bold"
          >
            <RefreshCw
              className={`mr-2 size-4 ${loading ? "animate-spin" : ""}`}
            />
            Làm mới
          </Button>
        }
      />

      <MyRegisteredEventsStatCards stats={stats} loading={loading} />

      {error ? (
        <Alert variant="destructive">
          <AlertTitle>Không thể tải dữ liệu</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      <MyRegisteredEventsTable
        rows={rows}
        columns={columns}
        loading={loading}
        session={session}
        exportGeneratedAt={exportGeneratedAt}
        bulkActions={bulkActions}
        tableScope={tableScope}
        exportAudienceLabel={exportAudienceLabel}
      />
    </AdminPageSection>
  )
}

export function MyRegisteredEventsPage({
  config,
}: {
  config: MyRegisteredEventsPageConfig
}) {
  return <MyRegisteredEventsPageInner config={config} />
}

"use client"

import { ExternalLink, Loader2, XCircle } from "lucide-react"
import {
  DataTableRowActionsMenu,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import { getCancelRegistrationState } from "../_lib/my-registered-events"
import type { MyRegisteredEventRow } from "./types"

export type MyRegisteredEventRowActionHandlers = {
  onView: (row: MyRegisteredEventRow) => void
  onCancel: (row: MyRegisteredEventRow) => void | Promise<void>
  cancellingId?: string | null
}

function buildRowActions(
  row: MyRegisteredEventRow,
  handlers: MyRegisteredEventRowActionHandlers,
): DataTableRowActionItem[] {
  const cancelState = getCancelRegistrationState(row)
  const isCancelling = handlers.cancellingId === row.id

  const actions: DataTableRowActionItem[] = [
    {
      key: "view",
      label: "Xem sự kiện",
      hint: "Mở trang chi tiết và vé điện tử",
      icon: <ExternalLink className="size-4" />,
      onClick: () => handlers.onView(row),
      group: "primary",
    },
  ]

  if (cancelState.allowed || isCancelling) {
    actions.push({
      key: "cancel",
      label: "Hủy đăng ký",
      hint: cancelState.allowed
        ? "Chỉ hủy khi còn trong thời gian đăng ký"
        : cancelState.reason,
      icon: isCancelling ? (
        <Loader2 className="size-4 animate-spin" />
      ) : (
        <XCircle className="size-4" />
      ),
      disabled: !cancelState.allowed || isCancelling,
      title: !cancelState.allowed ? cancelState.reason : undefined,
      menuVariant: "destructive",
      group: "danger",
      confirm: cancelState.allowed
        ? {
            title: "Hủy đăng ký sự kiện?",
            description: `Bạn sẽ hủy đăng ký «${row.event.title}». Thao tác này không thể hoàn tác.`,
            confirmLabel: "Hủy đăng ký",
            destructive: true,
          }
        : false,
      onClick: () => handlers.onCancel(row),
    })
  }

  return actions
}

export function MyRegisteredEventRowActions({
  row,
  handlers,
}: {
  row: MyRegisteredEventRow
  handlers: MyRegisteredEventRowActionHandlers
}) {
  const actions = buildRowActions(row, handlers)
  const busy = handlers.cancellingId === row.id

  return (
    <div className="flex w-full justify-center">
      <DataTableRowActionsMenu
        actions={actions}
        busy={busy}
        triggerLabel="Thao tác đăng ký sự kiện"
        groups={{
          primary: { label: "Sự kiện" },
          danger: { label: "Hủy đăng ký", sublabel: true },
        }}
      />
    </div>
  )
}

