"use client"

import { useCallback, useEffect, useMemo, useState } from "react"
import { toast } from "sonner"
import { useAdminApi, useAdminAuth } from "@workspace/admin-app/runtime"
import {
  cancelMyEventRegistration,
  computeMyRegisteredEventStats,
  fetchMyRegisteredEvents,
  type MyRegisteredEvent,
} from "../../_lib/my-registered-events"

export function useMyRegisteredEvents() {
  const api = useAdminApi()
  const { user: session, isLoading: authLoading } = useAdminAuth()
  const [rows, setRows] = useState<MyRegisteredEvent[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [cancellingId, setCancellingId] = useState<string | null>(null)

  const load = useCallback(async (options?: { silent?: boolean }) => {
    if (!session?.id) {
      setRows([])
      setLoading(false)
      return
    }

    if (!options?.silent) {
      setLoading(true)
    }
    setError(null)
    try {
      setRows(await fetchMyRegisteredEvents(api))
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Không thể tải dữ liệu."
      setError(message)
    } finally {
      if (!options?.silent) {
        setLoading(false)
      }
    }
  }, [api, session?.id])

  useEffect(() => {
    if (authLoading) return
    void load()
  }, [authLoading, load])

  const stats = useMemo(
    () => computeMyRegisteredEventStats(rows),
    [rows],
  )

  const cancelRegistration = useCallback(
    async (row: MyRegisteredEvent) => {
      setCancellingId(row.id)
      try {
        const updated = await cancelMyEventRegistration(api, row.id)
        setRows((current) =>
          current.map((item) => (item.id === updated.id ? updated : item)),
        )
        toast.success("Đã hủy đăng ký sự kiện.")
        return updated
      } catch (err) {
        toast.error(
          err instanceof Error ? err.message : "Không thể hủy đăng ký.",
        )
        throw err
      } finally {
        setCancellingId(null)
      }
    },
    [api],
  )

  return {
    session,
    rows,
    setRows,
    loading: loading || authLoading,
    error,
    load,
    stats,
    cancellingId,
    cancelRegistration,
  }
}

"use client"

import { useCallback, useState } from "react"
import type {
  ColumnDef,
  ColumnFiltersState,
  RowSelectionState,
} from "@tanstack/react-table"
import type { AuthUser } from "@workspace/api-client"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
  type AdminDataTableBulkAction,
} from "@ui/components/data-table"
import {
  ATTENDANCE_STATUS_LABELS,
  REGISTRATION_STATUS_LABELS,
  type MyRegisteredEventRow,
} from "../types"
import { canCancelRegistrationRow } from "../utils"

export type MyRegisteredEventsTableProps = {
  rows: MyRegisteredEventRow[]
  columns: ColumnDef<MyRegisteredEventRow, unknown>[]
  loading: boolean
  session: AuthUser
  exportGeneratedAt: string
  bulkActions: AdminDataTableBulkAction<MyRegisteredEventRow>[]
  tableScope: string
  exportAudienceLabel: string
}

export function MyRegisteredEventsTable({
  rows,
  columns,
  loading,
  session,
  exportGeneratedAt,
  bulkActions,
  tableScope,
  exportAudienceLabel,
}: MyRegisteredEventsTableProps) {
  const [selectedRowIds, setSelectedRowIds] = useState<RowSelectionState>({})
  const [globalFilter, setGlobalFilter] = useState("")
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])

  const handleClearFilters = useCallback(() => {
    setGlobalFilter("")
    setColumnFilters([])
    setSelectedRowIds({})
  }, [])

  const displayName =
    session.name?.trim() || session.email

  return (
    <AdminDataTable<MyRegisteredEventRow>
      tableScope={tableScope}
      data={rows}
      columns={columns}
      getRowId={(row) => row.id}
      isLoading={loading}
      indexColumnExcludeFromExport
      emptyLabel="Bạn chưa đăng ký sự kiện nào."
      getGlobalFilterText={(row) =>
        [
          row.event.title,
          row.event.location,
          row.event.address,
          row.fullName,
          row.email,
          REGISTRATION_STATUS_LABELS[row.status],
          ATTENDANCE_STATUS_LABELS[row.attendanceStatus],
        ]
          .filter(Boolean)
          .join(" ")
      }
      globalFilter={globalFilter}
      onGlobalFilterChange={setGlobalFilter}
      globalFilterPlaceholder="Tìm theo tên sự kiện, địa điểm, trạng thái..."
      columnFilters={columnFilters}
      onColumnFiltersChange={setColumnFilters}
      onClearFilters={handleClearFilters}
      clearFiltersVariant="destructive"
      clientPagination={{
        initialPageSize: 10,
        itemLabel: "đăng ký",
        isLoading: loading,
      }}
      xlsxExport={{
        fileName: "su-kien-cua-toi.xlsx",
        sheetName: "Su kien cua toi",
        title: "DANH SÁCH SỰ KIỆN ĐÃ ĐĂNG KÝ",
        subtitle: `Báo cáo dành cho ${exportAudienceLabel} trên HUB Events`,
        metadata: [
          { label: "Chủ đề", value: `Sự kiện ${exportAudienceLabel} đã đăng ký` },
          { label: "Ngày xuất", value: exportGeneratedAt },
          { label: "Người xuất", value: displayName },
          { label: "Email", value: session.email },
          { label: "Số bản ghi", value: rows.length },
        ],
      }}
      filterColumnVisibilityKey={`checkin-my-registered-events-filters:${tableScope}`}
      canSelectRow={(row) => canCancelRegistrationRow(row.original)}
      bulkActions={bulkActions}
      footer={
        <p className="text-sm text-muted-foreground">
          {loading ? "Đang tải..." : `Tổng ${rows.length} đăng ký`}
        </p>
      }
      {...adminTableRowSelectionProps(selectedRowIds, setSelectedRowIds)}
    />
  )
}

