"use client"

import { Copy, ExternalLink, Eye } from "lucide-react"
import {
  DataTableRowActionsMenu,
  TABLE_ACTIONS_COLUMN_META,
  type DataTableRowActionItem,
} from "@ui/components/data-table"
import type { OrderItemRow } from "./types"

export type OrderItemRowActionHandlers = {
  onViewProduct: (item: OrderItemRow) => void
  onCopySku: (item: OrderItemRow) => void | Promise<void>
  busyItemId?: string | null
}

export function OrderItemRowActions({
  item,
  handlers,
}: {
  item: OrderItemRow
  handlers: OrderItemRowActionHandlers
}) {
  const unit = item.unitLabel?.trim() || item.unitType

  const actions: DataTableRowActionItem[] = [
    {
      key: "view",
      label: "Xem sản phẩm",
      hint: "Mở trang quản trị SP",
      onClick: () => handlers.onViewProduct(item),
      icon: <Eye />,
      group: "primary",
    },
    {
      key: "copy-sku",
      label: "Sao chép SKU",
      hint: item.sku,
      onClick: () => handlers.onCopySku(item),
      icon: <Copy />,
      group: "status",
      confirm: false,
    },
    {
      key: "open-tab",
      label: "Mở tab mới",
      hint: "Xem SP ở tab riêng",
      onClick: () => {
        window.open(`/products/${item.productId}`, "_blank", "noopener")
      },
      icon: <ExternalLink />,
      group: "status",
      confirm: false,
    },
  ]

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={handlers.busyItemId === item.id}
      autoConfirmDangerousActions={false}
      triggerLabel={`Thao tác ${item.sku}`}
      groups={{
        primary: { label: "Thao tác nhanh", sublabel: false },
        status: {
          label: "Tiện ích",
          sublabel: true,
          header: (
            <div className="min-w-0 px-1 pb-1">
              <p className="line-clamp-2 text-[11px] font-medium leading-snug">
                {item.name}
              </p>
              <p className="font-mono text-[11px] text-muted-foreground">
                {item.sku}
                {unit ? ` · ${item.quantity.toLocaleString("vi-VN")} × ${unit}` : null}
              </p>
            </div>
          ),
        },
      }}
    />
  )
}

export const orderItemActionsColumnMeta = {
  ...TABLE_ACTIONS_COLUMN_META,
  className: `${TABLE_ACTIONS_COLUMN_META.className} sticky right-0 z-[10]`,
}

"use client"

import type { ColumnDef } from "@tanstack/react-table"
import Link from "next/link"
import { Package2 } from "lucide-react"
import { Badge } from "@ui/components/badge"
import { defineDataTableActionsColumn } from "@ui/components/data-table"
import { resolveMediaUrl } from "@ui/lib/resolve-media-url"
import { formatVND } from "@workspace/admin-app/lib/format"
import {
  OrderItemRowActions,
  type OrderItemRowActionHandlers,
} from "./order-item-row-actions"
import type { OrderItemRow } from "./types"

export function getOrderItemColumns({
  actionHandlers,
  getProductDetailHref,
}: {
  actionHandlers: OrderItemRowActionHandlers
  getProductDetailHref: (productId: string | number) => string
}): ColumnDef<OrderItemRow>[] {
  return [
    {
      accessorKey: "name",
      header: "Sản phẩm",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => {
        const item = row.original
        const imageSrc = item.image
          ? resolveMediaUrl(item.image, 120)
          : null
        return (
          <Link
            href={getProductDetailHref(item.productId)}
            className="flex min-w-[10rem] items-center gap-3 rounded-lg transition-colors hover:bg-muted/40"
          >
            {imageSrc ? (
              <img
                src={imageSrc}
                alt=""
                className="size-10 shrink-0 rounded-md border object-cover"
              />
            ) : (
              <div className="flex size-10 shrink-0 items-center justify-center rounded-md border border-dashed bg-muted/40 text-muted-foreground">
                <Package2 className="size-4 opacity-60" aria-hidden />
              </div>
            )}
            <div className="min-w-0">
              <p className="line-clamp-2 text-sm font-semibold leading-snug">
                {item.name}
              </p>
              <p className="font-mono text-xs text-muted-foreground">
                {item.sku}
              </p>
              {item.giftNote ? (
                <p className="mt-0.5 line-clamp-1 text-xs text-primary">
                  {item.giftNote}
                </p>
              ) : null}
            </div>
          </Link>
        )
      },
    },
    {
      id: "quantity",
      header: "Số lượng",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => {
        const unit =
          row.original.unitLabel?.trim() || row.original.unitType
        return (
          <Badge variant="outline" className="font-normal tabular-nums">
            {row.original.quantity.toLocaleString("vi-VN")} × {unit}
          </Badge>
        )
      },
    },
    {
      accessorKey: "unitPrice",
      header: "Đơn giá",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => {
        const item = row.original
        const hasDiscount =
          item.listUnitPrice != null && item.listUnitPrice > item.unitPrice
        return (
          <div className="text-xs tabular-nums">
            {hasDiscount ? (
              <p className="text-muted-foreground line-through">
                {formatVND(item.listUnitPrice!)}
              </p>
            ) : null}
            <p className="font-semibold">{formatVND(item.unitPrice)}</p>
          </div>
        )
      },
    },
    {
      accessorKey: "totalPrice",
      header: "Thành tiền",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => (
        <span className="font-bold tabular-nums text-primary">
          {formatVND(row.original.totalPrice)}
        </span>
      ),
    },
    defineDataTableActionsColumn<OrderItemRow>({
      cell: ({ row }) => (
        <OrderItemRowActions item={row.original} handlers={actionHandlers} />
      ),
    }),
  ]
}

"use client"

import { useMemo } from "react"
import type { OrderItem } from "@workspace/api-client"
import { AdminDataTable } from "@ui/components/data-table"
import { getOrderItemColumns } from "./order-items-columns"
import type { OrderItemRowActionHandlers } from "./order-item-row-actions"
import { mapOrderItemRows, type OrderItemRow } from "./types"

export function OrderItemsTable({
  orderId,
  items,
  actionHandlers,
  getProductDetailHref,
}: {
  orderId: string
  items?: OrderItem[]
  actionHandlers: OrderItemRowActionHandlers
  getProductDetailHref: (productId: string | number) => string
}) {
  const rows = useMemo(
    () => mapOrderItemRows(orderId, items),
    [items, orderId]
  )

  const columns = useMemo(
    () => getOrderItemColumns({ actionHandlers, getProductDetailHref }),
    [actionHandlers, getProductDetailHref]
  )

  if (rows.length === 0) {
    return (
      <p className="py-2 text-center text-sm text-muted-foreground">
        Không có sản phẩm trong đơn.
      </p>
    )
  }

  return (
    <AdminDataTable<OrderItemRow>
      embedded
      tableScope={`order-${orderId}-items`}
      data={rows}
      columns={columns}
      getRowId={(row) => row.id}
      showTableToolbar={false}
      showColumnFilters={false}
      showTableColumnPicker={false}
      showIndexColumn
      indexColumnLabel="#"
      stickyTableHeader={false}
      horizontalScrollButtons={false}
      emptyLabel="Không có sản phẩm."
    />
  )
}

