"use client"

import { Trash2 } from "lucide-react"
import type { AdminDataTableBulkAction } from "@ui/components/data-table"
import type { OrderStatus } from "@workspace/api-client"
import { ORDER_STATUS_LABELS, ORDER_STATUSES, type OrderRow } from "./types"

export function buildOrderBulkStatusActionMap({
  onBulkStatusChange,
}: {
  onBulkStatusChange: (rows: OrderRow[], status: OrderStatus) => Promise<void>
}): Record<OrderStatus, AdminDataTableBulkAction<OrderRow>> {
  const map = {} as Record<OrderStatus, AdminDataTableBulkAction<OrderRow>>
  for (const status of ORDER_STATUSES) {
    map[status] = {
      id: `bulk-order-status-${status}`,
      label: ORDER_STATUS_LABELS[status],
      onAction: (rows) => onBulkStatusChange(rows, status),
      confirm: {
        title: `Đặt trạng thái «${ORDER_STATUS_LABELS[status]}»?`,
        description: (rows) => (
          <span>
            Áp dụng cho <strong>{rows.length}</strong> đơn hàng đã chọn.
          </span>
        ),
        confirmLabel: "Cập nhật",
      },
    }
  }
  return map
}

export function buildOrderBulkDeleteAction({
  onBulkDelete,
}: {
  onBulkDelete: (rows: OrderRow[]) => Promise<void>
}): AdminDataTableBulkAction<OrderRow> {
  return {
    id: "bulk-order-delete",
    label: "Xóa đã chọn",
    variant: "destructive",
    icon: <Trash2 className="size-3.5" aria-hidden />,
    confirm: {
      title: "Xóa các đơn đã chọn?",
      description: (rows) => (
        <span>
          Bạn đã chọn <strong>{rows.length}</strong> đơn hàng. Không thể hoàn
          tác.
        </span>
      ),
      confirmLabel: "Xóa",
      destructive: true,
    },
    onAction: onBulkDelete,
  }
}

export function buildOrderBulkActions({
  canDelete,
  onBulkDelete,
}: {
  canDelete: boolean
  onBulkDelete: (rows: OrderRow[]) => Promise<void>
}): AdminDataTableBulkAction<OrderRow>[] {
  if (!canDelete) return []
  return [buildOrderBulkDeleteAction({ onBulkDelete })]
}

src/modules/orders/_component/use-orders.content:
import { api } from "@workspace/admin-app/lib/api"
import {
  adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@workspace/admin-app/lib/admin-detail-query"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk } from "@workspace/api-client"
import { mapOrderRow, type OrderRow } from "./types"

export const orderDetailQueryKey = (id: string) =>
  ["orders", "detail", id] as const

export function prefetchOrderDetail(
  queryClient: QueryClient,
  api: StoreSyncSdk,
  id: string
) {
  return prefetchAdminDetailQuery(queryClient, orderDetailQueryKey(id), () =>
    api.orders.get(Number(id))
  )
}

export function useOrderDetailQuery(api: StoreSyncSdk, id: string) {
  return useQuery({
    ...adminDetailQueryOptions(
      orderDetailQueryKey(id),
      async () => api.orders.get(Number(id)),
      id
    ),
  })
}

export function useOrdersListQuery(
  api: StoreSyncSdk,
  params: {
    page: number
    limit: number
    status?: string
    search?: string
    filters?: Record<string, string>
    enabled?: boolean
  }
) {
  return useQuery({
    queryKey: ["orders", "list", params],
    queryFn: async () => {
      const result = await api.orders.list({
        page: params.page,
        limit: params.limit,
        status:
          params.status && params.status !== "all" ? params.status : undefined,
        search: params.search,
        filters: params.filters,
      })
      return {
        items: result.items.map(mapOrderRow),
        total: result.total,
      }
    },
    enabled: params.enabled !== false,
  })
}

export function useOrderStatusCountsQuery(api: StoreSyncSdk) {
  return useQuery({
    queryKey: ["orders", "status-counts"],
    queryFn: () => api.orders.getStaffStatusCounts(),
  })
}

export type { OrderRow }

