                valueClassName="font-medium"
              >
                {formatDateTime(post.updatedAt)}
              </FieldSectionField>
            </FieldSetContent>
          </FieldSet>
        </AdminDetailSidebar>
      </AdminDetailLayout>
    </AdminPageSection>
  )
}

export default function PostDetailPage() {
