"use client"

import { useEffect, useMemo, useState } from "react"
import { Package } from "lucide-react"
import {
  PanelDialog,
  PanelDialogSearch,
} from "@ui/components/dialogs/panel-dialog"
import { Button } from "@ui/components/button"
import { resolveMediaUrl } from "@ui/lib/resolve-media-url"
import { api } from "@workspace/admin-app/lib/api"
import { useProductsListQuery } from "./use-products-queries"
import type { ProductRow } from "./types"

function firstProductImage(product: ProductRow): string {
  const fromUnit = product.unitTypes?.find((u) => u.images?.length)?.images?.[0]
  return fromUnit ?? product.images?.[0] ?? ""
}

export type ProductCatalogPickerDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSelect: (product: ProductRow) => void
  excludeProductId?: string | null
  title?: string
}

export function ProductCatalogPickerDialog({
  open,
  onOpenChange,
  onSelect,
  excludeProductId,
  title = "Chọn sản phẩm quà tặng",
}: ProductCatalogPickerDialogProps) {
  const [q, setQ] = useState("")
  const [debouncedQ, setDebouncedQ] = useState("")

  useEffect(() => {
    if (!open) {
      setQ("")
      setDebouncedQ("")
      return
    }
    const timer = window.setTimeout(() => setDebouncedQ(q.trim()), 280)
    return () => window.clearTimeout(timer)
  }, [q, open])

  const listQuery = useProductsListQuery(api, {
    page: 1,
    limit: 30,
    q: debouncedQ || undefined,
    enabled: open,
  })

  const items = useMemo(() => {
    const rows = listQuery.data?.items ?? []
    if (!excludeProductId) return rows
    return rows.filter((row) => row.id !== excludeProductId)
  }, [listQuery.data?.items, excludeProductId])

  return (
    <PanelDialog
      open={open}
      onOpenChange={onOpenChange}
      title={title}
      description="Chọn sản phẩm có sẵn trong kho làm quà tặng kèm."
      size="md"
      footer={
        <Button
          type="button"
          variant="outline"
          onClick={() => onOpenChange(false)}
        >
          Đóng
        </Button>
      }
    >
      <div className="space-y-4">
        <PanelDialogSearch
          id="product-catalog-picker-q"
          value={q}
          onChange={setQ}
          placeholder="Tìm theo tên hoặc SKU…"
        />

        <div className="max-h-[min(52vh,420px)] space-y-1 overflow-y-auto rounded-lg border bg-card p-1">
          {listQuery.isLoading ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              Đang tải…
            </p>
          ) : listQuery.isError ? (
            <p className="px-3 py-6 text-center text-sm text-destructive">
              Không tải được danh sách sản phẩm.
            </p>
          ) : items.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              Không có sản phẩm phù hợp.
            </p>
          ) : (
            items.map((product) => {
              const image = firstProductImage(product)
              const imageSrc = image ? resolveMediaUrl(image, 96) : ""
              return (
                <button
                  key={product.id}
                  type="button"
                  onClick={() => {
                    onSelect(product)
                    onOpenChange(false)
                  }}
                  className="flex w-full items-center gap-3 rounded-md px-2 py-2 text-left transition-colors hover:bg-muted/60"
                >
                  <div className="relative size-11 shrink-0 overflow-hidden rounded-md border bg-muted">
                    {imageSrc ? (
                      <img
                        src={imageSrc}
                        alt=""
                        className="size-full object-cover"
                        loading="lazy"
                        decoding="async"
                      />
                    ) : (
                      <div className="flex size-full items-center justify-center">
                        <Package
                          className="size-4 text-muted-foreground/50"
                          aria-hidden
                        />
                      </div>
                    )}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium">
                      {product.name}
                    </p>
                    <p className="truncate font-mono text-xs text-muted-foreground">
                      {product.sku}
                    </p>
                  </div>
                </button>
              )
            })
          )}
        </div>
      </div>
    </PanelDialog>
  )
}

export { firstProductImage }

"use client"

import { zodResolver } from "@hookform/resolvers/zod"
import { useForm, type UseFormReturn } from "react-hook-form"
import { z } from "zod"
import {
  AdminFormLayout,
  AdminFormMain,
  AdminFormPageHeader,
  AdminFormSidebar,
  ProductFormSidebar,
} from "@ui/components/admin"
import {
  FieldSet,
  FieldSetContent,
  FieldSectionLegend,
} from "@ui/components/field"
import type {
  CreateProductInput,
  Product,
  ProductGiftRule,
  ProductUnitType,
} from "@workspace/api-client"
import { productBaseStock } from "@workspace/api-client"
import {
  EMPTY_UNIT_ROW,
  formatImageUrls,
  parseImageUrls,
  type ProductFormValues,
  type ProductUnitFormRow,
} from "./types"
import { ProductUnitVariantsField } from "./product-unit-variants-field"

const unitRowSchema = z.object({
  type: z.string().min(1, "Bắt buộc"),
  label: z.string().min(1, "Bắt buộc"),
  sku: z.string(),
  retailPrice: z.string().min(1, "Bắt buộc"),
  wholesalePrice: z.string(),
  minWholesaleQty: z.string(),
  qtyPerUnit: z.string(),
  imageUrls: z.string(),
  tierMinQty: z.string(),
  tierUnitPrice: z.string(),
  tierLabel: z.string(),
  gifts: z.array(
    z.object({
      label: z.string(),
      minQty: z.string(),
      name: z.string(),
      sku: z.string(),
      qty: z.string(),
      image: z.string(),
      productId: z.string(),
      scope: z.enum(["line", "product"]),
    })
  ),
  isDefault: z.boolean(),
})

const schema = z.object({
  sku: z.string().min(1, "Bắt buộc"),
  name: z.string().min(1, "Bắt buộc"),
  category: z.string().min(1, "Bắt buộc"),
  description: z.string(),
  isActive: z.boolean(),
  fulfillmentNote: z.string(),
  baseStock: z.string(),
  units: z.array(unitRowSchema).min(1, "Cần ít nhất một loại hàng"),
})

function unitRowToApi(row: ProductUnitFormRow, index: number): ProductUnitType {
  const retail = Math.max(0, Math.floor(Number(row.retailPrice) || 0))
  const wholesaleRaw = Math.floor(Number(row.wholesalePrice) || 0)
  const wholesale = wholesaleRaw > 0 ? wholesaleRaw : null
  const minQ = Math.max(0, Math.floor(Number(row.minWholesaleQty) || 0))
  const images = parseImageUrls(row.imageUrls)

  const tierMin = Math.floor(Number(row.tierMinQty) || 0)
  const tierPrice = Math.floor(Number(row.tierUnitPrice) || 0)
  const priceTiers =
    tierMin > 0 && tierPrice > 0
      ? [
          {
            minQty: tierMin,
            unitPrice: tierPrice,
            label: row.tierLabel.trim() || undefined,
          },
        ]
      : undefined

  const giftRules: ProductGiftRule[] = []
  row.gifts.forEach((gift, giftIndex) => {
    const giftMin = Math.floor(Number(gift.minQty) || 0)
    const giftName = gift.name.trim()
    if (giftMin <= 0 || !giftName) return
    giftRules.push({
      id: `gift-${row.type.trim() || index}-${giftIndex}`,
      label: gift.label.trim() || giftName,
      trigger: { scope: gift.scope, minQty: giftMin },
      gift: {
        name: giftName,
        sku: gift.sku.trim() || undefined,
        productId: gift.productId.trim() ? Number(gift.productId) : undefined,
        qty: Math.max(1, Math.floor(Number(gift.qty) || 1)),
        image: gift.image.trim() || undefined,
        qtyMultiplier: "once",
      },
      applyPer: "order",
    })
  })
  const giftRulesOrUndefined = giftRules.length ? giftRules : undefined

  return {
    type: row.type.trim(),
    label: row.label.trim() || row.type.trim(),
    sku: row.sku.trim() || undefined,
    retailPrice: retail,
    wholesalePrice: wholesale,
    minWholesaleQty: minQ,
    qtyPerUnit: Math.max(1, Math.floor(Number(row.qtyPerUnit) || 1)),
    images: images.length ? images : undefined,
    priceTiers,
    giftRules: giftRulesOrUndefined,
    isDefault: row.isDefault,
    isActive: true,
  }
}

export function useProductForm(defaults?: Partial<ProductFormValues>) {
  const form = useForm<ProductFormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      sku: "",
      name: "",
      category: "general",
      description: "",
      isActive: true,
      fulfillmentNote: "",
      baseStock: "0",
      units: [{ ...EMPTY_UNIT_ROW }],
      ...defaults,
    },
  })
  return { form }
}

function unitToFormRow(
  unit: ProductUnitType,
  isDefault: boolean
): ProductUnitFormRow {
  const tier = unit.priceTiers?.[0]
  return {
    type: unit.type,
    label: unit.label,
    sku: unit.sku ?? "",
    retailPrice: String(unit.retailPrice ?? 0),
    wholesalePrice: String(unit.wholesalePrice ?? 0),
    minWholesaleQty: String(unit.minWholesaleQty ?? 0),
    qtyPerUnit: String(unit.qtyPerUnit ?? 1),
    imageUrls: formatImageUrls(unit.images),
    tierMinQty: tier ? String(tier.minQty) : "",
    tierUnitPrice: tier ? String(tier.unitPrice) : "",
    tierLabel: tier?.label ?? "",
    gifts: (unit.giftRules ?? []).map((gift) => ({
      label: gift.label ?? "",
      minQty: gift.trigger.minQty ? String(gift.trigger.minQty) : "",
      name: gift.gift.name ?? "",
      sku: gift.gift.sku ?? "",
      qty: String(gift.gift.qty ?? 1),
      image: gift.gift.image ?? "",
      productId: gift.gift.productId ? String(gift.gift.productId) : "",
      scope: gift.trigger.scope === "product" ? "product" : "line",
    })),
    isDefault,
  }
}

export function productToFormValues(product: Product): ProductFormValues {
  const units = product.unitTypes?.length
    ? product.unitTypes.map((u, i) => unitToFormRow(u, u.isDefault ?? i === 0))
    : [
        unitToFormRow(
          {
            type: product.unit,
            label: product.unit,
            retailPrice: product.retailPrice,
            wholesalePrice: product.wholesalePrice,
            minWholesaleQty: 0,
            qtyPerUnit: 1,
            images: product.images ?? undefined,
          },
          true
        ),
      ]

  if (!units.some((u) => u.isDefault)) {
    units[0] = { ...units[0]!, isDefault: true }
  }

  return {
    sku: product.sku,
    name: product.name,
    category: product.category,
    description: product.description ?? "",
    isActive: product.isActive,
    fulfillmentNote: product.fulfillmentNote ?? "",
    baseStock: String(productBaseStock(product)),
    units,
  }
}

export function buildProductPayload(
  values: ProductFormValues
): CreateProductInput {
  const unitTypes = values.units.map((row, index) => unitRowToApi(row, index))
  const defaultUnit = unitTypes.find((u) => u.isDefault) ?? unitTypes[0]!
  const allImages = unitTypes.flatMap((u) => u.images ?? [])
  const totalStock = Math.max(0, Math.floor(Number(values.baseStock) || 0))

  return {
    sku: values.sku.trim(),
    name: values.name.trim(),
    category: values.category.trim(),
    description: values.description?.trim() || null,
    basePrice: defaultUnit.retailPrice,
    retailPrice: defaultUnit.retailPrice,
    wholesalePrice: defaultUnit.wholesalePrice ?? 0,
    stock: totalStock,
    unit: defaultUnit.type,
    unitTypes,
    images: allImages.length ? [...new Set(allImages)] : null,
    fulfillmentNote: values.fulfillmentNote.trim() || null,
    isActive: values.isActive,
  }
}

export function ProductFormShell({
  form,
  onSubmit,
  submitting,
  editingId,
  onBack,
  onReset,
}: {
  form: UseFormReturn<ProductFormValues>
  onSubmit: (values: ProductFormValues) => Promise<void>
  submitting: boolean
  editingId: string | null
  onBack: () => void
  onReset: () => void
}) {
  const { register, watch, setValue } = form
  const isActive = watch("isActive")
  const units = watch("units") ?? []
  const baseStock = watch("baseStock")

  return (
    <>
      <AdminFormPageHeader
        title={editingId ? "Chỉnh sửa sản phẩm" : "Thêm sản phẩm"}
        subtitle="Mỗi loại hàng có giá, ảnh, tồn và quà tặng riêng — snapshot lúc checkout."
        onBack={onBack}
        onReset={onReset}
        formId="product-form"
        submitting={submitting}
        isEdit={!!editingId}
      />
      <AdminFormLayout id="product-form" onSubmit={form.handleSubmit(onSubmit)}>
        <AdminFormMain className="space-y-6">
          <FieldSet variant="section">
            <FieldSectionLegend
              title="Loại hàng (biến thể)"
              description="Giá, ảnh, tồn pool chung, bậc giá và quà tặng theo từng loại."
            />
            <FieldSetContent variant="section" className="pt-0">
              <ProductUnitVariantsField
                form={form}
                currentProductId={editingId}
              />
            </FieldSetContent>
          </FieldSet>
        </AdminFormMain>
        <AdminFormSidebar className="sticky top-2 max-h-[calc(100vh-80px)] overflow-y-auto">
          <ProductFormSidebar
            register={register}
            isActive={isActive}
            onIsActiveChange={(v) => setValue("isActive", v)}
            baseStock={baseStock}
            units={units}
          />
        </AdminFormSidebar>
      </AdminFormLayout>
    </>
  )
}

import { resolveStorageFolderSlugPath } from "@workspace/api-client"
import {
  createStorageFolder,
  fetchStorageFolders,
  type FolderItem,
} from "@workspace/admin-app/lib/admin-uploads"
import {
  extensionsFromGroupIds,
  getRealmDefaultGroupIds,
  resolveFolderPathAfterCreate,
} from "@workspace/admin-app/modules/file-storage/_component"

export const PRODUCT_IMAGE_PARENT_LABEL = "Sản phẩm"
export const PRODUCT_IMAGE_PARENT_SLUG = "san-pham"

export type ProductImageUploadInput = {
  productName?: string
  productSlug?: string
  productSku?: string
}

export type ProductImageUploadContext = {
  productName: string
  productSlug: string
  productSku?: string
  folderLabel: string
}

function leafSlugFromText(input: string): string {
  const from = resolveStorageFolderSlugPath(input.trim())
  if (!from?.slugPath) return ""
  const parts = from.slugPath.split("/").filter(Boolean)
  return parts[parts.length - 1] ?? ""
}

export function resolveProductImageSlug(
  productName: string,
  productSlug?: string,
  productSku?: string
): string {
  const explicit = productSlug?.trim()
  if (explicit) return explicit

  const fromName = leafSlugFromText(productName)
  if (fromName) return fromName

  return leafSlugFromText(productSku ?? "")
}

/** Đọc trực tiếp từ form — tránh `watch` trong dialog bị stale. */
export function buildProductImageUploadContext(
  input: ProductImageUploadInput
): ProductImageUploadContext | null {
  const name = input.productName?.trim() ?? ""
  const sku = input.productSku?.trim() ?? ""
  const folderLabel = name || sku
  const slug = resolveProductImageSlug(name, input.productSlug, sku)

  if (!folderLabel || !slug) return null

  return {
    productName: name || folderLabel,
    productSlug: slug,
    productSku: sku || undefined,
    folderLabel,
  }
}

export function resolveProductImageFolderNav(
  productName: string,
  productSlug?: string,
  productSku?: string
): { navPath: string; slug: string; label: string } | null {
  const ctx = buildProductImageUploadContext({
    productName,
    productSlug,
    productSku,
  })
  if (!ctx) return null
  return {
    navPath: `${PRODUCT_IMAGE_PARENT_SLUG}/${ctx.productSlug}`,
    slug: ctx.productSlug,
    label: ctx.folderLabel,
  }
}

function folderNavPath(folder: FolderItem): string {
  return resolveFolderPathAfterCreate(folder.path.replace(/\\/g, "/"), "images")
}

export function folderMatchesProductImage(
  folder: FolderItem,
  slug: string
): boolean {
  const nav = folderNavPath(folder)
  if (nav === `${PRODUCT_IMAGE_PARENT_SLUG}/${slug}`) return true
  if (!nav.startsWith(`${PRODUCT_IMAGE_PARENT_SLUG}/`)) return false
  const leaf = nav.split("/").pop()
  return leaf === slug
}

export function findProductImageFolder(
  folders: FolderItem[],
  input: ProductImageUploadInput
): { navPath: string; uploadFolderPath: string } | null {
  const resolved = resolveProductImageFolderNav(
    input.productName ?? "",
    input.productSlug,
    input.productSku
  )
  if (!resolved) return null
  const match = folders.find((folder) =>
    folderMatchesProductImage(folder, resolved.slug)
  )
  if (!match) return null
  const navPath = folderNavPath(match)
  return { navPath, uploadFolderPath: navPath }
}

async function ensureProductImageParentFolder(
  folders: FolderItem[]
): Promise<void> {
  const parentExists = folders.some((folder) => {
    const nav = folderNavPath(folder)
    return nav === PRODUCT_IMAGE_PARENT_SLUG
  })
  if (parentExists) return

  await createStorageFolder({
    folderName: PRODUCT_IMAGE_PARENT_LABEL,
    parentPath: "images",
    resourceType: "images",
    allowedExtensions: extensionsFromGroupIds(
      "images",
      getRealmDefaultGroupIds("images")
    ),
  })
}

/** Tạo hoặc tái sử dụng folder ảnh chính của sản phẩm dưới «Sản phẩm». */
export async function ensureProductImageFolder(
  input: ProductImageUploadInput
): Promise<{ navPath: string; uploadFolderPath: string; created: boolean }> {
  const resolved = resolveProductImageFolderNav(
    input.productName ?? "",
    input.productSlug,
    input.productSku
  )
  if (!resolved) {
    throw new Error(
      "Nhập tên hoặc SKU sản phẩm ở form — hệ thống cần tạo slug folder lưu ảnh"
    )
  }

  let folders = await fetchStorageFolders()
  const existing = findProductImageFolder(folders, input)
  if (existing) {
    return { ...existing, created: false }
  }

  await ensureProductImageParentFolder(folders)
  folders = await fetchStorageFolders()

  const parentFolder = folders.find(
    (folder) => folderNavPath(folder) === PRODUCT_IMAGE_PARENT_SLUG
  )
  const parentDisk =
    parentFolder?.path.replace(/\\/g, "/") ??
    `images/${PRODUCT_IMAGE_PARENT_SLUG}`

  const created = await createStorageFolder({
    folderName: resolved.label,
    parentPath: parentDisk,
    resourceType: "images",
  })

  const navPath = resolveFolderPathAfterCreate(created.folderPath, "images")
  return {
    navPath,
    uploadFolderPath: navPath,
    created: true,
  }
}

"use client"

import { useState } from "react"
import {
  Controller,
  useFieldArray,
  useWatch,
