"use client"

import { useRef, useState } from "react"
import type { UseFormReturn } from "react-hook-form"
import { toast } from "@ui/components/sonner"
import { formatAdminOperationErrorDetails } from "@ui/lib/admin-operation-toast"
import { getStudentCodeAvatarUploadBlockReason } from "@workspace/admin-app/lib/student-code-form"
import { useAdminApi } from "@workspace/admin-app/runtime"

import type { StaffFormValues } from "./staff-form.schema"

type UseStaffAvatarUploadOptions = {
  form: UseFormReturn<StaffFormValues>
  subjectUserId?: string
}

export function useStaffAvatarUpload(options: UseStaffAvatarUploadOptions) {
  const api = useAdminApi()
  const { form, subjectUserId } = options
  const [uploadingAvatar, setUploadingAvatar] = useState(false)
  const avatarInputRef = useRef<HTMLInputElement>(null)
  const avatarValue = form.watch("avatar")

  const handleUploadAvatar = async (file: File) => {
    if (!subjectUserId) {
      toast.error("Tạo tài khoản trước khi tải ảnh đại diện.")
      return
    }

    const blockReason = getStudentCodeAvatarUploadBlockReason({
      studentCode: form.getValues("studentCode") ?? "",
      studentCodeDirty: Boolean(form.formState.dirtyFields.studentCode),
    })
    if (blockReason) {
      toast.error(blockReason)
      return
    }

    setUploadingAvatar(true)
    try {
      const url = (await api.users.uploadAvatar(subjectUserId, file)).url
      form.setValue("avatar", url, { shouldDirty: true })
      toast.success("Đã tải ảnh đại diện", {
        description: [
          `User ID: ${subjectUserId}`,
          `File: ${file.name}`,
          `URL: ${url}`,
        ].join("\n"),
      })
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Lỗi upload ảnh", {
        description: formatAdminOperationErrorDetails(error),
      })
    } finally {
      setUploadingAvatar(false)
    }
  }

  return {
    uploadingAvatar,
    avatarInputRef,
    avatarValue,
    handleUploadAvatar,
  }
}

import { useCallback } from "react"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"

import type { StaffRow } from "../types"
import {
  buildStaffSubmitPayload,
  type StaffSubmitPayload,
} from "../staff-form.types"
import {
  STAFF_FORM_DEFAULT_VALUES,
  staffFormSchema,
  type StaffFormValues,
} from "./staff-form.schema"

export {
  staffFormSchema,
  STAFF_FORM_DEFAULT_VALUES,
  type StaffFormValues,
} from "./staff-form.schema"

interface UseStaffFormOptions {
  editingId?: string | null
}

export function mapStaffUserToFormValues(user: StaffRow): StaffFormValues {
  return {
    email: user.email,
    fullName: user.fullName,
    password: "",
    isActive: user.isActive,
    roleCodes: user.roles.map((role) => role.code),
    avatar: user.avatar ?? "",
    phone: user.phone ?? "",
    address: user.address ?? "",
    citizenId: user.citizenId ?? "",
    studentCode: user.studentCode ?? "",
  }
}

export function useStaffForm(options: UseStaffFormOptions = {}) {
  const { editingId } = options

  const form = useForm<StaffFormValues>({
    resolver: zodResolver(staffFormSchema),
    defaultValues: STAFF_FORM_DEFAULT_VALUES,
    mode: "onChange",
  })

  const resetForm = useCallback(() => {
    form.reset(STAFF_FORM_DEFAULT_VALUES)
  }, [form])

  const populateForm = useCallback(
    (user: StaffRow) => {
      form.reset(mapStaffUserToFormValues(user))
    },
    [form],
  )

  const toggleRole = useCallback(
    (code: string, checked: boolean) => {
      const currentRoles = form.getValues("roleCodes")
      if (checked) {
        form.setValue("roleCodes", [...new Set([...currentRoles, code])], {
          shouldDirty: true,
        })
      } else {
        form.setValue(
          "roleCodes",
          currentRoles.filter((roleCode) => roleCode !== code),
          { shouldDirty: true },
        )
      }
    },
    [form],
  )

  const getPayload = useCallback((): StaffSubmitPayload => {
    return buildStaffSubmitPayload(form.getValues(), editingId)
  }, [form, editingId])

  return {
    form,
    resetForm,
    populateForm,
    toggleRole,
    getPayload,
  }
}

