export {
  useColumnFiltersChange,
  useClearListFilters,
  useClearTrashFilters,
} from "@workspace/admin-app/hooks/use-table-filters"
export {
  buildTrainingLevelPayload,
  useTrainingLevelForm,
  useHandleConfirmAction,
  useConfirmAction,
} from "./use-training-levels-actions"

import { useCallback, useState } from "react"
import { useForm } from "react-hook-form"
import type { UseMutationResult } from "@tanstack/react-query"
import type {
  TrainingLevelConfirmAction,
  TrainingLevelFormValues,
} from "../types"
import { entityFormSchema } from "../types"
import { zodResolver } from "@hookform/resolvers/zod"

const EMPTY_VALUES: TrainingLevelFormValues = { name: "", code: "", status: 1 }

export function buildTrainingLevelPayload(
  values: TrainingLevelFormValues
): Record<string, unknown> {
  return {
    name: values.name.trim(),
    code: values.code?.trim() || null,
    status: values.status,
  }
}

export function useTrainingLevelForm() {
  const form = useForm<TrainingLevelFormValues>({
    resolver: zodResolver(entityFormSchema),
    defaultValues: EMPTY_VALUES,
  })
  const resetForm = useCallback(() => {
    form.reset(EMPTY_VALUES)
  }, [form])
  return { form, resetForm }
}

export function useHandleConfirmAction(
  deleteMutation: UseMutationResult<unknown, Error, string>,
  restoreMutation: UseMutationResult<unknown, Error, string>,
  purgeMutation: UseMutationResult<unknown, Error, string>,
  setConfirmAction: React.Dispatch<
    React.SetStateAction<TrainingLevelConfirmAction | null>
  >
) {
  return useCallback(
    async ({ kind, row }: TrainingLevelConfirmAction) => {
      try {
        if (kind === "delete") {
          await deleteMutation.mutateAsync(row.id)
        } else if (kind === "restore") {
          await restoreMutation.mutateAsync(row.id)
        } else if (kind === "purge") {
          await purgeMutation.mutateAsync(row.id)
        }
      } catch {
        /* toast: MutationCache */
      } finally {
        setConfirmAction(null)
      }
    },
    [deleteMutation, restoreMutation, purgeMutation, setConfirmAction]
  )
}

export function useConfirmAction() {
  const [confirmAction, setConfirmAction] =
    useState<TrainingLevelConfirmAction | null>(null)
  return { confirmAction, setConfirmAction }
}

import { api } from "@workspace/admin-app/lib/api"
import {
  adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@workspace/admin-app/lib/admin-detail-query"
import type { UseQueryResult } from "@tanstack/react-query"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@workspace/admin-app/lib/fetch-all-admin-list"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk, PagedResult } from "@workspace/api-client"
import type { TrainingLevelDetail, TrainingLevelRow } from "../types"

export const trainingLevelDetailQueryKey = (id: string) =>
  ["training-levels", "detail", id] as const

export function prefetchTrainingLevelDetail(
  queryClient: QueryClient,
  api: StoreSyncSdk,
  id: string
) {
  return prefetchAdminDetailQuery(
    queryClient,
    trainingLevelDetailQueryKey(id),
    () => api.trainingLevels.get<TrainingLevelDetail>(id)
  )
}

export function useTrainingLevelDetailQuery(api: StoreSyncSdk, id: string) {
  return useQuery({
    ...adminDetailQueryOptions(
      trainingLevelDetailQueryKey(id),
      async () => api.trainingLevels.get<TrainingLevelDetail>(id),
      id
    ),
  })
}

export function useTrainingLevelsListQuery(
  apiParam: StoreSyncSdk,
  enabled: boolean,
  filters?: Record<string, string>
): UseQueryResult<TrainingLevelRow[]> {
  return useQuery({
    queryKey: ["training-levels", "list", filters],
    queryFn: async (): Promise<TrainingLevelRow[]> => {
      const limit = ADMIN_LIST_EXPORT_FETCH_LIMIT
      const items: TrainingLevelRow[] = []
      let page = 1
      let total = Number.POSITIVE_INFINITY

      while (items.length < total) {
        const result = await apiParam.trainingLevels.list<TrainingLevelRow>({
          page,
          limit,
          status: "active",
          filters,
        })
        items.push(...result.items)
        total = result.total
        if (result.items.length === 0) break
        page += 1
      }

      return items
    },
    enabled,
  })
}

export interface UseTrashQueryProps {
  api: StoreSyncSdk
  trashPage: number
  trashPageSize: number
  debouncedTrashQ: string
  enabled: boolean
}

export function useTrainingLevelsTrashQuery({
  api: apiParam,
  trashPage,
  trashPageSize,
  debouncedTrashQ,
  enabled,
  filters,
}: UseTrashQueryProps & { filters?: Record<string, string> }): UseQueryResult<
  PagedResult<TrainingLevelRow>
> {
  return useQuery({
    queryKey: [
      "training-levels",
      "trash",
      trashPage,
      trashPageSize,
      debouncedTrashQ,
      filters,
    ],
    enabled,
    queryFn: async (): Promise<PagedResult<TrainingLevelRow>> => {
      return apiParam.trainingLevels.list<TrainingLevelRow>({
        page: trashPage,
        limit: trashPageSize,
        search: debouncedTrashQ.trim() || undefined,
        status: "deleted",
        ...filters,
      })
    },
  })
}

"use client"

import type {
  ColumnDef,
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"
import type { TrainingLevelRow } from "../types"
import { buildAdminTableXlsxExport } from "@ui/components/admin"

export interface TrainingLevelsTableProps {
  data: TrainingLevelRow[]
  columns: ColumnDef<TrainingLevelRow>[]
  isLoading: boolean
  columnFilters: ColumnFiltersState
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  total: number
  onClearFilters: () => void
  onBulkDelete: (rows: TrainingLevelRow[]) => Promise<void>
  onBulkPurge: (rows: TrainingLevelRow[]) => Promise<void>
  onRowPrefetch?: (row: TrainingLevelRow) => void
}

export function TrainingLevelsTable({
  data,
  columns,
  isLoading,
  columnFilters,
  onColumnFiltersChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  total,
  onClearFilters,
  onBulkDelete,
  onBulkPurge,
  onRowPrefetch,
}: TrainingLevelsTableProps) {
  return (
    <AdminDataTable<TrainingLevelRow>
      tableScope="training-levels"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel='Chưa có bậc học — bấm "Thêm bậc học".'
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm theo tên hoặc mã..."
      onClearFilters={onClearFilters}
      onRowPointerEnter={
        onRowPrefetch ? (row) => onRowPrefetch(row.original) : undefined
      }
      xlsxExport={buildAdminTableXlsxExport("training-levels", {
        pageCount: data.length,
        total,
      })}
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        {
          id: "bulk-training-level-delete",
          label: "Xóa tạm đã chọn",
          variant: "destructive",
          confirm: {
            title: "Đưa các bậc học đã chọn vào thùng rác?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} bậc học. Các bậc học sẽ được chuyển vào thùng rác và có thể khôi phục sau.`,
            confirmLabel: "Xóa tạm",
            destructive: true,
          },
          onAction: onBulkDelete,
        },
        {
          id: "bulk-training-level-purge",
          label: "Xóa vĩnh viễn đã chọn",
          variant: "destructive",
          confirm: {
            title: "Xóa vĩnh viễn các bậc học đã chọn?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} bậc học. Hành động này không thể hoàn tác!`,
            confirmLabel: "Xóa vĩnh viễn",
            destructive: true,
          },
          onAction: onBulkPurge,
        },
      ]}
      footer={
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            {isLoading ? "Đang tải..." : `Tổng ${total} bậc học`}
          </p>
        </div>
      }
    />
  )
}

"use client"

import type {
  ColumnDef,
  ColumnFiltersState,
  OnChangeFn,
  RowSelectionState,
} from "@tanstack/react-table"
import {
  AdminDataTable,
  adminTableRowSelectionProps,
} from "@ui/components/data-table"
import type { TrainingLevelRow } from "../types"
import { buildAdminTableXlsxExport } from "@ui/components/admin"
import { api } from "@workspace/admin-app/lib/api"
import {
  createAdminTrashExportFetchPage,
  type AdminTrashExportParams,
} from "@workspace/admin-app/lib/admin-trash-export"

export interface TrainingLevelsTrashTableProps {
  data: TrainingLevelRow[]
  columns: ColumnDef<TrainingLevelRow>[]
  isLoading: boolean
  columnFilters: ColumnFiltersState
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>
  globalFilter: string
  onGlobalFilterChange: OnChangeFn<string>
  selectedRowIds: RowSelectionState
  onSelectedRowIdsChange: OnChangeFn<RowSelectionState>
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
  onClearFilters: () => void
  onBulkRestore: (rows: TrainingLevelRow[]) => Promise<void>
  onBulkPurge: (rows: TrainingLevelRow[]) => Promise<void>
  trashExportParams?: AdminTrashExportParams
}

export function TrainingLevelsTrashTable({
  data,
  columns,
  isLoading,
  columnFilters,
  onColumnFiltersChange,
  globalFilter,
  onGlobalFilterChange,
  selectedRowIds,
  onSelectedRowIdsChange,
  page,
  pageSize,
  total,
  onPageChange,
  onPageSizeChange,
  onClearFilters,
  onBulkRestore,
  onBulkPurge,
  trashExportParams,
}: TrainingLevelsTrashTableProps) {
  return (
    <AdminDataTable<TrainingLevelRow>
      tableScope="training-levels-trash"
      data={data}
      getRowId={(row) => row.id}
      columns={columns}
      isLoading={isLoading}
      emptyLabel="Thùng rác trống."
      manualFiltering
      columnFilters={columnFilters}
      onColumnFiltersChange={onColumnFiltersChange}
      globalFilter={globalFilter}
      onGlobalFilterChange={onGlobalFilterChange}
      globalFilterPlaceholder="Tìm trong thùng rác..."
      onClearFilters={onClearFilters}
      clearFiltersVariant="destructive"
      xlsxExport={buildAdminTableXlsxExport("training-levels-trash", {
        pageCount: data.length,
        total,
      })}
      exportFetchPage={
        trashExportParams
          ? createAdminTrashExportFetchPage<TrainingLevelRow>(
              (params) => api.trainingLevels.list<TrainingLevelRow>(params),
              trashExportParams
            )
          : undefined
      }
      {...adminTableRowSelectionProps(selectedRowIds, onSelectedRowIdsChange)}
      bulkActions={[
        {
          id: "bulk-training-level-restore",
          label: "Khôi phục đã chọn",
          variant: "default",
          confirm: {
            title: "Khôi phục các bậc học đã chọn?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} bậc học. Các bậc học sẽ được đưa trở lại danh sách đang hoạt động.`,
            confirmLabel: "Khôi phục",
          },
          onAction: onBulkRestore,
        },
        {
          id: "bulk-training-level-purge",
          label: "Xóa vĩnh viễn đã chọn",
          variant: "destructive",
          confirm: {
            title: "Xóa vĩnh viễn các bậc học đã chọn?",
            description: (rows) =>
              `Bạn đã chọn ${rows.length} bậc học. Hành động này không thể hoàn tác.`,
            confirmLabel: "Xóa vĩnh viễn",
            destructive: true,
          },
          onAction: onBulkPurge,
        },
      ]}
      pagination={{
        page,
        pageSize,
        total,
        isLoading,
        onPageChange,
        onPageSizeChange,
        emptySummary: "Không có bậc học trong thùng rác",
        itemLabel: "bậc học",
      }}
    />
  )
}

