import { useCallback, useState } from "react"
import { useForm } from "react-hook-form"
import type { UseMutationResult } from "@tanstack/react-query"
import type {
  TrainingSystemConfirmAction,
  TrainingSystemFormValues,
} from "../types"
import { entityFormSchema } from "../types"
import { zodResolver } from "@hookform/resolvers/zod"

const EMPTY_VALUES: TrainingSystemFormValues = { name: "", code: "", status: 1 }

export function buildTrainingSystemPayload(
  values: TrainingSystemFormValues
): Record<string, unknown> {
  return {
    name: values.name.trim(),
    code: values.code?.trim() || null,
    status: values.status,
  }
}

export function useTrainingSystemForm() {
  const form = useForm<TrainingSystemFormValues>({
    resolver: zodResolver(entityFormSchema),
    defaultValues: EMPTY_VALUES,
  })
  const resetForm = useCallback(() => {
    form.reset(EMPTY_VALUES)
  }, [form])
  return { form, resetForm }
}

export function useHandleConfirmAction(
  deleteMutation: UseMutationResult<unknown, Error, string>,
  restoreMutation: UseMutationResult<unknown, Error, string>,
  purgeMutation: UseMutationResult<unknown, Error, string>,
  setConfirmAction: React.Dispatch<
    React.SetStateAction<TrainingSystemConfirmAction | null>
  >
) {
  return useCallback(
    async ({ kind, row }: TrainingSystemConfirmAction) => {
      try {
        if (kind === "delete") {
          await deleteMutation.mutateAsync(row.id)
        } else if (kind === "restore") {
          await restoreMutation.mutateAsync(row.id)
        } else if (kind === "purge") {
          await purgeMutation.mutateAsync(row.id)
        }
      } catch {
        /* toast: MutationCache */
      } finally {
        setConfirmAction(null)
      }
    },
    [deleteMutation, restoreMutation, purgeMutation, setConfirmAction]
  )
}

export function useConfirmAction() {
  const [confirmAction, setConfirmAction] =
    useState<TrainingSystemConfirmAction | null>(null)
  return { confirmAction, setConfirmAction }
}

import { api } from "@workspace/admin-app/lib/api"
import {
  adminDetailQueryOptions,
  prefetchAdminDetailQuery,
} from "@workspace/admin-app/lib/admin-detail-query"
import type { UseQueryResult } from "@tanstack/react-query"
import { ADMIN_LIST_EXPORT_FETCH_LIMIT } from "@workspace/admin-app/lib/fetch-all-admin-list"
import { useQuery, type QueryClient } from "@tanstack/react-query"
import type { StoreSyncSdk, PagedResult } from "@workspace/api-client"
import type { TrainingSystemDetail, TrainingSystemRow } from "../types"

export const trainingSystemDetailQueryKey = (id: string) =>
  ["training-systems", "detail", id] as const

export function prefetchTrainingSystemDetail(
  queryClient: QueryClient,
  api: StoreSyncSdk,
  id: string
) {
  return prefetchAdminDetailQuery(
    queryClient,
    trainingSystemDetailQueryKey(id),
    () => api.trainingSystems.get<TrainingSystemDetail>(id)
  )
}

export function useTrainingSystemDetailQuery(api: StoreSyncSdk, id: string) {
  return useQuery({
    ...adminDetailQueryOptions(
      trainingSystemDetailQueryKey(id),
      async () => api.trainingSystems.get<TrainingSystemDetail>(id),
      id
    ),
  })
}

export function useTrainingSystemsListQuery(
  apiParam: StoreSyncSdk,
  enabled: boolean,
  filters?: Record<string, string>
): UseQueryResult<TrainingSystemRow[]> {
  return useQuery({
    queryKey: ["training-systems", "list", filters],
    queryFn: async (): Promise<TrainingSystemRow[]> => {
      const limit = ADMIN_LIST_EXPORT_FETCH_LIMIT
      const items: TrainingSystemRow[] = []
      let page = 1
      let total = Number.POSITIVE_INFINITY

      while (items.length < total) {
        const result = await apiParam.trainingSystems.list<TrainingSystemRow>({
          page,
          limit,
          status: "active",
          filters,
        })
        items.push(...result.items)
        total = result.total
        if (result.items.length === 0) break
        page += 1
      }

      return items
    },
    enabled,
  })
}

export interface UseTrashQueryProps {
  api: StoreSyncSdk
  trashPage: number
  trashPageSize: number
  debouncedTrashQ: string
  enabled: boolean
}

export function useTrainingSystemsTrashQuery({
  api: apiParam,
  trashPage,
  trashPageSize,
  debouncedTrashQ,
  enabled,
  filters,
}: UseTrashQueryProps & { filters?: Record<string, string> }): UseQueryResult<
  PagedResult<TrainingSystemRow>
> {
  return useQuery({
    queryKey: [
      "training-systems",
      "trash",
      trashPage,
      trashPageSize,
      debouncedTrashQ,
      filters,
    ],
    enabled,
    queryFn: async (): Promise<PagedResult<TrainingSystemRow>> => {
      return apiParam.trainingSystems.list<TrainingSystemRow>({
        page: trashPage,
        limit: trashPageSize,
        search: debouncedTrashQ.trim() || undefined,
        status: "deleted",
        ...filters,
      })
    },
  })
}

